  'legalTermsTitle': 'Terms & Conditions',
  'legalPrivacyTitle': 'Privacy Policy',
  'legalLastUpdatedDate': 'September 4, 2026',
  'legalTerms1Heading': '1. Agreement to these Terms',
  'legalTerms1Body': 'These Terms & Conditions (“Terms”) govern your use of the WWNGO mobile application and related services (the “Platform”). WWNGO is a peer-to-peer marketplace that connects Senders who need a parcel moved, Travelers who are already going that way, and Receivers who accept the parcel at destination. By creating an account and checking “I agree to the Terms and Privacy Policy,” you enter a binding agreement with WWNGO. If you do not agree, do not register or use the Platform.',
  'legalTerms2Heading': '2. What WWNGO is — and is not',
  'legalTerms2Body': 'WWNGO facilitates matching, in-app chat, meetup coordination, identity checks, wallet payments, escrow, NFC handoff confirmation, tracking, ratings, and dispute review. WWNGO is not a courier, postal operator, freight forwarder, customs broker, insurer, or employer of Travelers. Delivery is performed by independent users. WWNGO does not take possession of parcels except as needed to operate the Platform (for example storing photos you upload).',
  'legalTerms3Heading': '3. Eligibility and accounts',
  'legalTerms3Bullet1': 'You must be at least 18 years old and able to form a binding contract.',
  'legalTerms3Bullet2': 'You must provide accurate name, email, phone, country, and password, and keep them up to date.',
  'legalTerms3Bullet3': 'One person may use a single WWNGO account as Sender, Traveler, and/or Receiver. These Terms apply to every role you use.',
  'legalTerms3Bullet4': 'Email and phone verification, and identity verification (KYC) through our partner Sumsub, are required before posting deliveries, listing trips, bidding, accepting parcels, or moving money.',
  'legalTerms3Bullet5': 'You are responsible for activity on your account. Do not share login credentials. Notify support@wwngo.com if you suspect unauthorized access.',
  'legalTerms4Heading': '4. Sender responsibilities',
  'legalTerms4Body': 'When you act as a Sender you post a delivery request (city-to-city or country-to-country), describe the parcel, set a budget, add photos, and name a Receiver. You agree to:',
  'legalTerms4Bullet1': 'Provide truthful parcel category, size, weight, contents description, route, travel date, and meetup preferences.',
  'legalTerms4Bullet2': 'Only send items that are legal to possess and transport on the chosen route, including customs and airline rules for international trips.',
  'legalTerms4Bullet3': 'Never list prohibited, dangerous, or illegal goods (see Section 10).',
  'legalTerms4Bullet4': 'Fund escrow for the agreed traveler payout when you accept a bid or counter-offer, and pay your Sender platform fee at Pay Now (\$2 for Document and Object, or \$3 when you cover the receiver\'s fee). Traveler and Receiver platform fees are also collected at Pay Now (wallet first, then card).',
  'legalTerms4Bullet5': 'Meet the Traveler at the agreed origin meetup location and complete NFC Checkpoint 1 (Sender ↔ Traveler) to confirm handoff.',
  'legalTerms4Bullet6': 'Communicate only through WWNGO chat for the delivery, and honor cancellations and timers described in the app.',
  'legalTerms5Heading': '5. Traveler responsibilities',
  'legalTerms5Body': 'When you act as a Traveler you list a trip, review matching parcel requests, accept or counter offers, and carry the parcel on your journey. You agree to:',
  'legalTerms5Bullet1': 'Post accurate origin, destination, travel date, and capacity, and only accept parcels you can legally and safely carry.',
  'legalTerms5Bullet2': 'Pay applicable Traveler platform fees (\$3 for Document and Object) from your wallet (or card if needed) when the Sender completes Pay Now.',
  'legalTerms5Bullet3': 'Confirm or propose meetup locations, complete NFC Checkpoint 1 with the Sender, keep the parcel secure in transit, and complete NFC Checkpoint 2 (Traveler ↔ Receiver) at destination.',
  'legalTerms5Bullet4': 'Not open, use, swap, or abandon a parcel, and not subcontract the delivery outside WWNGO.',
  'legalTerms5Bullet5': 'Update shipment status in good faith (for example starting transit) and respond promptly in chat.',
  'legalTerms5Bullet6': 'Comply with airline, border, and customs declarations. You are responsible for what you physically carry.',
  'legalTerms6Heading': '6. Receiver responsibilities',
  'legalTerms6Body': 'When you act as a Receiver you are named on a delivery, accept the incoming request, and take the parcel at destination. You agree to:',
  'legalTerms6Bullet1': 'Review parcel details before accepting. Accepting is consent only — a Receiver platform fee (\$2 for Document and Object) is charged at sender Pay Now unless the sender covers it.',
  'legalTerms6Bullet2': 'Be available at the destination meetup, verify the parcel, and complete NFC Checkpoint 2 (Traveler ↔ Receiver) to confirm delivery.',
  'legalTerms6Bullet3': 'Raise a dispute in-app promptly if the parcel is missing, damaged, or not as described, instead of completing NFC confirmation if you do not accept the goods.',
  'legalTerms6Bullet4': 'Keep contact details accurate so the Sender and Traveler can coordinate.',
  'legalTerms7Heading': '7. Matching, bids, and booking',
  'legalTerms7Body': 'Senders may discover travelers and send requests. Travelers may receive matching requests, accept, decline, or send a counter-offer. A booking is created only when the Sender accepts a price, required KYC and verification are complete, escrow is successfully funded, and platform fees are collected as displayed. Selection of a Traveler locks the booking. If a payment window or accept timer expires, the booking may auto-cancel and escrow principal is refunded according to Section 12.',
  'legalTerms8Heading': '8. Meetup locations and chat',
  'legalTerms8Body': 'Parties coordinate a public, appropriate meetup using in-app location tools. A meetup is confirmed when the required parties accept it in the app. Chat between Sender–Traveler, Sender–Receiver, and Traveler–Receiver unlocks according to delivery status. Do not share payment details off-platform or move the deal outside WWNGO. Off-platform payments void escrow protection.',
  'legalTerms9Heading': '9. NFC checkpoints and delivery confirmation',
  'legalTerms9Bullet1': 'NFC Checkpoint 1 (Sender ↔ Traveler) confirms the Sender handed the parcel to the Traveler.',
  'legalTerms9Bullet2': 'NFC Checkpoint 2 (Traveler ↔ Receiver) confirms the Receiver received the parcel. Both parties must complete their tap. Successful Checkpoint 2 marks the shipment Delivered and releases escrow to the Traveler (unless frozen by a dispute).',
  'legalTerms9Bullet3': 'NFC is a confirmation tool, not a guarantee of parcel condition. Photos, chat, tracking, and dispute records may still be used in a review.',
  'legalTerms9Bullet4': 'Misusing NFC (confirming without a real handoff, coercing a tap, or spoofing devices) is grounds for suspension and escrow freeze.',
  'legalTerms10Heading': '10. Prohibited items and zero-tolerance conduct',
  'legalTerms10Body': 'You must not send, carry, or request: illegal drugs, weapons, explosives, hazardous materials, stolen goods, counterfeit items, cash or bearer instruments beyond what local law allows, live animals, human remains, or any item banned by the carrier, airline, or destination country. Fraud, fake identity, fake photos, harassment, rating manipulation, and attempts to bypass escrow are forbidden. WWNGO may suspend accounts, freeze escrow, and report illegal activity to authorities.',
  'legalTerms11Heading': '11. Payments, wallets, and escrow',
  'legalTerms11Bullet1': 'You have one WWNGO wallet shared across Sender, Traveler, and Receiver activity. Top up with Stripe and withdraw via Stripe Connect once a payout account is linked and ready. Transaction history records which role each entry relates to.',
  'legalTerms11Bullet2': 'When a Sender accepts a Traveler, the agreed payout is moved from the Sender\'s available balance into escrow (card payment may cover a shortfall). Escrow is not withdrawable by any party until release, refund, or a dispute decision.',
  'legalTerms11Bullet3': 'Platform fees (Sender, Traveler, and/or Receiver, including optional Sender-covers-Receiver-fee) are disclosed before you confirm and are charged as shown.',
  'legalTerms11Bullet4': 'Escrow is released to the Traveler after NFC Checkpoint 2 / Delivered, unless frozen. WWNGO is not a bank; wallet balances are Platform records used to settle marketplace transactions.',
  'legalTerms12Heading': '12. Cancellations and refunds',
  'legalTerms12Body': 'Booked deliveries may be cancelled before the trip is in transit or delivered, subject to in-app rules. Escrow principal is refunded to the Sender. Platform fees are refunded to the paying parties if cancellation is more than 24 hours before travel; within 24 hours, platform fees are generally non-refundable. Posted deliveries that are not yet booked may be cancelled under the posting rules in the app. Auto-cancel (for example unpaid Receiver windows or expired accept timers) refunds escrow principal as stated in the product. Top-ups and completed payouts are not reversed except as required by law or a formal dispute outcome.',
  'legalTerms13Heading': '13. Tracking, photos, and reviews',
  'legalTerms13Body': 'Status updates, parcel photos, and GPS or meetup data you provide are used to operate the delivery. After delivery, parties may leave reviews. Reviews must be honest and about the transaction. WWNGO may hide or remove abusive or fake reviews.',
  'legalTerms14Heading': '14. Disputes',
  'legalTerms14Body': 'If something goes wrong (damage, non-delivery, wrong item, NFC dispute), file a dispute in the app. Filing a dispute freezes escrow while WWNGO reviews delivery records, photos, chat, NFC checkpoints, and identity data. Do not complete NFC Checkpoint 2 if you intend to dispute receipt. WWNGO\'s decision on escrow (release, refund, or split) is final as between the parties on the Platform, without limiting any rights you may have against another user in a court of competent jurisdiction. Chargebacks or off-platform claims may still result in account action.',
  'legalTerms15Heading': '15. Limitation of liability',
  'legalTerms15Body': 'To the maximum extent permitted by law, WWNGO is not liable for loss, delay, damage, seizure, or customs issues caused by users, carriers, or governments; for the acts of Senders, Travelers, or Receivers; or for indirect, incidental, or consequential damages. Our total liability to you for a claim relating to the Platform is limited to the greater of (a) the platform fees you paid to WWNGO for the delivery in dispute in the 12 months before the claim, or (b) USD 50. Nothing in these Terms excludes liability that cannot legally be excluded (including for fraud or death/personal injury caused by negligence where such exclusion is forbidden).',
  'legalTerms16Heading': '16. Changes, suspension, and contact',
  'legalTerms16Body': 'We may update these Terms. Continued use after an in-app notice constitutes acceptance of the revised Terms. We may suspend or terminate accounts that violate these Terms. Questions: support@wwngo.com. These Terms are the entire agreement for your use of the Platform and are governed by the laws applicable to WWNGO\'s place of establishment, without prejudice to mandatory consumer protections in your country of residence.',
  'legalPrivacy1Heading': '1. Introduction',
  'legalPrivacy1Body': 'This Privacy Policy explains how WWNGO collects, uses, shares, and protects personal data when you use our peer-to-peer parcel marketplace as a Sender, Traveler, and/or Receiver. It applies to first-time registration and all later use of the same account. By creating an account you acknowledge this Policy. For questions, contact privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. Data we collect',
  'legalPrivacy2Bullet1': 'Account data: full name, email, phone (with country/dial code), password (stored hashed), country, selected role, and profile details you add.',
  'legalPrivacy2Bullet2': 'Verification data: email and phone OTP status; KYC information processed by Sumsub (identity document, selfie, liveness, and verification result). WWNGO stores verification status and references, not your raw ID images, except as our KYC partner\'s flow requires.',
  'legalPrivacy2Bullet3': 'Delivery data: routes, dates, parcel category/size/weight/description, photos, Receiver contact, meetup addresses, bids and counter-offers, shipment status, NFC checkpoint records, cancellation and dispute records.',
  'legalPrivacy2Bullet4': 'Communications: in-app chat messages, attachments, and support emails.',
  'legalPrivacy2Bullet5': 'Payments: unified wallet balance and ledger (available and escrow), transaction descriptions with activity role tags, Stripe payment and Connect identifiers. Card numbers are handled by Stripe, not stored on WWNGO servers.',
  'legalPrivacy2Bullet6': 'Device and usage: app version, device type, IP address, crash logs, and push-notification tokens (FCM) to deliver alerts.',
  'legalPrivacy3Heading': '3. How we use your data',
  'legalPrivacy3Bullet1': 'Create and secure your account, and let you switch among Sender, Traveler, and Receiver.',
  'legalPrivacy3Bullet2': 'Match parcels to trips, display listings, and run bids, timers, and booking locks.',
  'legalPrivacy3Bullet3': 'Collect platform fees, hold Sender funds in escrow, release payouts to Travelers after NFC Checkpoint 2, and process refunds on cancellation or dispute.',
  'legalPrivacy3Bullet4': 'Enable meetup coordination, chat, tracking, NFC confirmation, reviews, and notifications.',
  'legalPrivacy3Bullet5': 'Prevent fraud, enforce these Terms, review disputes, and meet legal obligations.',
  'legalPrivacy3Bullet6': 'Improve reliability and customer support. We do not sell your personal data.',
  'legalPrivacy4Heading': '4. Role-specific sharing on a delivery',
  'legalPrivacy4Body': 'To complete a booking, limited profile and delivery information is shown to the other parties on that shipment only — for example names, ratings, route, parcel summary, meetup status, and chat. A Traveler does not receive your full payment card details. A Receiver sees what they need to accept and collect the parcel. After delivery or cancellation, access follows product rules (history, reviews, dispute files).',
  'legalPrivacy5Heading': '5. Processors and third parties',
  'legalPrivacy5Bullet1': 'Sumsub — identity verification (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — wallet top-up, payment intents, and Connect payouts.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — push notifications.',
  'legalPrivacy5Bullet4': 'Email/SMS providers — one-time codes and transactional mail.',
  'legalPrivacy5Bullet5': 'Hosting and database providers that process data on our instructions.',
  'legalPrivacy5Bullet6': 'Authorities when required by law or to protect users from serious harm.',
  'legalPrivacy6Heading': '6. Retention, security, and international transfer',
  'legalPrivacy6Body': 'We keep account, ledger, delivery, NFC, and dispute records for as long as you have an account and for a reasonable period afterward to complete payouts, handle chargebacks, and meet bookkeeping and legal duties. We use encryption in transit, access controls, and unified wallet accounting. Data may be processed in countries other than yours; we use appropriate safeguards with processors. No method of transmission is 100% secure.',
  'legalPrivacy7Heading': '7. Your rights',
  'legalPrivacy7Body': 'Subject to applicable law, you may request access, correction, deletion, restriction, or export of your personal data, and object to certain processing. You may withdraw consent where processing is based on consent (this does not affect prior lawful processing). Some records (escrow, KYC status, completed ledgers) may be retained where we must keep them. Contact privacy@wwngo.com. You may also lodge a complaint with your local data protection authority.',
  'legalPrivacy8Heading': '8. Children, changes, and contact',
  'legalPrivacy8Body': 'WWNGO is not directed at children under 18. We do not knowingly collect their data. We may update this Policy and will post the new date in the app. Material changes may be notified in-app or by email. Contact: privacy@wwngo.com (privacy) or support@wwngo.com (general).',
  'legalCookie1Heading': 'What are cookies?',
  'legalCookie1Body': 'Cookies are small text files stored on your device. They help remember preferences and understand how you use our site.',
  'legalCookie2Heading': 'Cookies we use',
  'legalCookie2Bullet1': 'Essential — required for security and sessions',
  'legalCookie2Bullet2': 'Analytics — help us improve performance (optional)',
  'legalCookie2Bullet3': 'Preferences — remember your settings (optional)',
  'legalCookie3Heading': 'Managing cookies',
  'legalCookie3Body': 'You can control cookies in your browser settings. Disabling essential cookies may affect site functionality.',
