  'legalTermsTitle': 'Conditions générales',
  'legalPrivacyTitle': 'Politique de confidentialité',
  'legalLastUpdatedDate': '4 septembre 2026',
  'legalTerms1Heading': '1. Acceptation des présentes Conditions',
  'legalTerms1Body': 'Les présentes Conditions générales (« Conditions ») régissent votre utilisation de l\'application mobile WWNGO et des services associés (la « Plateforme »). WWNGO est une place de marché entre particuliers qui met en relation des Expéditeurs ayant besoin de faire transporter un colis, des Voyageurs qui se déplacent déjà dans cette direction, et des Destinataires qui réceptionnent le colis à l\'arrivée. En créant un compte et en cochant « J\'accepte les Conditions et la Politique de confidentialité », vous concluez un accord contraignant avec WWNGO. Si vous n\'acceptez pas ces Conditions, ne vous inscrivez pas et n\'utilisez pas la Plateforme.',
  'legalTerms2Heading': '2. Ce que WWNGO est — et n\'est pas',
  'legalTerms2Body': 'WWNGO facilite la mise en relation, le chat intégré à l\'application, la coordination des rendez-vous, les vérifications d\'identité, les paiements par portefeuille, le séquestre, la confirmation de remise par NFC, le suivi, les évaluations et l\'examen des litiges. WWNGO n\'est ni un transporteur, ni un opérateur postal, ni un transitaire, ni un courtier en douane, ni un assureur, ni un employeur de Voyageurs. La livraison est effectuée par des utilisateurs indépendants. WWNGO ne prend pas possession des colis, sauf si cela est nécessaire au fonctionnement de la Plateforme (par exemple pour stocker les photos que vous téléchargez).',
  'legalTerms3Heading': '3. Éligibilité et comptes',
  'legalTerms3Bullet1': 'Vous devez être âgé d\'au moins 18 ans et avoir la capacité de conclure un contrat contraignant.',
  'legalTerms3Bullet2': 'Vous devez fournir un nom, un e-mail, un téléphone, un pays et un mot de passe exacts, et les tenir à jour.',
  'legalTerms3Bullet3': 'Une même personne peut utiliser un seul compte WWNGO en tant qu\'Expéditeur, Voyageur et/ou Destinataire. Les présentes Conditions s\'appliquent à chaque rôle que vous utilisez.',
  'legalTerms3Bullet4': 'La vérification de l\'e-mail et du téléphone, ainsi que la vérification d\'identité (KYC) via notre partenaire Sumsub, sont requises avant de publier des livraisons, de proposer des trajets, d\'enchérir, d\'accepter des colis ou de déplacer des fonds.',
  'legalTerms3Bullet5': 'Vous êtes responsable de l\'activité sur votre compte. Ne partagez pas vos identifiants de connexion. Prévenez support@wwngo.com si vous suspectez un accès non autorisé.',
  'legalTerms4Heading': '4. Responsabilités de l\'Expéditeur',
  'legalTerms4Body': 'Lorsque vous agissez en tant qu\'Expéditeur, vous publiez une demande de livraison (ville à ville ou pays à pays), décrivez le colis, fixez un budget, ajoutez des photos et désignez un Destinataire. Vous acceptez de :',
  'legalTerms4Bullet1': 'Fournir une catégorie de colis, une taille, un poids, une description du contenu, un itinéraire, une date de voyage et des préférences de rendez-vous exacts.',
  'legalTerms4Bullet2': 'N\'envoyer que des objets légaux à posséder et à transporter sur l\'itinéraire choisi, y compris les règles douanières et aériennes pour les trajets internationaux.',
  'legalTerms4Bullet3': 'Ne jamais proposer d\'articles interdits, dangereux ou illégaux (voir la Section 10).',
  'legalTerms4Bullet4': 'Financer le séquestre pour le paiement convenu au voyageur lorsque vous acceptez une enchère ou une contre-offre, et régler vos frais de plateforme Expéditeur lors du Payer maintenant (2 \$ pour Document et Objet, ou 3 \$ si vous prenez en charge les frais du destinataire). Les frais de plateforme du Voyageur et du Destinataire sont également prélevés lors du Payer maintenant (d\'abord le portefeuille, puis la carte).',
  'legalTerms4Bullet5': 'Rencontrer le Voyageur au lieu de rendez-vous d\'origine convenu et effectuer le Point de contrôle NFC 1 (Expéditeur ↔ Voyageur) pour confirmer la remise.',
  'legalTerms4Bullet6': 'Communiquer uniquement via le chat WWNGO pour cette livraison, et respecter les annulations et délais décrits dans l\'application.',
  'legalTerms5Heading': '5. Responsabilités du Voyageur',
  'legalTerms5Body': 'Lorsque vous agissez en tant que Voyageur, vous publiez un trajet, examinez les demandes de colis correspondantes, acceptez ou faites des contre-offres, et transportez le colis pendant votre voyage. Vous acceptez de :',
  'legalTerms5Bullet1': 'Publier une origine, une destination, une date de voyage et une capacité exactes, et n\'accepter que des colis que vous pouvez transporter légalement et en toute sécurité.',
  'legalTerms5Bullet2': 'Régler les frais de plateforme Voyageur applicables (3 \$ pour Document et Objet) depuis votre portefeuille (ou votre carte si nécessaire) lorsque l\'Expéditeur effectue le Payer maintenant.',
  'legalTerms5Bullet3': 'Confirmer ou proposer des lieux de rendez-vous, effectuer le Point de contrôle NFC 1 avec l\'Expéditeur, garder le colis en sécurité pendant le transport, et effectuer le Point de contrôle NFC 2 (Voyageur ↔ Destinataire) à l\'arrivée.',
  'legalTerms5Bullet4': 'Ne pas ouvrir, utiliser, échanger ou abandonner un colis, et ne pas sous-traiter la livraison hors de WWNGO.',
  'legalTerms5Bullet5': 'Mettre à jour de bonne foi le statut de l\'envoi (par exemple au début du transport) et répondre rapidement dans le chat.',
  'legalTerms5Bullet6': 'Respecter les déclarations aériennes, frontalières et douanières. Vous êtes responsable de ce que vous transportez physiquement.',
  'legalTerms6Heading': '6. Responsabilités du Destinataire',
  'legalTerms6Body': 'Lorsque vous agissez en tant que Destinataire, vous êtes désigné sur une livraison, acceptez la demande entrante et récupérez le colis à l\'arrivée. Vous acceptez de :',
  'legalTerms6Bullet1': 'Examiner les détails du colis avant d\'accepter. Accepter constitue uniquement un consentement — des frais de plateforme Destinataire (2 \$ pour Document et Objet) sont prélevés lors du Payer maintenant de l\'expéditeur, sauf si l\'expéditeur les prend en charge.',
  'legalTerms6Bullet2': 'Être disponible au rendez-vous de destination, vérifier le colis et effectuer le Point de contrôle NFC 2 (Voyageur ↔ Destinataire) pour confirmer la livraison.',
  'legalTerms6Bullet3': 'Ouvrir rapidement un litige dans l\'application si le colis est manquant, endommagé ou non conforme à la description, plutôt que de valider la confirmation NFC si vous n\'acceptez pas les biens.',
  'legalTerms6Bullet4': 'Maintenir des coordonnées exactes afin que l\'Expéditeur et le Voyageur puissent se coordonner.',
  'legalTerms7Heading': '7. Mise en relation, enchères et réservation',
  'legalTerms7Body': 'Les Expéditeurs peuvent découvrir des voyageurs et envoyer des demandes. Les Voyageurs peuvent recevoir des demandes correspondantes, les accepter, les refuser ou envoyer une contre-offre. Une réservation n\'est créée que lorsque l\'Expéditeur accepte un prix, que le KYC et la vérification requis sont terminés, que le séquestre est correctement approvisionné et que les frais de plateforme sont prélevés comme indiqué. La sélection d\'un Voyageur verrouille la réservation. Si une fenêtre de paiement ou un délai d\'acceptation expire, la réservation peut être annulée automatiquement et le principal du séquestre est remboursé conformément à la Section 12.',
  'legalTerms8Heading': '8. Lieux de rendez-vous et chat',
  'legalTerms8Body': 'Les parties coordonnent un rendez-vous public et approprié à l\'aide des outils de localisation de l\'application. Un rendez-vous est confirmé lorsque les parties requises l\'acceptent dans l\'application. Le chat entre Expéditeur–Voyageur, Expéditeur–Destinataire et Voyageur–Destinataire se déverrouille selon le statut de la livraison. Ne communiquez pas les détails de paiement hors plateforme et ne déplacez pas la transaction hors de WWNGO. Les paiements hors plateforme annulent la protection du séquestre.',
  'legalTerms9Heading': '9. Points de contrôle NFC et confirmation de livraison',
  'legalTerms9Bullet1': 'Le Point de contrôle NFC 1 (Expéditeur ↔ Voyageur) confirme que l\'Expéditeur a remis le colis au Voyageur.',
  'legalTerms9Bullet2': 'Le Point de contrôle NFC 2 (Voyageur ↔ Destinataire) confirme que le Destinataire a reçu le colis. Les deux parties doivent effectuer leur validation. La réussite du Point de contrôle 2 marque l\'envoi comme Livré et libère le séquestre au profit du Voyageur (sauf s\'il est gelé en raison d\'un litige).',
  'legalTerms9Bullet3': 'Le NFC est un outil de confirmation, pas une garantie de l\'état du colis. Les photos, le chat, le suivi et les registres de litiges peuvent toujours être utilisés dans un examen.',
  'legalTerms9Bullet4': 'Toute utilisation abusive du NFC (confirmation sans remise réelle, validation forcée ou usurpation d\'appareils) constitue un motif de suspension et de gel du séquestre.',
  'legalTerms10Heading': '10. Objets interdits et tolérance zéro',
  'legalTerms10Body': 'Vous ne devez pas envoyer, transporter ou demander : des drogues illégales, des armes, des explosifs, des matières dangereuses, des biens volés, des articles de contrefaçon, des espèces ou instruments au porteur au-delà de ce que la loi locale autorise, des animaux vivants, des restes humains, ou tout article interdit par le transporteur, la compagnie aérienne ou le pays de destination. La fraude, la fausse identité, les fausses photos, le harcèlement, la manipulation des évaluations et les tentatives de contournement du séquestre sont interdits. WWNGO peut suspendre des comptes, geler le séquestre et signaler toute activité illégale aux autorités.',
  'legalTerms11Heading': '11. Paiements, portefeuilles et séquestre',
  'legalTerms11Bullet1': 'Vous disposez d\'un seul portefeuille WWNGO partagé entre vos activités d\'Expéditeur, de Voyageur et de Destinataire. Rechargez via Stripe et retirez via Stripe Connect une fois qu\'un compte de paiement est lié et prêt. L\'historique des transactions indique à quel rôle chaque entrée se rapporte.',
  'legalTerms11Bullet2': 'Lorsqu\'un Expéditeur accepte un Voyageur, le paiement convenu est transféré du solde disponible de l\'Expéditeur vers le séquestre (un paiement par carte peut couvrir un déficit). Le séquestre n\'est retirable par aucune partie jusqu\'à sa libération, son remboursement ou une décision de litige.',
  'legalTerms11Bullet3': 'Les frais de plateforme (Expéditeur, Voyageur et/ou Destinataire, y compris l\'option où l\'Expéditeur prend en charge les frais du Destinataire) sont communiqués avant votre confirmation et prélevés comme indiqué.',
  'legalTerms11Bullet4': 'Le séquestre est libéré au profit du Voyageur après le Point de contrôle NFC 2 / Livré, sauf s\'il est gelé. WWNGO n\'est pas une banque ; les soldes de portefeuille sont des registres de la Plateforme utilisés pour régler les transactions de la place de marché.',
  'legalTerms12Heading': '12. Annulations et remboursements',
  'legalTerms12Body': 'Les livraisons réservées peuvent être annulées avant que le trajet ne soit en transit ou livré, sous réserve des règles de l\'application. Le principal du séquestre est remboursé à l\'Expéditeur. Les frais de plateforme sont remboursés aux parties payantes si l\'annulation intervient plus de 24 heures avant le voyage ; dans les 24 heures, les frais de plateforme ne sont généralement pas remboursables. Les livraisons publiées qui ne sont pas encore réservées peuvent être annulées selon les règles de publication de l\'application. L\'annulation automatique (par exemple des fenêtres Destinataire impayées ou des délais d\'acceptation expirés) rembourse le principal du séquestre comme indiqué dans le produit. Les recharges et les paiements déjà effectués ne sont pas annulés, sauf si la loi ou une décision de litige formelle l\'exige.',
  'legalTerms13Heading': '13. Suivi, photos et avis',
  'legalTerms13Body': 'Les mises à jour de statut, les photos de colis et les données GPS ou de rendez-vous que vous fournissez sont utilisées pour assurer la livraison. Après la livraison, les parties peuvent laisser des avis. Les avis doivent être honnêtes et porter sur la transaction. WWNGO peut masquer ou supprimer les avis abusifs ou frauduleux.',
  'legalTerms14Heading': '14. Litiges',
  'legalTerms14Body': 'Si quelque chose ne se passe pas comme prévu (dommage, non-livraison, mauvais article, litige NFC), ouvrez un litige dans l\'application. L\'ouverture d\'un litige gèle le séquestre pendant que WWNGO examine les registres de livraison, les photos, le chat, les points de contrôle NFC et les données d\'identité. Ne validez pas le Point de contrôle NFC 2 si vous avez l\'intention de contester la réception. La décision de WWNGO concernant le séquestre (libération, remboursement ou partage) est définitive entre les parties sur la Plateforme, sans limiter les droits dont vous pourriez disposer contre un autre utilisateur devant une juridiction compétente. Les rétrofacturations ou réclamations hors plateforme peuvent tout de même entraîner une mesure sur le compte.',
  'legalTerms15Heading': '15. Limitation de responsabilité',
  'legalTerms15Body': 'Dans toute la mesure permise par la loi, WWNGO n\'est pas responsable des pertes, retards, dommages, saisies ou problèmes douaniers causés par les utilisateurs, les transporteurs ou les gouvernements ; des actes des Expéditeurs, Voyageurs ou Destinataires ; ni des dommages indirects, accessoires ou consécutifs. Notre responsabilité totale à votre égard pour une réclamation liée à la Plateforme est limitée au montant le plus élevé entre (a) les frais de plateforme que vous avez versés à WWNGO pour la livraison contestée au cours des 12 mois précédant la réclamation, ou (b) 50 USD. Rien dans les présentes Conditions n\'exclut une responsabilité qui ne peut légalement être exclue (y compris en cas de fraude ou de décès/blessure corporelle causé par une négligence lorsque cette exclusion est interdite).',
  'legalTerms16Heading': '16. Modifications, suspension et contact',
  'legalTerms16Body': 'Nous pouvons mettre à jour les présentes Conditions. La poursuite de l\'utilisation après un avis dans l\'application constitue une acceptation des Conditions révisées. Nous pouvons suspendre ou résilier les comptes qui violent les présentes Conditions. Questions : support@wwngo.com. Les présentes Conditions constituent l\'accord intégral relatif à votre utilisation de la Plateforme et sont régies par les lois applicables au lieu d\'établissement de WWNGO, sans préjudice des protections des consommateurs obligatoires dans votre pays de résidence.',
  'legalPrivacy1Heading': '1. Introduction',
  'legalPrivacy1Body': 'Cette Politique de confidentialité explique comment WWNGO collecte, utilise, partage et protège les données personnelles lorsque vous utilisez notre place de marché de colis entre particuliers en tant qu\'Expéditeur, Voyageur et/ou Destinataire. Elle s\'applique à l\'inscription initiale et à toute utilisation ultérieure du même compte. En créant un compte, vous reconnaissez cette Politique. Pour toute question, contactez privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. Données que nous collectons',
  'legalPrivacy2Bullet1': 'Données de compte : nom complet, e-mail, téléphone (avec pays/indicatif), mot de passe (stocké haché), pays, rôle sélectionné et informations de profil que vous ajoutez.',
  'legalPrivacy2Bullet2': 'Données de vérification : statut OTP de l\'e-mail et du téléphone ; informations KYC traitées par Sumsub (document d\'identité, selfie, détection de vivacité et résultat de vérification). WWNGO conserve le statut et les références de vérification, et non vos images d\'identité brutes, sauf lorsque le processus de notre partenaire KYC l\'exige.',
  'legalPrivacy2Bullet3': 'Données de livraison : itinéraires, dates, catégorie/taille/poids/description du colis, photos, contact du Destinataire, adresses de rendez-vous, enchères et contre-offres, statut de l\'envoi, registres des points de contrôle NFC, registres d\'annulation et de litige.',
  'legalPrivacy2Bullet4': 'Communications : messages de chat dans l\'application, pièces jointes et e-mails d\'assistance.',
  'legalPrivacy2Bullet5': 'Paiements : solde et registre unifiés du portefeuille (disponible et séquestre), descriptions de transactions avec balises de rôle d\'activité, identifiants de paiement Stripe et Connect. Les numéros de carte sont traités par Stripe et ne sont pas stockés sur les serveurs de WWNGO.',
  'legalPrivacy2Bullet6': 'Appareil et utilisation : version de l\'application, type d\'appareil, adresse IP, journaux de plantage et jetons de notification push (FCM) pour diffuser les alertes.',
  'legalPrivacy3Heading': '3. Comment nous utilisons vos données',
  'legalPrivacy3Bullet1': 'Créer et sécuriser votre compte, et vous permettre de basculer entre Expéditeur, Voyageur et Destinataire.',
  'legalPrivacy3Bullet2': 'Associer les colis aux trajets, afficher les annonces et gérer les enchères, minuteries et verrouillages de réservation.',
  'legalPrivacy3Bullet3': 'Percevoir les frais de plateforme, conserver les fonds de l\'Expéditeur en séquestre, libérer les paiements aux Voyageurs après le Point de contrôle NFC 2, et traiter les remboursements en cas d\'annulation ou de litige.',
  'legalPrivacy3Bullet4': 'Permettre la coordination des rendez-vous, le chat, le suivi, la confirmation NFC, les avis et les notifications.',
  'legalPrivacy3Bullet5': 'Prévenir la fraude, faire respecter les présentes Conditions, examiner les litiges et satisfaire aux obligations légales.',
  'legalPrivacy3Bullet6': 'Améliorer la fiabilité et le support client. Nous ne vendons pas vos données personnelles.',
  'legalPrivacy4Heading': '4. Partage spécifique au rôle lors d\'une livraison',
  'legalPrivacy4Body': 'Pour finaliser une réservation, des informations limitées de profil et de livraison sont affichées aux autres parties de cet envoi uniquement — par exemple les noms, les évaluations, l\'itinéraire, le résumé du colis, le statut du rendez-vous et le chat. Un Voyageur ne reçoit pas l\'intégralité des détails de votre carte de paiement. Un Destinataire voit ce dont il a besoin pour accepter et récupérer le colis. Après la livraison ou l\'annulation, l\'accès suit les règles du produit (historique, avis, dossiers de litige).',
  'legalPrivacy5Heading': '5. Sous-traitants et tiers',
  'legalPrivacy5Bullet1': 'Sumsub — vérification d\'identité (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — recharge du portefeuille, intentions de paiement et paiements Connect.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — notifications push.',
  'legalPrivacy5Bullet4': 'Fournisseurs d\'e-mail/SMS — codes à usage unique et e-mails transactionnels.',
  'legalPrivacy5Bullet5': 'Fournisseurs d\'hébergement et de bases de données qui traitent les données selon nos instructions.',
  'legalPrivacy5Bullet6': 'Les autorités, lorsque la loi l\'exige ou pour protéger les utilisateurs d\'un préjudice grave.',
  'legalPrivacy6Heading': '6. Conservation, sécurité et transfert international',
  'legalPrivacy6Body': 'Nous conservons les registres de compte, de portefeuille, de livraison, NFC et de litiges pendant toute la durée de votre compte et pendant une période raisonnable par la suite afin de finaliser les paiements, de traiter les rétrofacturations et de satisfaire aux obligations comptables et légales. Nous utilisons le chiffrement en transit, des contrôles d\'accès et une comptabilité de portefeuille unifiée. Les données peuvent être traitées dans des pays autres que le vôtre ; nous utilisons des garanties appropriées avec nos sous-traitants. Aucune méthode de transmission n\'est sûre à 100 %.',
  'legalPrivacy7Heading': '7. Vos droits',
  'legalPrivacy7Body': 'Sous réserve du droit applicable, vous pouvez demander l\'accès, la correction, la suppression, la restriction ou l\'exportation de vos données personnelles, et vous opposer à certains traitements. Vous pouvez retirer votre consentement lorsque le traitement est fondé sur celui-ci (cela n\'affecte pas la licéité du traitement antérieur). Certains registres (séquestre, statut KYC, registres finalisés) peuvent être conservés lorsque nous devons les garder. Contactez privacy@wwngo.com. Vous pouvez également déposer une réclamation auprès de votre autorité locale de protection des données.',
  'legalPrivacy8Heading': '8. Enfants, modifications et contact',
  'legalPrivacy8Body': 'WWNGO ne s\'adresse pas aux enfants de moins de 18 ans. Nous ne collectons pas sciemment leurs données. Nous pouvons mettre à jour cette Politique et publierons la nouvelle date dans l\'application. Les changements importants pourront être notifiés dans l\'application ou par e-mail. Contact : privacy@wwngo.com (confidentialité) ou support@wwngo.com (général).',
  'legalCookie1Heading': 'Que sont les cookies ?',
  'legalCookie1Body': 'Les cookies sont de petits fichiers texte stockés sur votre appareil. Ils aident à se souvenir de vos préférences et à comprendre comment vous utilisez notre site.',
  'legalCookie2Heading': 'Cookies que nous utilisons',
  'legalCookie2Bullet1': 'Essentiels — requis pour la sécurité et les sessions',
  'legalCookie2Bullet2': 'Analytiques — nous aident à améliorer les performances (facultatifs)',
  'legalCookie2Bullet3': 'Préférences — mémorisent vos paramètres (facultatifs)',
  'legalCookie3Heading': 'Gestion des cookies',
  'legalCookie3Body': 'Vous pouvez contrôler les cookies dans les paramètres de votre navigateur. La désactivation des cookies essentiels peut affecter le fonctionnement du site.',
