  'legalTermsTitle': 'Términos y Condiciones',
  'legalPrivacyTitle': 'Política de privacidad',
  'legalLastUpdatedDate': '4 de septiembre de 2026',
  'legalTerms1Heading': '1. Aceptación de estos Términos',
  'legalTerms1Body': 'Estos Términos y Condiciones («Términos») rigen el uso de la aplicación móvil WWNGO y los servicios relacionados (la «Plataforma»). WWNGO es un mercado entre particulares que conecta a Remitentes que necesitan transportar un paquete, Viajeros que ya se dirigen hacia ese destino, y Destinatarios que reciben el paquete en destino. Al crear una cuenta y marcar «Acepto los Términos y la Política de privacidad», usted celebra un acuerdo vinculante con WWNGO. Si no está de acuerdo, no se registre ni utilice la Plataforma.',
  'legalTerms2Heading': '2. Qué es WWNGO — y qué no es',
  'legalTerms2Body': 'WWNGO facilita la búsqueda de coincidencias, el chat dentro de la aplicación, la coordinación de encuentros, las verificaciones de identidad, los pagos por monedero, el depósito en garantía, la confirmación de entrega por NFC, el seguimiento, las valoraciones y la revisión de disputas. WWNGO no es un mensajero, un operador postal, un transitario, un agente de aduanas, una aseguradora ni un empleador de Viajeros. La entrega la realizan usuarios independientes. WWNGO no toma posesión de los paquetes salvo cuando sea necesario para operar la Plataforma (por ejemplo, almacenar las fotos que usted sube).',
  'legalTerms3Heading': '3. Elegibilidad y cuentas',
  'legalTerms3Bullet1': 'Debe tener al menos 18 años y capacidad para celebrar un contrato vinculante.',
  'legalTerms3Bullet2': 'Debe proporcionar nombre, correo electrónico, teléfono, país y contraseña exactos, y mantenerlos actualizados.',
  'legalTerms3Bullet3': 'Una misma persona puede usar una única cuenta de WWNGO como Remitente, Viajero y/o Destinatario. Estos Términos se aplican a cada rol que utilice.',
  'legalTerms3Bullet4': 'La verificación de correo electrónico y teléfono, así como la verificación de identidad (KYC) a través de nuestro socio Sumsub, son obligatorias antes de publicar entregas, listar viajes, ofertar, aceptar paquetes o mover dinero.',
  'legalTerms3Bullet5': 'Usted es responsable de la actividad en su cuenta. No comparta sus credenciales de acceso. Notifique a support@wwngo.com si sospecha de un acceso no autorizado.',
  'legalTerms4Heading': '4. Responsabilidades del Remitente',
  'legalTerms4Body': 'Cuando actúa como Remitente, publica una solicitud de entrega (de ciudad a ciudad o de país a país), describe el paquete, fija un presupuesto, añade fotos y designa a un Destinatario. Usted se compromete a:',
  'legalTerms4Bullet1': 'Proporcionar de forma veraz la categoría, el tamaño, el peso, la descripción del contenido, la ruta, la fecha de viaje y las preferencias de encuentro del paquete.',
  'legalTerms4Bullet2': 'Enviar únicamente artículos cuya posesión y transporte sea legal en la ruta elegida, incluidas las normas de aduanas y aerolíneas para viajes internacionales.',
  'legalTerms4Bullet3': 'No incluir nunca artículos prohibidos, peligrosos o ilegales (véase la Sección 10).',
  'legalTerms4Bullet4': 'Financiar el depósito en garantía para el pago acordado al viajero al aceptar una oferta o contraoferta, y pagar su tarifa de plataforma de Remitente en Pagar ahora (2 \$ para Documento y Objeto, o 3 \$ si usted cubre la tarifa del destinatario). Las tarifas de plataforma del Viajero y del Destinatario también se cobran en Pagar ahora (primero desde el monedero, luego con tarjeta).',
  'legalTerms4Bullet5': 'Reunirse con el Viajero en el lugar de encuentro de origen acordado y completar el Punto de control NFC 1 (Remitente ↔ Viajero) para confirmar la entrega.',
  'legalTerms4Bullet6': 'Comunicarse únicamente a través del chat de WWNGO para esta entrega, y respetar las cancelaciones y los plazos descritos en la aplicación.',
  'legalTerms5Heading': '5. Responsabilidades del Viajero',
  'legalTerms5Body': 'Cuando actúa como Viajero, publica un viaje, revisa las solicitudes de paquetes coincidentes, acepta o hace contraofertas, y transporta el paquete durante su trayecto. Usted se compromete a:',
  'legalTerms5Bullet1': 'Publicar un origen, un destino, una fecha de viaje y una capacidad exactos, y aceptar únicamente paquetes que pueda transportar de forma legal y segura.',
  'legalTerms5Bullet2': 'Pagar las tarifas de plataforma de Viajero aplicables (3 \$ para Documento y Objeto) desde su monedero (o tarjeta si es necesario) cuando el Remitente complete Pagar ahora.',
  'legalTerms5Bullet3': 'Confirmar o proponer lugares de encuentro, completar el Punto de control NFC 1 con el Remitente, mantener el paquete seguro durante el tránsito, y completar el Punto de control NFC 2 (Viajero ↔ Destinatario) en destino.',
  'legalTerms5Bullet4': 'No abrir, usar, intercambiar ni abandonar un paquete, ni subcontratar la entrega fuera de WWNGO.',
  'legalTerms5Bullet5': 'Actualizar de buena fe el estado del envío (por ejemplo, al iniciar el tránsito) y responder con prontitud en el chat.',
  'legalTerms5Bullet6': 'Cumplir con las declaraciones de la aerolínea, de frontera y de aduanas. Usted es responsable de lo que transporta físicamente.',
  'legalTerms6Heading': '6. Responsabilidades del Destinatario',
  'legalTerms6Body': 'Cuando actúa como Destinatario, está designado en una entrega, acepta la solicitud entrante y recoge el paquete en destino. Usted se compromete a:',
  'legalTerms6Bullet1': 'Revisar los detalles del paquete antes de aceptar. Aceptar constituye únicamente un consentimiento — se cobra una tarifa de plataforma de Destinatario (2 \$ para Documento y Objeto) en el Pagar ahora del remitente, salvo que el remitente la cubra.',
  'legalTerms6Bullet2': 'Estar disponible en el encuentro de destino, verificar el paquete y completar el Punto de control NFC 2 (Viajero ↔ Destinatario) para confirmar la entrega.',
  'legalTerms6Bullet3': 'Abrir con prontitud una disputa en la aplicación si el paquete falta, está dañado o no coincide con la descripción, en lugar de completar la confirmación NFC si no acepta los bienes.',
  'legalTerms6Bullet4': 'Mantener los datos de contacto exactos para que el Remitente y el Viajero puedan coordinarse.',
  'legalTerms7Heading': '7. Coincidencias, ofertas y reservas',
  'legalTerms7Body': 'Los Remitentes pueden descubrir viajeros y enviar solicitudes. Los Viajeros pueden recibir solicitudes coincidentes, aceptarlas, rechazarlas o enviar una contraoferta. Una reserva se crea únicamente cuando el Remitente acepta un precio, se completan el KYC y la verificación requeridos, el depósito en garantía se financia correctamente y se cobran las tarifas de plataforma según lo mostrado. La selección de un Viajero bloquea la reserva. Si vence una ventana de pago o un temporizador de aceptación, la reserva puede cancelarse automáticamente y el principal del depósito se reembolsa conforme a la Sección 12.',
  'legalTerms8Heading': '8. Lugares de encuentro y chat',
  'legalTerms8Body': 'Las partes coordinan un encuentro público y apropiado utilizando las herramientas de ubicación de la aplicación. Un encuentro queda confirmado cuando las partes requeridas lo aceptan en la aplicación. El chat entre Remitente–Viajero, Remitente–Destinatario y Viajero–Destinatario se desbloquea según el estado de la entrega. No comparta datos de pago fuera de la plataforma ni traslade el acuerdo fuera de WWNGO. Los pagos fuera de la plataforma anulan la protección del depósito en garantía.',
  'legalTerms9Heading': '9. Puntos de control NFC y confirmación de entrega',
  'legalTerms9Bullet1': 'El Punto de control NFC 1 (Remitente ↔ Viajero) confirma que el Remitente entregó el paquete al Viajero.',
  'legalTerms9Bullet2': 'El Punto de control NFC 2 (Viajero ↔ Destinatario) confirma que el Destinatario recibió el paquete. Ambas partes deben completar su acercamiento. Un Punto de control 2 exitoso marca el envío como Entregado y libera el depósito en garantía al Viajero (salvo que esté congelado por una disputa).',
  'legalTerms9Bullet3': 'El NFC es una herramienta de confirmación, no una garantía del estado del paquete. Las fotos, el chat, el seguimiento y los registros de disputas pueden seguir utilizándose en una revisión.',
  'legalTerms9Bullet4': 'El uso indebido del NFC (confirmar sin una entrega real, forzar un acercamiento o falsificar dispositivos) es motivo de suspensión y congelación del depósito en garantía.',
  'legalTerms10Heading': '10. Artículos prohibidos y tolerancia cero',
  'legalTerms10Body': 'No debe enviar, transportar ni solicitar: drogas ilegales, armas, explosivos, materiales peligrosos, bienes robados, artículos falsificados, efectivo o instrumentos al portador más allá de lo que permita la ley local, animales vivos, restos humanos, o cualquier artículo prohibido por el transportista, la aerolínea o el país de destino. Se prohíben el fraude, la identidad falsa, las fotos falsas, el acoso, la manipulación de valoraciones y los intentos de eludir el depósito en garantía. WWNGO puede suspender cuentas, congelar el depósito en garantía y denunciar actividades ilegales a las autoridades.',
  'legalTerms11Heading': '11. Pagos, monederos y depósito en garantía',
  'legalTerms11Bullet1': 'Usted tiene un único monedero WWNGO compartido entre sus actividades como Remitente, Viajero y Destinatario. Recargue con Stripe y retire mediante Stripe Connect una vez que una cuenta de pago esté vinculada y lista. El historial de transacciones registra a qué rol corresponde cada entrada.',
  'legalTerms11Bullet2': 'Cuando un Remitente acepta a un Viajero, el pago acordado se transfiere del saldo disponible del Remitente al depósito en garantía (un pago con tarjeta puede cubrir un déficit). El depósito en garantía no puede retirarlo ninguna de las partes hasta su liberación, reembolso o una decisión de disputa.',
  'legalTerms11Bullet3': 'Las tarifas de plataforma (Remitente, Viajero y/o Destinatario, incluida la opción de que el Remitente cubra la tarifa del Destinatario) se muestran antes de confirmar y se cobran según lo indicado.',
  'legalTerms11Bullet4': 'El depósito en garantía se libera al Viajero después del Punto de control NFC 2 / Entregado, salvo que esté congelado. WWNGO no es un banco; los saldos del monedero son registros de la Plataforma utilizados para liquidar las transacciones del mercado.',
  'legalTerms12Heading': '12. Cancelaciones y reembolsos',
  'legalTerms12Body': 'Las entregas reservadas pueden cancelarse antes de que el viaje esté en tránsito o entregado, sujeto a las reglas de la aplicación. El principal del depósito en garantía se reembolsa al Remitente. Las tarifas de plataforma se reembolsan a las partes pagadoras si la cancelación ocurre con más de 24 horas de antelación al viaje; dentro de las 24 horas, las tarifas de plataforma generalmente no son reembolsables. Las entregas publicadas que aún no estén reservadas pueden cancelarse según las reglas de publicación de la aplicación. La cancelación automática (por ejemplo, ventanas de Destinatario impagas o temporizadores de aceptación vencidos) reembolsa el principal del depósito en garantía según lo indicado en el producto. Las recargas y los pagos ya completados no se revierten, salvo que la ley lo exija o exista un resultado formal de disputa.',
  'legalTerms13Heading': '13. Seguimiento, fotos y valoraciones',
  'legalTerms13Body': 'Las actualizaciones de estado, las fotos del paquete y los datos de GPS o de encuentro que usted proporciona se utilizan para gestionar la entrega. Después de la entrega, las partes pueden dejar valoraciones. Las valoraciones deben ser honestas y referirse a la transacción. WWNGO puede ocultar o eliminar valoraciones abusivas o falsas.',
  'legalTerms14Heading': '14. Disputas',
  'legalTerms14Body': 'Si algo sale mal (daño, no entrega, artículo incorrecto, disputa NFC), presente una disputa en la aplicación. Presentar una disputa congela el depósito en garantía mientras WWNGO revisa los registros de entrega, las fotos, el chat, los puntos de control NFC y los datos de identidad. No complete el Punto de control NFC 2 si tiene intención de disputar la recepción. La decisión de WWNGO sobre el depósito en garantía (liberación, reembolso o división) es definitiva entre las partes en la Plataforma, sin limitar los derechos que pueda tener frente a otro usuario ante un tribunal competente. Las devoluciones de cargo o reclamaciones fuera de la plataforma pueden seguir dando lugar a medidas sobre la cuenta.',
  'legalTerms15Heading': '15. Limitación de responsabilidad',
  'legalTerms15Body': 'En la máxima medida permitida por la ley, WWNGO no es responsable de pérdidas, retrasos, daños, incautaciones o problemas aduaneros causados por usuarios, transportistas o gobiernos; de los actos de Remitentes, Viajeros o Destinatarios; ni de daños indirectos, incidentales o consecuentes. Nuestra responsabilidad total frente a usted por una reclamación relacionada con la Plataforma se limita al mayor de (a) las tarifas de plataforma que usted haya pagado a WWNGO por la entrega en disputa en los 12 meses anteriores a la reclamación, o (b) 50 USD. Nada en estos Términos excluye la responsabilidad que no pueda excluirse legalmente (incluida la derivada de fraude o de muerte/lesión personal causada por negligencia cuando dicha exclusión esté prohibida).',
  'legalTerms16Heading': '16. Cambios, suspensión y contacto',
  'legalTerms16Body': 'Podemos actualizar estos Términos. El uso continuado tras un aviso en la aplicación constituye la aceptación de los Términos revisados. Podemos suspender o cancelar cuentas que infrinjan estos Términos. Preguntas: support@wwngo.com. Estos Términos constituyen el acuerdo íntegro relativo a su uso de la Plataforma y se rigen por las leyes aplicables al lugar de establecimiento de WWNGO, sin perjuicio de las protecciones obligatorias al consumidor en su país de residencia.',
  'legalPrivacy1Heading': '1. Introducción',
  'legalPrivacy1Body': 'Esta Política de privacidad explica cómo WWNGO recopila, utiliza, comparte y protege los datos personales cuando usted utiliza nuestro mercado de paquetes entre particulares como Remitente, Viajero y/o Destinatario. Se aplica al registro inicial y a todo uso posterior de la misma cuenta. Al crear una cuenta, usted reconoce esta Política. Para consultas, contacte con privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. Datos que recopilamos',
  'legalPrivacy2Bullet1': 'Datos de la cuenta: nombre completo, correo electrónico, teléfono (con código de país), contraseña (almacenada cifrada mediante hash), país, rol seleccionado y datos de perfil que usted añada.',
  'legalPrivacy2Bullet2': 'Datos de verificación: estado del código OTP de correo y teléfono; información KYC procesada por Sumsub (documento de identidad, selfie, prueba de vida y resultado de verificación). WWNGO almacena el estado y las referencias de verificación, no sus imágenes de identidad en bruto, salvo cuando el proceso de nuestro socio KYC lo requiera.',
  'legalPrivacy2Bullet3': 'Datos de entrega: rutas, fechas, categoría/tamaño/peso/descripción del paquete, fotos, contacto del Destinatario, direcciones de encuentro, ofertas y contraofertas, estado del envío, registros de puntos de control NFC, registros de cancelación y disputa.',
  'legalPrivacy2Bullet4': 'Comunicaciones: mensajes de chat dentro de la aplicación, archivos adjuntos y correos de soporte.',
  'legalPrivacy2Bullet5': 'Pagos: saldo y libro mayor unificados del monedero (disponible y en depósito en garantía), descripciones de transacciones con etiquetas de rol de actividad, identificadores de pago de Stripe y de Connect. Los números de tarjeta son gestionados por Stripe y no se almacenan en los servidores de WWNGO.',
  'legalPrivacy2Bullet6': 'Dispositivo y uso: versión de la aplicación, tipo de dispositivo, dirección IP, registros de fallos y tókenes de notificaciones push (FCM) para entregar alertas.',
  'legalPrivacy3Heading': '3. Cómo utilizamos sus datos',
  'legalPrivacy3Bullet1': 'Crear y proteger su cuenta, y permitirle cambiar entre Remitente, Viajero y Destinatario.',
  'legalPrivacy3Bullet2': 'Emparejar paquetes con viajes, mostrar anuncios y gestionar ofertas, temporizadores y bloqueos de reserva.',
  'legalPrivacy3Bullet3': 'Cobrar tarifas de plataforma, mantener los fondos del Remitente en depósito en garantía, liberar los pagos a los Viajeros tras el Punto de control NFC 2, y procesar reembolsos por cancelación o disputa.',
  'legalPrivacy3Bullet4': 'Habilitar la coordinación de encuentros, el chat, el seguimiento, la confirmación NFC, las valoraciones y las notificaciones.',
  'legalPrivacy3Bullet5': 'Prevenir el fraude, hacer cumplir estos Términos, revisar disputas y cumplir con las obligaciones legales.',
  'legalPrivacy3Bullet6': 'Mejorar la fiabilidad y el soporte al cliente. No vendemos sus datos personales.',
  'legalPrivacy4Heading': '4. Compartición específica por rol en una entrega',
  'legalPrivacy4Body': 'Para completar una reserva, se muestra información limitada de perfil y de entrega únicamente a las demás partes de ese envío — por ejemplo, nombres, valoraciones, ruta, resumen del paquete, estado del encuentro y chat. Un Viajero no recibe los datos completos de su tarjeta de pago. Un Destinatario ve lo que necesita para aceptar y recoger el paquete. Tras la entrega o la cancelación, el acceso sigue las reglas del producto (historial, valoraciones, expedientes de disputa).',
  'legalPrivacy5Heading': '5. Encargados y terceros',
  'legalPrivacy5Bullet1': 'Sumsub — verificación de identidad (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — recarga del monedero, intenciones de pago y pagos de Connect.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — notificaciones push.',
  'legalPrivacy5Bullet4': 'Proveedores de correo/SMS — códigos de un solo uso y correos transaccionales.',
  'legalPrivacy5Bullet5': 'Proveedores de alojamiento y bases de datos que procesan datos siguiendo nuestras instrucciones.',
  'legalPrivacy5Bullet6': 'Las autoridades, cuando lo exija la ley o para proteger a los usuarios de un daño grave.',
  'legalPrivacy6Heading': '6. Conservación, seguridad y transferencia internacional',
  'legalPrivacy6Body': 'Conservamos los registros de cuenta, libro mayor, entrega, NFC y disputas durante todo el tiempo que tenga una cuenta y por un período razonable después, para completar pagos, gestionar devoluciones de cargo y cumplir con obligaciones contables y legales. Utilizamos cifrado en tránsito, controles de acceso y una contabilidad unificada del monedero. Los datos pueden procesarse en países distintos al suyo; utilizamos garantías adecuadas con los encargados. Ningún método de transmisión es 100 % seguro.',
  'legalPrivacy7Heading': '7. Sus derechos',
  'legalPrivacy7Body': 'Sujeto a la ley aplicable, usted puede solicitar el acceso, la corrección, la eliminación, la restricción o la exportación de sus datos personales, y oponerse a determinados tratamientos. Puede retirar su consentimiento cuando el tratamiento se base en él (esto no afecta a la licitud del tratamiento anterior). Algunos registros (depósito en garantía, estado KYC, libros mayores completados) pueden conservarse cuando debamos mantenerlos. Contacte con privacy@wwngo.com. También puede presentar una reclamación ante su autoridad local de protección de datos.',
  'legalPrivacy8Heading': '8. Menores, cambios y contacto',
  'legalPrivacy8Body': 'WWNGO no está dirigido a menores de 18 años. No recopilamos sus datos a sabiendas. Podemos actualizar esta Política y publicaremos la nueva fecha en la aplicación. Los cambios importantes podrán notificarse dentro de la aplicación o por correo electrónico. Contacto: privacy@wwngo.com (privacidad) o support@wwngo.com (general).',
  'legalCookie1Heading': '¿Qué son las cookies?',
  'legalCookie1Body': 'Las cookies son pequeños archivos de texto almacenados en su dispositivo. Ayudan a recordar sus preferencias y a entender cómo utiliza nuestro sitio.',
  'legalCookie2Heading': 'Cookies que utilizamos',
  'legalCookie2Bullet1': 'Esenciales — necesarias para la seguridad y las sesiones',
  'legalCookie2Bullet2': 'Analíticas — nos ayudan a mejorar el rendimiento (opcionales)',
  'legalCookie2Bullet3': 'Preferencias — recuerdan su configuración (opcionales)',
  'legalCookie3Heading': 'Gestión de cookies',
  'legalCookie3Body': 'Puede controlar las cookies en la configuración de su navegador. Deshabilitar las cookies esenciales puede afectar la funcionalidad del sitio.',
