  'legalTermsTitle': 'Termini e Condizioni',
  'legalPrivacyTitle': 'Informativa sulla privacy',
  'legalLastUpdatedDate': '4 settembre 2026',
  'legalTerms1Heading': '1. Accettazione dei presenti Termini',
  'legalTerms1Body': 'I presenti Termini e Condizioni («Termini») disciplinano l\'utilizzo dell\'app mobile WWNGO e dei servizi correlati (la «Piattaforma»). WWNGO è un marketplace peer-to-peer che collega Mittenti che devono far trasportare un pacco, Viaggiatori già in viaggio verso quella destinazione e Destinatari che ricevono il pacco a destinazione. Creando un account e selezionando «Accetto i Termini e l\'Informativa sulla privacy», si stipula un accordo vincolante con WWNGO. In caso di mancata accettazione, non registrarsi né utilizzare la Piattaforma.',
  'legalTerms2Heading': '2. Cosa è WWNGO — e cosa non è',
  'legalTerms2Body': 'WWNGO facilita l\'incontro tra domanda e offerta, la chat in-app, il coordinamento degli incontri, le verifiche d\'identità, i pagamenti tramite portafoglio, il deposito a garanzia, la conferma della consegna tramite NFC, il tracciamento, le valutazioni e la revisione delle controversie. WWNGO non è un corriere, un operatore postale, uno spedizioniere, un intermediario doganale, un assicuratore né un datore di lavoro dei Viaggiatori. La consegna è effettuata da utenti indipendenti. WWNGO non prende possesso dei pacchi salvo quando necessario per il funzionamento della Piattaforma (ad esempio per archiviare le foto caricate).',
  'legalTerms3Heading': '3. Requisiti e account',
  'legalTerms3Bullet1': 'Devi avere almeno 18 anni e la capacità di stipulare un contratto vincolante.',
  'legalTerms3Bullet2': 'Devi fornire nome, e-mail, telefono, paese e password accurati e mantenerli aggiornati.',
  'legalTerms3Bullet3': 'Una stessa persona può utilizzare un solo account WWNGO come Mittente, Viaggiatore e/o Destinatario. I presenti Termini si applicano a ciascun ruolo utilizzato.',
  'legalTerms3Bullet4': 'La verifica di e-mail e telefono, e la verifica dell\'identità (KYC) tramite il nostro partner Sumsub, sono richieste prima di pubblicare consegne, elencare viaggi, fare offerte, accettare pacchi o movimentare denaro.',
  'legalTerms3Bullet5': 'Sei responsabile dell\'attività sul tuo account. Non condividere le credenziali di accesso. Segnala a support@wwngo.com eventuali accessi non autorizzati sospetti.',
  'legalTerms4Heading': '4. Responsabilità del Mittente',
  'legalTerms4Body': 'Quando agisci come Mittente, pubblichi una richiesta di consegna (città-città o paese-paese), descrivi il pacco, fissi un budget, aggiungi foto e indichi un Destinatario. Accetti di:',
  'legalTerms4Bullet1': 'Fornire in modo veritiero categoria, dimensioni, peso, descrizione del contenuto, percorso, data del viaggio e preferenze di incontro del pacco.',
  'legalTerms4Bullet2': 'Inviare solo articoli legali da possedere e trasportare sul percorso scelto, incluse le regole doganali e aeree per i viaggi internazionali.',
  'legalTerms4Bullet3': 'Non elencare mai articoli proibiti, pericolosi o illegali (vedi Sezione 10).',
  'legalTerms4Bullet4': 'Finanziare il deposito a garanzia per il pagamento concordato al viaggiatore quando accetti un\'offerta o una controfferta, e pagare la tua commissione piattaforma da Mittente al momento di Paga ora (2 \$ per Documento e Oggetto, o 3 \$ se copri la commissione del destinatario). Anche le commissioni piattaforma di Viaggiatore e Destinatario vengono riscosse al momento di Paga ora (prima dal portafoglio, poi con carta).',
  'legalTerms4Bullet5': 'Incontrare il Viaggiatore nel luogo di incontro di origine concordato e completare il Checkpoint NFC 1 (Mittente ↔ Viaggiatore) per confermare la consegna.',
  'legalTerms4Bullet6': 'Comunicare solo tramite la chat WWNGO per questa consegna, e rispettare le cancellazioni e i tempi descritti nell\'app.',
  'legalTerms5Heading': '5. Responsabilità del Viaggiatore',
  'legalTerms5Body': 'Quando agisci come Viaggiatore, pubblichi un viaggio, esamini le richieste di pacchi corrispondenti, accetti o fai controfferte, e trasporti il pacco durante il tuo viaggio. Accetti di:',
  'legalTerms5Bullet1': 'Pubblicare origine, destinazione, data del viaggio e capacità accurate, e accettare solo pacchi che puoi trasportare legalmente e in sicurezza.',
  'legalTerms5Bullet2': 'Pagare le commissioni piattaforma Viaggiatore applicabili (3 \$ per Documento e Oggetto) dal tuo portafoglio (o con carta se necessario) quando il Mittente completa Paga ora.',
  'legalTerms5Bullet3': 'Confermare o proporre i luoghi di incontro, completare il Checkpoint NFC 1 con il Mittente, mantenere il pacco al sicuro durante il trasporto e completare il Checkpoint NFC 2 (Viaggiatore ↔ Destinatario) a destinazione.',
  'legalTerms5Bullet4': 'Non aprire, usare, scambiare o abbandonare un pacco, e non subaffidare la consegna fuori da WWNGO.',
  'legalTerms5Bullet5': 'Aggiornare in buona fede lo stato della spedizione (ad esempio all\'inizio del trasporto) e rispondere prontamente in chat.',
  'legalTerms5Bullet6': 'Rispettare le dichiarazioni aeree, di frontiera e doganali. Sei responsabile di ciò che trasporti fisicamente.',
  'legalTerms6Heading': '6. Responsabilità del Destinatario',
  'legalTerms6Body': 'Quando agisci come Destinatario, sei indicato in una consegna, accetti la richiesta in arrivo e ritiri il pacco a destinazione. Accetti di:',
  'legalTerms6Bullet1': 'Esaminare i dettagli del pacco prima di accettare. Accettare costituisce solo consenso — una commissione piattaforma Destinatario (2 \$ per Documento e Oggetto) viene riscossa al momento di Paga ora del mittente, a meno che il mittente non la copra.',
  'legalTerms6Bullet2': 'Essere disponibile all\'incontro di destinazione, verificare il pacco e completare il Checkpoint NFC 2 (Viaggiatore ↔ Destinatario) per confermare la consegna.',
  'legalTerms6Bullet3': 'Apri prontamente una controversia in-app se il pacco è mancante, danneggiato o non conforme alla descrizione, invece di completare la conferma NFC se non accetti i beni.',
  'legalTerms6Bullet4': 'Mantenere i dati di contatto accurati affinché Mittente e Viaggiatore possano coordinarsi.',
  'legalTerms7Heading': '7. Corrispondenza, offerte e prenotazione',
  'legalTerms7Body': 'I Mittenti possono trovare viaggiatori e inviare richieste. I Viaggiatori possono ricevere richieste corrispondenti, accettarle, rifiutarle o inviare una controfferta. Una prenotazione viene creata solo quando il Mittente accetta un prezzo, il KYC e la verifica richiesti sono completati, il deposito a garanzia è finanziato con successo e le commissioni piattaforma vengono riscosse come indicato. La selezione di un Viaggiatore blocca la prenotazione. Se una finestra di pagamento o un timer di accettazione scade, la prenotazione può essere annullata automaticamente e il capitale del deposito a garanzia viene rimborsato secondo la Sezione 12.',
  'legalTerms8Heading': '8. Luoghi di incontro e chat',
  'legalTerms8Body': 'Le parti coordinano un incontro pubblico e appropriato utilizzando gli strumenti di localizzazione dell\'app. Un incontro è confermato quando le parti richieste lo accettano nell\'app. La chat tra Mittente–Viaggiatore, Mittente–Destinatario e Viaggiatore–Destinatario si sblocca in base allo stato della consegna. Non condividere i dettagli di pagamento fuori piattaforma né spostare l\'accordo fuori da WWNGO. I pagamenti fuori piattaforma annullano la protezione del deposito a garanzia.',
  'legalTerms9Heading': '9. Checkpoint NFC e conferma della consegna',
  'legalTerms9Bullet1': 'Il Checkpoint NFC 1 (Mittente ↔ Viaggiatore) conferma che il Mittente ha consegnato il pacco al Viaggiatore.',
  'legalTerms9Bullet2': 'Il Checkpoint NFC 2 (Viaggiatore ↔ Destinatario) conferma che il Destinatario ha ricevuto il pacco. Entrambe le parti devono completare il proprio tocco. Il completamento con successo del Checkpoint 2 contrassegna la spedizione come Consegnata e rilascia il deposito a garanzia al Viaggiatore (salvo che sia congelato da una controversia).',
  'legalTerms9Bullet3': 'L\'NFC è uno strumento di conferma, non una garanzia delle condizioni del pacco. Foto, chat, tracciamento e registri delle controversie possono comunque essere utilizzati in una revisione.',
  'legalTerms9Bullet4': 'L\'uso improprio dell\'NFC (confermare senza una consegna reale, forzare un tocco o falsificare i dispositivi) è motivo di sospensione e congelamento del deposito a garanzia.',
  'legalTerms10Heading': '10. Articoli proibiti e tolleranza zero',
  'legalTerms10Body': 'Non devi inviare, trasportare o richiedere: droghe illegali, armi, esplosivi, materiali pericolosi, merce rubata, articoli contraffatti, contanti o strumenti al portatore oltre quanto consentito dalla legge locale, animali vivi, resti umani, o qualsiasi articolo vietato dal vettore, dalla compagnia aerea o dal paese di destinazione. Sono vietati frode, identità falsa, foto false, molestie, manipolazione delle valutazioni e tentativi di eludere il deposito a garanzia. WWNGO può sospendere account, congelare il deposito a garanzia e segnalare attività illegali alle autorità.',
  'legalTerms11Heading': '11. Pagamenti, portafogli e deposito a garanzia',
  'legalTerms11Bullet1': 'Hai un unico portafoglio WWNGO condiviso tra le attività di Mittente, Viaggiatore e Destinatario. Ricarica con Stripe e preleva tramite Stripe Connect una volta che un account di pagamento è collegato e pronto. Lo storico delle transazioni registra a quale ruolo si riferisce ogni voce.',
  'legalTerms11Bullet2': 'Quando un Mittente accetta un Viaggiatore, il pagamento concordato viene spostato dal saldo disponibile del Mittente al deposito a garanzia (un pagamento con carta può coprire un\'eventuale carenza). Il deposito a garanzia non è prelevabile da nessuna parte fino al rilascio, al rimborso o a una decisione sulla controversia.',
  'legalTerms11Bullet3': 'Le commissioni piattaforma (Mittente, Viaggiatore e/o Destinatario, incluendo l\'opzione facoltativa in cui il Mittente copre la commissione del Destinatario) vengono comunicate prima della conferma e riscosse come indicato.',
  'legalTerms11Bullet4': 'Il deposito a garanzia viene rilasciato al Viaggiatore dopo il Checkpoint NFC 2 / Consegnato, salvo che sia congelato. WWNGO non è una banca; i saldi del portafoglio sono registri della Piattaforma utilizzati per regolare le transazioni del marketplace.',
  'legalTerms12Heading': '12. Cancellazioni e rimborsi',
  'legalTerms12Body': 'Le consegne prenotate possono essere annullate prima che il viaggio sia in transito o consegnato, secondo le regole dell\'app. Il capitale del deposito a garanzia viene rimborsato al Mittente. Le commissioni piattaforma vengono rimborsate alle parti pagatrici se la cancellazione avviene con più di 24 ore di anticipo rispetto al viaggio; entro le 24 ore, le commissioni piattaforma generalmente non sono rimborsabili. Le consegne pubblicate ma non ancora prenotate possono essere annullate secondo le regole di pubblicazione dell\'app. La cancellazione automatica (ad esempio finestre Destinatario non pagate o timer di accettazione scaduti) rimborsa il capitale del deposito a garanzia come indicato nel prodotto. Le ricariche e i pagamenti già completati non vengono annullati, salvo quando richiesto dalla legge o da un esito formale di controversia.',
  'legalTerms13Heading': '13. Tracciamento, foto e recensioni',
  'legalTerms13Body': 'Gli aggiornamenti di stato, le foto del pacco e i dati GPS o di incontro che fornisci vengono utilizzati per gestire la consegna. Dopo la consegna, le parti possono lasciare recensioni. Le recensioni devono essere oneste e riguardare la transazione. WWNGO può nascondere o rimuovere recensioni abusive o false.',
  'legalTerms14Heading': '14. Controversie',
  'legalTerms14Body': 'Se qualcosa va storto (danno, mancata consegna, articolo errato, controversia NFC), apri una controversia nell\'app. L\'apertura di una controversia congela il deposito a garanzia mentre WWNGO esamina i registri della consegna, le foto, la chat, i checkpoint NFC e i dati identificativi. Non completare il Checkpoint NFC 2 se intendi contestare la ricezione. La decisione di WWNGO sul deposito a garanzia (rilascio, rimborso o divisione) è definitiva tra le parti sulla Piattaforma, senza limitare eventuali diritti che potresti avere nei confronti di un altro utente dinanzi a un tribunale competente. Contestazioni di pagamento o reclami fuori piattaforma possono comunque comportare un\'azione sull\'account.',
  'legalTerms15Heading': '15. Limitazione di responsabilità',
  'legalTerms15Body': 'Nella misura massima consentita dalla legge, WWNGO non è responsabile per perdite, ritardi, danni, sequestri o problemi doganali causati da utenti, vettori o governi; per gli atti di Mittenti, Viaggiatori o Destinatari; né per danni indiretti, incidentali o consequenziali. La nostra responsabilità totale nei tuoi confronti per un reclamo relativo alla Piattaforma è limitata al maggiore tra (a) le commissioni piattaforma pagate a WWNGO per la consegna contestata nei 12 mesi precedenti il reclamo, oppure (b) 50 USD. Nulla nei presenti Termini esclude responsabilità che non possono essere legalmente escluse (incluse quelle per frode o morte/lesione personale causata da negligenza, laddove tale esclusione sia vietata).',
  'legalTerms16Heading': '16. Modifiche, sospensione e contatti',
  'legalTerms16Body': 'Possiamo aggiornare i presenti Termini. L\'uso continuato dopo un avviso in-app costituisce accettazione dei Termini rivisti. Possiamo sospendere o chiudere account che violano i presenti Termini. Domande: support@wwngo.com. I presenti Termini costituiscono l\'intero accordo relativo al tuo utilizzo della Piattaforma e sono disciplinati dalle leggi applicabili al luogo di stabilimento di WWNGO, senza pregiudizio per le tutele obbligatorie dei consumatori nel tuo paese di residenza.',
  'legalPrivacy1Heading': '1. Introduzione',
  'legalPrivacy1Body': 'La presente Informativa sulla privacy spiega come WWNGO raccoglie, utilizza, condivide e protegge i dati personali quando utilizzi il nostro marketplace peer-to-peer di pacchi come Mittente, Viaggiatore e/o Destinatario. Si applica alla prima registrazione e a ogni utilizzo successivo dello stesso account. Creando un account, dichiari di aver preso visione della presente Informativa. Per domande, contatta privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. Dati che raccogliamo',
  'legalPrivacy2Bullet1': 'Dati dell\'account: nome completo, e-mail, telefono (con prefisso internazionale), password (memorizzata in forma cifrata/hash), paese, ruolo selezionato e dettagli del profilo che aggiungi.',
  'legalPrivacy2Bullet2': 'Dati di verifica: stato OTP di e-mail e telefono; informazioni KYC elaborate da Sumsub (documento d\'identità, selfie, prova di vitalità e risultato della verifica). WWNGO conserva lo stato e i riferimenti della verifica, non le immagini grezze del documento, salvo quando richiesto dal flusso del nostro partner KYC.',
  'legalPrivacy2Bullet3': 'Dati di consegna: percorsi, date, categoria/dimensioni/peso/descrizione del pacco, foto, contatto del Destinatario, indirizzi di incontro, offerte e controfferte, stato della spedizione, registri dei checkpoint NFC, registri di cancellazione e controversia.',
  'legalPrivacy2Bullet4': 'Comunicazioni: messaggi di chat in-app, allegati ed e-mail di assistenza.',
  'legalPrivacy2Bullet5': 'Pagamenti: saldo e registro unificati del portafoglio (disponibile e deposito a garanzia), descrizioni delle transazioni con etichette del ruolo di attività, identificativi di pagamento Stripe e Connect. I numeri di carta sono gestiti da Stripe e non sono memorizzati sui server di WWNGO.',
  'legalPrivacy2Bullet6': 'Dispositivo e utilizzo: versione dell\'app, tipo di dispositivo, indirizzo IP, log di arresto anomalo e token per le notifiche push (FCM) per l\'invio degli avvisi.',
  'legalPrivacy3Heading': '3. Come utilizziamo i tuoi dati',
  'legalPrivacy3Bullet1': 'Creare e proteggere il tuo account, e consentirti di passare tra Mittente, Viaggiatore e Destinatario.',
  'legalPrivacy3Bullet2': 'Abbinare i pacchi ai viaggi, mostrare gli annunci ed eseguire offerte, timer e blocchi di prenotazione.',
  'legalPrivacy3Bullet3': 'Riscuotere le commissioni piattaforma, mantenere i fondi del Mittente in deposito a garanzia, rilasciare i pagamenti ai Viaggiatori dopo il Checkpoint NFC 2, e gestire i rimborsi in caso di cancellazione o controversia.',
  'legalPrivacy3Bullet4': 'Consentire il coordinamento degli incontri, la chat, il tracciamento, la conferma NFC, le recensioni e le notifiche.',
  'legalPrivacy3Bullet5': 'Prevenire le frodi, applicare i presenti Termini, esaminare le controversie e adempiere agli obblighi legali.',
  'legalPrivacy3Bullet6': 'Migliorare l\'affidabilità e l\'assistenza clienti. Non vendiamo i tuoi dati personali.',
  'legalPrivacy4Heading': '4. Condivisione specifica per ruolo su una consegna',
  'legalPrivacy4Body': 'Per completare una prenotazione, informazioni limitate sul profilo e sulla consegna vengono mostrate solo alle altre parti di quella spedizione — ad esempio nomi, valutazioni, percorso, riepilogo del pacco, stato dell\'incontro e chat. Un Viaggiatore non riceve i dettagli completi della tua carta di pagamento. Un Destinatario vede ciò di cui ha bisogno per accettare e ritirare il pacco. Dopo la consegna o la cancellazione, l\'accesso segue le regole del prodotto (storico, recensioni, fascicoli delle controversie).',
  'legalPrivacy5Heading': '5. Responsabili del trattamento e terze parti',
  'legalPrivacy5Bullet1': 'Sumsub — verifica dell\'identità (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — ricarica del portafoglio, intenti di pagamento e pagamenti Connect.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — notifiche push.',
  'legalPrivacy5Bullet4': 'Fornitori di e-mail/SMS — codici monouso ed e-mail transazionali.',
  'legalPrivacy5Bullet5': 'Fornitori di hosting e database che elaborano i dati secondo le nostre istruzioni.',
  'legalPrivacy5Bullet6': 'Le autorità, quando richiesto dalla legge o per proteggere gli utenti da un danno grave.',
  'legalPrivacy6Heading': '6. Conservazione, sicurezza e trasferimento internazionale',
  'legalPrivacy6Body': 'Conserviamo i registri di account, portafoglio, consegna, NFC e controversie per tutta la durata del tuo account e per un periodo ragionevole successivo, per completare i pagamenti, gestire le contestazioni di pagamento e adempiere agli obblighi contabili e legali. Utilizziamo la crittografia in transito, controlli di accesso e una contabilità unificata del portafoglio. I dati possono essere elaborati in paesi diversi dal tuo; utilizziamo garanzie adeguate con i responsabili del trattamento. Nessun metodo di trasmissione è sicuro al 100%.',
  'legalPrivacy7Heading': '7. I tuoi diritti',
  'legalPrivacy7Body': 'Fatto salvo il diritto applicabile, puoi richiedere l\'accesso, la rettifica, la cancellazione, la limitazione o l\'esportazione dei tuoi dati personali, e opporti a determinati trattamenti. Puoi revocare il consenso quando il trattamento si basa su di esso (ciò non incide sulla liceità del trattamento precedente). Alcuni registri (deposito a garanzia, stato KYC, registri completati) possono essere conservati quando siamo obbligati a mantenerli. Contatta privacy@wwngo.com. Puoi anche presentare un reclamo alla tua autorità locale di protezione dei dati.',
  'legalPrivacy8Heading': '8. Minori, modifiche e contatti',
  'legalPrivacy8Body': 'WWNGO non è destinato a minori di 18 anni. Non raccogliamo consapevolmente i loro dati. Possiamo aggiornare questa Informativa e pubblicheremo la nuova data nell\'app. Le modifiche rilevanti potranno essere notificate in-app o via e-mail. Contatti: privacy@wwngo.com (privacy) o support@wwngo.com (generale).',
  'legalCookie1Heading': 'Cosa sono i cookie?',
  'legalCookie1Body': 'I cookie sono piccoli file di testo memorizzati sul tuo dispositivo. Aiutano a ricordare le preferenze e a capire come utilizzi il nostro sito.',
  'legalCookie2Heading': 'Cookie che utilizziamo',
  'legalCookie2Bullet1': 'Essenziali — necessari per la sicurezza e le sessioni',
  'legalCookie2Bullet2': 'Analitici — ci aiutano a migliorare le prestazioni (opzionali)',
  'legalCookie2Bullet3': 'Preferenze — ricordano le tue impostazioni (opzionali)',
  'legalCookie3Heading': 'Gestione dei cookie',
  'legalCookie3Body': 'Puoi controllare i cookie nelle impostazioni del tuo browser. La disattivazione dei cookie essenziali potrebbe influire sulla funzionalità del sito.',
