  'emailDelayedBackupCode': 'E-mail is vertraagd of mislukt. Je kunt inloggen met de backupcode {code}.',
  'enableBiometricAfterLogin': 'Log eerst in met e-mail en wachtwoord en schakel daarna {label} in via Instellingen (of wanneer daarom wordt gevraagd).',
  'biometricWebOnlyInfo': 'Inloggen met {label} werkt in de Android/iOS-app, niet in de browser.',
  'loginPasswordThenBiometric': 'Log eerst in met je wachtwoord en schakel daarna {label} in.',
  'couldNotEnableBiometric': 'Kon {label} niet inschakelen. Probeer het opnieuw.',
  'paymentFailedBookingNotCreatedDetail': 'Betaling mislukt. De boeking is niet aangemaakt. {detail}',
  'travelerRequestLimitMessage': 'Je kunt maximaal {n} reizigers aanvragen voor dit pakket.',
  'cancelBlockedHoursMessage': 'Annuleren is alleen toegestaan ten minste {hours} uur voor de vluchtdatum.',
  'minWalletTripMessage': 'Een minimaal walletsaldo van {amount} is vereist om een reis aan te maken.',
  'minWalletDeliveryMessage': 'Een minimaal walletsaldo van {amount} is vereist om een levering aan te maken.',
  'walletNeededAcceptMessage': 'Je hebt minimaal {amount} in je wallet nodig om te accepteren (inclusief platformkosten).',
  'bidCannotExceedMaxBudget': 'Bod mag het maximale budget van de verzender niet overschrijden ({amount}).',
  'walletMustHaveAtLeastFinalBudget': 'De wallet moet minstens {amount} bevatten om een definitief budget te versturen.',
  'legalTermsTitle': 'Algemene voorwaarden',
  'legalPrivacyTitle': 'Privacybeleid',
  'legalLastUpdatedDate': '4 september 2026',
  'legalTerms1Heading': '1. Aanvaarding van deze Voorwaarden',
  'legalTerms1Body': 'Deze Algemene voorwaarden (“Voorwaarden”) regelen uw gebruik van de WWNGO-mobiele app en de bijbehorende diensten (het “Platform”). WWNGO is een peer-to-peer marktplaats die Afzenders die een pakket willen laten vervoeren, Reizigers die al in die richting reizen, en Ontvangers die het pakket op de bestemming in ontvangst nemen, met elkaar verbindt. Door een account aan te maken en “Ik ga akkoord met de Voorwaarden en het Privacybeleid” aan te vinken, sluit u een bindende overeenkomst met WWNGO. Als u niet akkoord gaat, registreer u dan niet en gebruik het Platform niet.',
  'legalTerms2Heading': '2. Wat WWNGO is — en niet is',
  'legalTerms2Body': 'WWNGO faciliteert matching, in-app chat, coördinatie van ontmoetingen, identiteitscontroles, betalingen via de wallet, escrow, NFC-bevestiging van overdracht, tracking, beoordelingen en geschillenbeoordeling. WWNGO is geen koerier, postbedrijf, expediteur, douane-expediteur, verzekeraar of werkgever van Reizigers. De levering wordt uitgevoerd door onafhankelijke gebruikers. WWNGO neemt geen pakketten in bezit, behalve wanneer dit nodig is om het Platform te laten werken (bijvoorbeeld het opslaan van foto\'s die u uploadt).',
  'legalTerms3Heading': '3. Geschiktheid en accounts',
  'legalTerms3Bullet1': 'U moet minstens 18 jaar oud zijn en in staat zijn een bindende overeenkomst te sluiten.',
  'legalTerms3Bullet2': 'U moet een juiste naam, e-mailadres, telefoonnummer, land en wachtwoord opgeven en deze up-to-date houden.',
  'legalTerms3Bullet3': 'Eén persoon mag één WWNGO-account gebruiken als Afzender, Reiziger en/of Ontvanger. Deze Voorwaarden zijn van toepassing op elke rol die u gebruikt.',
  'legalTerms3Bullet4': 'E-mail- en telefoonverificatie, en identiteitsverificatie (KYC) via onze partner Sumsub, zijn vereist voordat u leveringen plaatst, reizen aanbiedt, biedt, pakketten accepteert of geld verplaatst.',
  'legalTerms3Bullet5': 'U bent verantwoordelijk voor de activiteit op uw account. Deel uw inloggegevens niet. Meld het bij support@wwngo.com als u onbevoegde toegang vermoedt.',
  'legalTerms4Heading': '4. Verantwoordelijkheden van de Afzender',
  'legalTerms4Body': 'Wanneer u optreedt als Afzender, plaatst u een leveringsverzoek (stad-naar-stad of land-naar-land), beschrijft u het pakket, stelt u een budget vast, voegt u foto\'s toe en geeft u een Ontvanger aan. U gaat ermee akkoord om:',
  'legalTerms4Bullet1': 'Een waarheidsgetrouwe pakketcategorie, afmeting, gewicht, inhoudsbeschrijving, route, reisdatum en ontmoetingsvoorkeuren op te geven.',
  'legalTerms4Bullet2': 'Alleen items te verzenden die legaal bezeten en vervoerd mogen worden op de gekozen route, inclusief douane- en luchtvaartregels voor internationale reizen.',
  'legalTerms4Bullet3': 'Nooit verboden, gevaarlijke of illegale goederen aan te bieden (zie Sectie 10).',
  'legalTerms4Bullet4': 'Escrow te financieren voor de overeengekomen uitbetaling aan de reiziger wanneer u een bod of tegenbod accepteert, en uw platformkosten als Afzender te betalen bij Nu betalen (\$2 voor Document en Object, of \$3 als u de kosten van de ontvanger overneemt). De platformkosten van Reiziger en Ontvanger worden ook geïnd bij Nu betalen (eerst vanuit de wallet, dan met kaart).',
  'legalTerms4Bullet5': 'De Reiziger te ontmoeten op de overeengekomen ontmoetingsplaats van herkomst en NFC-controlepunt 1 (Afzender ↔ Reiziger) te voltooien om de overdracht te bevestigen.',
  'legalTerms4Bullet6': 'Alleen via de WWNGO-chat te communiceren over deze levering, en annuleringen en tijdslimieten zoals beschreven in de app te respecteren.',
  'legalTerms5Heading': '5. Verantwoordelijkheden van de Reiziger',
  'legalTerms5Body': 'Wanneer u optreedt als Reiziger, plaatst u een reis, bekijkt u overeenkomende pakketverzoeken, accepteert u of doet u tegenbiedingen, en vervoert u het pakket tijdens uw reis. U gaat ermee akkoord om:',
  'legalTerms5Bullet1': 'Een juiste herkomst, bestemming, reisdatum en capaciteit te plaatsen, en alleen pakketten te accepteren die u legaal en veilig kunt vervoeren.',
  'legalTerms5Bullet2': 'De toepasselijke platformkosten voor Reizigers (\$3 voor Document en Object) vanuit uw wallet (of kaart indien nodig) te betalen wanneer de Afzender Nu betalen voltooit.',
  'legalTerms5Bullet3': 'Ontmoetingsplaatsen te bevestigen of voor te stellen, NFC-controlepunt 1 met de Afzender te voltooien, het pakket veilig te houden tijdens het transport, en NFC-controlepunt 2 (Reiziger ↔ Ontvanger) te voltooien op de bestemming.',
  'legalTerms5Bullet4': 'Een pakket niet te openen, te gebruiken, te ruilen of achter te laten, en de levering niet buiten WWNGO uit te besteden.',
  'legalTerms5Bullet5': 'De verzendstatus in goed vertrouwen bij te werken (bijvoorbeeld bij het starten van het transport) en snel te reageren in de chat.',
  'legalTerms5Bullet6': 'De verklaringen van de luchtvaartmaatschappij, grens en douane na te leven. U bent verantwoordelijk voor wat u fysiek bij u draagt.',
  'legalTerms6Heading': '6. Verantwoordelijkheden van de Ontvanger',
  'legalTerms6Body': 'Wanneer u optreedt als Ontvanger, staat u vermeld op een levering, accepteert u het inkomende verzoek en neemt u het pakket in ontvangst op de bestemming. U gaat ermee akkoord om:',
  'legalTerms6Bullet1': 'Pakketdetails te bekijken voordat u accepteert. Accepteren is alleen toestemming — een platformkosten voor Ontvanger (\$2 voor Document en Object) wordt in rekening gebracht bij Nu betalen van de afzender, tenzij de afzender deze overneemt.',
  'legalTerms6Bullet2': 'Beschikbaar te zijn bij de ontmoeting op de bestemming, het pakket te controleren en NFC-controlepunt 2 (Reiziger ↔ Ontvanger) te voltooien om de levering te bevestigen.',
  'legalTerms6Bullet3': 'Snel een geschil in de app te openen als het pakket ontbreekt, beschadigd is of niet overeenkomt met de beschrijving, in plaats van de NFC-bevestiging te voltooien als u de goederen niet accepteert.',
  'legalTerms6Bullet4': 'Contactgegevens juist te houden zodat de Afzender en de Reiziger kunnen coördineren.',
  'legalTerms7Heading': '7. Matching, biedingen en boeking',
  'legalTerms7Body': 'Afzenders kunnen reizigers ontdekken en verzoeken versturen. Reizigers kunnen overeenkomende verzoeken ontvangen, accepteren, afwijzen of een tegenbod versturen. Een boeking wordt alleen aangemaakt wanneer de Afzender een prijs accepteert, de vereiste KYC en verificatie zijn afgerond, escrow succesvol is gefinancierd, en platformkosten zijn geïnd zoals weergegeven. Het selecteren van een Reiziger vergrendelt de boeking. Als een betalingsvenster of accepteertimer verloopt, kan de boeking automatisch worden geannuleerd en wordt de hoofdsom van de escrow terugbetaald volgens Sectie 12.',
  'legalTerms8Heading': '8. Ontmoetingsplaatsen en chat',
  'legalTerms8Body': 'Partijen coordineren een openbare, geschikte ontmoeting met behulp van de locatietools in de app. Een ontmoeting wordt bevestigd wanneer de vereiste partijen deze in de app accepteren. Chat tussen Afzender–Reiziger, Afzender–Ontvanger en Reiziger–Ontvanger wordt ontgrendeld op basis van de leveringsstatus. Deel geen betalingsgegevens buiten het platform en verplaats de deal niet buiten WWNGO. Betalingen buiten het platform maken de escrowbescherming ongeldig.',
  'legalTerms9Heading': '9. NFC-controlepunten en leveringsbevestiging',
  'legalTerms9Bullet1': 'NFC-controlepunt 1 (Afzender ↔ Reiziger) bevestigt dat de Afzender het pakket aan de Reiziger heeft overhandigd.',
  'legalTerms9Bullet2': 'NFC-controlepunt 2 (Reiziger ↔ Ontvanger) bevestigt dat de Ontvanger het pakket heeft ontvangen. Beide partijen moeten hun tik voltooien. Een succesvol Controlepunt 2 markeert de zending als Afgeleverd en geeft de escrow vrij aan de Reiziger (tenzij bevroren door een geschil).',
  'legalTerms9Bullet3': 'NFC is een bevestigingsmiddel, geen garantie voor de staat van het pakket. Foto\'s, chat, tracking en geschillendossiers kunnen nog steeds worden gebruikt in een beoordeling.',
  'legalTerms9Bullet4': 'Misbruik van NFC (bevestigen zonder echte overdracht, een tik afdwingen of apparaten vervalsen) is grond voor schorsing en bevriezing van de escrow.',
  'legalTerms10Heading': '10. Verboden items en zerotolerantiegedrag',
  'legalTerms10Body': 'U mag niet verzenden, vervoeren of vragen om: illegale drugs, wapens, explosieven, gevaarlijke stoffen, gestolen goederen, nagemaakte artikelen, contant geld of onderhandse instrumenten die verder gaan dan de lokale wet toestaat, levende dieren, menselijke resten, of enig item dat verboden is door de vervoerder, luchtvaartmaatschappij of het land van bestemming. Fraude, valse identiteit, valse foto\'s, intimidatie, manipulatie van beoordelingen en poging om escrow te omzeilen zijn verboden. WWNGO kan accounts opschorten, escrow bevriezen en illegale activiteiten melden aan de autoriteiten.',
  'legalTerms11Heading': '11. Betalingen, wallets en escrow',
  'legalTerms11Bullet1': 'U heeft één WWNGO-wallet die wordt gedeeld tussen uw activiteiten als Afzender, Reiziger en Ontvanger. Laad op met Stripe en neem op via Stripe Connect zodra een uitbetalingsaccount is gekoppeld en gereed is. De transactiegeschiedenis registreert bij welke rol elke vermelding hoort.',
  'legalTerms11Bullet2': 'Wanneer een Afzender een Reiziger accepteert, wordt de overeengekomen uitbetaling verplaatst van het beschikbare saldo van de Afzender naar escrow (een kaartbetaling kan een tekort dekken). Escrow kan door geen van de partijen worden opgenomen totdat er vrijgave, terugbetaling of een geschilbeslissing is.',
  'legalTerms11Bullet3': 'Platformkosten (Afzender, Reiziger en/of Ontvanger, inclusief de optionele mogelijkheid dat de Afzender de kosten van de Ontvanger overneemt) worden bekendgemaakt voordat u bevestigt en worden in rekening gebracht zoals weergegeven.',
  'legalTerms11Bullet4': 'Escrow wordt vrijgegeven aan de Reiziger na NFC-controlepunt 2 / Afgeleverd, tenzij bevroren. WWNGO is geen bank; walletsaldi zijn registraties van het Platform die worden gebruikt om marktplaatstransacties te verrekenen.',
  'legalTerms12Heading': '12. Annuleringen en terugbetalingen',
  'legalTerms12Body': 'Geboekte leveringen kunnen worden geannuleerd voordat de reis onderweg is of is afgeleverd, onder voorbehoud van de regels in de app. De hoofdsom van de escrow wordt terugbetaald aan de Afzender. Platformkosten worden terugbetaald aan de betalende partijen als de annulering meer dan 24 uur voor de reis plaatsvindt; binnen 24 uur zijn platformkosten over het algemeen niet terugbetaalbaar. Geplaatste leveringen die nog niet geboekt zijn, kunnen worden geannuleerd volgens de plaatsingsregels in de app. Automatische annulering (bijvoorbeeld onbetaalde Ontvanger-vensters of verlopen accepteertimers) betaalt de hoofdsom van de escrow terug zoals aangegeven in het product. Opwaarderingen en voltooide uitbetalingen worden niet teruggedraaid, behalve wanneer dit wettelijk vereist is of als resultaat van een formele geschilbeslissing.',
  'legalTerms13Heading': '13. Tracking, foto\'s en beoordelingen',
  'legalTerms13Body': 'Statusupdates, pakketfoto\'s en GPS- of ontmoetingsgegevens die u verstrekt, worden gebruikt om de levering uit te voeren. Na de levering kunnen partijen beoordelingen achterlaten. Beoordelingen moeten eerlijk zijn en over de transactie gaan. WWNGO kan misbruikende of valse beoordelingen verbergen of verwijderen.',
  'legalTerms14Heading': '14. Geschillen',
  'legalTerms14Body': 'Als er iets misgaat (schade, niet-levering, verkeerd item, NFC-geschil), dien dan een geschil in de app in. Het indienen van een geschil bevriest de escrow terwijl WWNGO leveringsgegevens, foto\'s, chat, NFC-controlepunten en identiteitsgegevens beoordeelt. Voltooi NFC-controlepunt 2 niet als u de ontvangst wilt betwisten. De beslissing van WWNGO over de escrow (vrijgave, terugbetaling of verdeling) is definitief tussen de partijen op het Platform, zonder enige rechten te beperken die u mogelijk heeft tegen een andere gebruiker bij een bevoegde rechtbank. Terugboekingen of claims buiten het platform kunnen nog steeds leiden tot actie op het account.',
  'legalTerms15Heading': '15. Beperking van aansprakelijkheid',
  'legalTerms15Body': 'Voor zover maximaal toegestaan door de wet, is WWNGO niet aansprakelijk voor verlies, vertraging, schade, inbeslagname of douaneproblemen veroorzaakt door gebruikers, vervoerders of overheden; voor handelingen van Afzenders, Reizigers of Ontvangers; of voor indirecte, incidentele of gevolgschade. Onze totale aansprakelijkheid tegenover u voor een claim met betrekking tot het Platform is beperkt tot het hoogste van (a) de platformkosten die u aan WWNGO heeft betaald voor de betwiste levering in de 12 maanden voorafgaand aan de claim, of (b) USD 50. Niets in deze Voorwaarden sluit aansprakelijkheid uit die wettelijk niet kan worden uitgesloten (inclusief voor fraude of overlijden/persoonlijk letsel veroorzaakt door nalatigheid, waar een dergelijke uitsluiting verboden is).',
  'legalTerms16Heading': '16. Wijzigingen, opschorting en contact',
  'legalTerms16Body': 'Wij kunnen deze Voorwaarden bijwerken. Voortgezet gebruik na een melding in de app vormt aanvaarding van de herziene Voorwaarden. Wij kunnen accounts opschorten of beëindigen die deze Voorwaarden overtreden. Vragen: support@wwngo.com. Deze Voorwaarden vormen de volledige overeenkomst voor uw gebruik van het Platform en worden beheerst door de wetten die van toepassing zijn op de vestigingsplaats van WWNGO, onverminderd verplichte consumentenbeschermingen in uw land van verblijf.',
  'legalPrivacy1Heading': '1. Inleiding',
  'legalPrivacy1Body': 'Dit Privacybeleid legt uit hoe WWNGO persoonsgegevens verzamelt, gebruikt, deelt en beschermt wanneer u onze peer-to-peer pakketmarktplaats gebruikt als Afzender, Reiziger en/of Ontvanger. Het is van toepassing op de eerste registratie en al het latere gebruik van hetzelfde account. Door een account aan te maken, erkent u dit Beleid. Voor vragen kunt u contact opnemen via privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. Gegevens die wij verzamelen',
  'legalPrivacy2Bullet1': 'Accountgegevens: volledige naam, e-mailadres, telefoonnummer (met landcode), wachtwoord (opgeslagen als hash), land, geselecteerde rol en profielgegevens die u toevoegt.',
  'legalPrivacy2Bullet2': 'Verificatiegegevens: OTP-status van e-mail en telefoon; KYC-informatie verwerkt door Sumsub (identiteitsdocument, selfie, liveness en verificatieresultaat). WWNGO bewaart de verificatiestatus en referenties, niet uw ruwe ID-afbeeldingen, behalve wanneer het proces van onze KYC-partner dit vereist.',
  'legalPrivacy2Bullet3': 'Leveringsgegevens: routes, data, pakketcategorie/afmeting/gewicht/beschrijving, foto\'s, contactgegevens van de Ontvanger, ontmoetingsadressen, biedingen en tegenbiedingen, verzendstatus, NFC-controlepuntregistraties, annulerings- en geschilregistraties.',
  'legalPrivacy2Bullet4': 'Communicatie: chatberichten in de app, bijlagen en support-e-mails.',
  'legalPrivacy2Bullet5': 'Betalingen: uniform walletsaldo en grootboek (beschikbaar en escrow), transactiebeschrijvingen met activiteitsrollabels, Stripe-betalings- en Connect-identificatoren. Kaartnummers worden verwerkt door Stripe en niet opgeslagen op WWNGO-servers.',
  'legalPrivacy2Bullet6': 'Apparaat en gebruik: app-versie, apparaattype, IP-adres, crashlogs en pushmeldingstokens (FCM) om waarschuwingen te bezorgen.',
  'legalPrivacy3Heading': '3. Hoe wij uw gegevens gebruiken',
  'legalPrivacy3Bullet1': 'Uw account aanmaken en beveiligen, en u laten wisselen tussen Afzender, Reiziger en Ontvanger.',
  'legalPrivacy3Bullet2': 'Pakketten koppelen aan reizen, aanbiedingen weergeven, en biedingen, timers en boekingsvergrendelingen uitvoeren.',
  'legalPrivacy3Bullet3': 'Platformkosten innen, geld van de Afzender in escrow houden, uitbetalingen aan Reizigers vrijgeven na NFC-controlepunt 2, en terugbetalingen verwerken bij annulering of geschil.',
  'legalPrivacy3Bullet4': 'Coordinatie van ontmoetingen, chat, tracking, NFC-bevestiging, beoordelingen en meldingen mogelijk maken.',
  'legalPrivacy3Bullet5': 'Fraude voorkomen, deze Voorwaarden handhaven, geschillen beoordelen en wettelijke verplichtingen naleven.',
  'legalPrivacy3Bullet6': 'Betrouwbaarheid en klantenservice verbeteren. Wij verkopen uw persoonsgegevens niet.',
  'legalPrivacy4Heading': '4. Roldeling bij een levering',
  'legalPrivacy4Body': 'Om een boeking te voltooien, wordt beperkte profiel- en leveringsinformatie alleen getoond aan de andere partijen bij die zending — bijvoorbeeld namen, beoordelingen, route, pakketoverzicht, ontmoetingsstatus en chat. Een Reiziger ontvangt niet uw volledige betaalkaartgegevens. Een Ontvanger ziet wat nodig is om het pakket te accepteren en op te halen. Na levering of annulering volgt de toegang de productregels (geschiedenis, beoordelingen, geschildossiers).',
  'legalPrivacy5Heading': '5. Verwerkers en derden',
  'legalPrivacy5Bullet1': 'Sumsub — identiteitsverificatie (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — opwaardering van de wallet, betalingsintenties en Connect-uitbetalingen.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — pushmeldingen.',
  'legalPrivacy5Bullet4': 'E-mail/sms-aanbieders — eenmalige codes en transactionele e-mail.',
  'legalPrivacy5Bullet5': 'Hosting- en database-aanbieders die gegevens verwerken op onze instructies.',
  'legalPrivacy5Bullet6': 'Autoriteiten wanneer dit wettelijk vereist is of om gebruikers te beschermen tegen ernstige schade.',
  'legalPrivacy6Heading': '6. Bewaring, beveiliging en internationale overdracht',
  'legalPrivacy6Body': 'Wij bewaren account-, grootboek-, leverings-, NFC- en geschilregistraties zolang u een account heeft en voor een redelijke periode daarna om uitbetalingen te voltooien, terugboekingen te behandelen en te voldoen aan boekhoudkundige en wettelijke verplichtingen. Wij gebruiken versleuteling tijdens overdracht, toegangscontroles en uniforme walletboekhouding. Gegevens kunnen worden verwerkt in andere landen dan het uwe; wij gebruiken passende waarborgen bij verwerkers. Geen enkele overdrachtsmethode is 100% veilig.',
  'legalPrivacy7Heading': '7. Uw rechten',
  'legalPrivacy7Body': 'Onder toepasselijk recht kunt u toegang, correctie, verwijdering, beperking of export van uw persoonsgegevens aanvragen, en bezwaar maken tegen bepaalde verwerkingen. U kunt uw toestemming intrekken wanneer de verwerking op toestemming is gebaseerd (dit heeft geen invloed op eerdere rechtmatige verwerking). Sommige registraties (escrow, KYC-status, voltooide grootboeken) kunnen worden bewaard wanneer wij deze moeten behouden. Neem contact op via privacy@wwngo.com. U kunt ook een klacht indienen bij uw lokale gegevensbeschermingsautoriteit.',
  'legalPrivacy8Heading': '8. Kinderen, wijzigingen en contact',
  'legalPrivacy8Body': 'WWNGO is niet gericht op kinderen onder de 18 jaar. Wij verzamelen niet bewust hun gegevens. Wij kunnen dit Beleid bijwerken en zullen de nieuwe datum in de app plaatsen. Belangrijke wijzigingen kunnen in de app of per e-mail worden gemeld. Contact: privacy@wwngo.com (privacy) of support@wwngo.com (algemeen).',
  'legalCookie1Heading': 'Wat zijn cookies?',
  'legalCookie1Body': 'Cookies zijn kleine tekstbestanden die op uw apparaat worden opgeslagen. Ze helpen voorkeuren te onthouden en te begrijpen hoe u onze site gebruikt.',
  'legalCookie2Heading': 'Cookies die wij gebruiken',
  'legalCookie2Bullet1': 'Essentieel — vereist voor beveiliging en sessies',
  'legalCookie2Bullet2': 'Analytisch — helpen ons de prestaties te verbeteren (optioneel)',
  'legalCookie2Bullet3': 'Voorkeuren — onthouden uw instellingen (optioneel)',
  'legalCookie3Heading': 'Cookies beheren',
  'legalCookie3Body': 'U kunt cookies beheren in uw browserinstellingen. Het uitschakelen van essentiële cookies kan de werking van de site beïnvloeden.',
