  'feeFullyCoveredBySender': 'De afzender koos om 100% van de platformkosten te betalen. Geen kosten wanneer je accepteert.',
  'requestAcceptedBody': 'Je pakketverzoek is geaccepteerd. We koppelen een reiziger en laten het je weten zodra de afzender betaalt.',
