  'legalLastUpdatedDate': '4. September 2026',
  'legalTerms1Heading': '1. Zustimmung zu diesen Bedingungen',
  'legalTerms1Body': 'Diese Allgemeinen Geschäftsbedingungen („Bedingungen“) regeln Ihre Nutzung der mobilen WWNGO-App und der zugehörigen Dienste (die „Plattform“). WWNGO ist ein Peer-to-Peer-Marktplatz, der Absender, die ein Paket transportieren lassen möchten, Reisende, die ohnehin in diese Richtung unterwegs sind, und Empfänger, die das Paket am Zielort entgegennehmen, miteinander verbindet. Durch das Erstellen eines Kontos und das Ankreuzen von „Ich stimme den Bedingungen und der Datenschutzerklärung zu“ schließen Sie eine verbindliche Vereinbarung mit WWNGO ab. Wenn Sie nicht zustimmen, registrieren Sie sich nicht und nutzen Sie die Plattform nicht.',
  'legalTerms2Heading': '2. Was WWNGO ist — und was nicht',
  'legalTerms2Body': 'WWNGO ermöglicht das Matching, In-App-Chat, die Koordination von Treffen, Identitätsprüfungen, Wallet-Zahlungen, Treuhand, die NFC-Bestätigung der Übergabe, Tracking, Bewertungen und die Prüfung von Streitfällen. WWNGO ist kein Kurierdienst, Postbetreiber, Frachtspediteur, Zollmakler, Versicherer oder Arbeitgeber von Reisenden. Die Zustellung wird von unabhängigen Nutzern durchgeführt. WWNGO übernimmt keinen Besitz an Paketen, außer wenn dies für den Betrieb der Plattform erforderlich ist (zum Beispiel das Speichern von hochgeladenen Fotos).',
  'legalTerms3Heading': '3. Berechtigung und Konten',
  'legalTerms3Bullet1': 'Sie müssen mindestens 18 Jahre alt sein und in der Lage sein, einen verbindlichen Vertrag abzuschließen.',
  'legalTerms3Bullet2': 'Sie müssen einen korrekten Namen, eine korrekte E-Mail-Adresse, Telefonnummer, Land und Passwort angeben und diese aktuell halten.',
  'legalTerms3Bullet3': 'Eine Person darf ein einziges WWNGO-Konto als Absender, Reisender und/oder Empfänger nutzen. Diese Bedingungen gelten für jede von Ihnen genutzte Rolle.',
  'legalTerms3Bullet4': 'E-Mail- und Telefonverifizierung sowie die Identitätsprüfung (KYC) über unseren Partner Sumsub sind erforderlich, bevor Sie Lieferungen veröffentlichen, Reisen einstellen, Gebote abgeben, Pakete annehmen oder Geld bewegen.',
  'legalTerms3Bullet5': 'Sie sind für Aktivitäten auf Ihrem Konto verantwortlich. Geben Sie Ihre Anmeldedaten nicht weiter. Benachrichtigen Sie support@wwngo.com, wenn Sie einen unbefugten Zugriff vermuten.',
  'legalTerms4Heading': '4. Pflichten des Absenders',
  'legalTerms4Body': 'Wenn Sie als Absender handeln, veröffentlichen Sie eine Lieferanfrage (Stadt-zu-Stadt oder Land-zu-Land), beschreiben das Paket, legen ein Budget fest, fügen Fotos hinzu und benennen einen Empfänger. Sie verpflichten sich:',
  'legalTerms4Bullet1': 'Eine wahrheitsgemäße Paketkategorie, Größe, Gewicht, Inhaltsbeschreibung, Route, Reisedatum und Treffpunktpräferenzen anzugeben.',
  'legalTerms4Bullet2': 'Nur Gegenstände zu versenden, deren Besitz und Transport auf der gewählten Route legal ist, einschließlich Zoll- und Fluggesellschaftsregeln für internationale Reisen.',
  'legalTerms4Bullet3': 'Niemals verbotene, gefährliche oder illegale Waren anzubieten (siehe Abschnitt 10).',
  'legalTerms4Bullet4': 'Treuhand für die vereinbarte Auszahlung an den Reisenden zu finanzieren, wenn Sie ein Gebot oder Gegenangebot annehmen, und Ihre Absender-Plattformgebühr bei Jetzt zahlen zu entrichten (2 \$ für Dokument und Objekt, oder 3 \$, wenn Sie die Gebühr des Empfängers übernehmen). Die Plattformgebühren für Reisende und Empfänger werden ebenfalls bei Jetzt zahlen erhoben (zunächst aus dem Wallet, dann per Karte).',
  'legalTerms4Bullet5': 'Sich mit dem Reisenden am vereinbarten Ausgangstreffpunkt zu treffen und NFC-Kontrollpunkt 1 (Absender ↔ Reisender) abzuschließen, um die Übergabe zu bestätigen.',
  'legalTerms4Bullet6': 'Für diese Lieferung nur über den WWNGO-Chat zu kommunizieren und die in der App beschriebenen Stornierungen und Fristen einzuhalten.',
  'legalTerms5Heading': '5. Pflichten des Reisenden',
  'legalTerms5Body': 'Wenn Sie als Reisender handeln, veröffentlichen Sie eine Reise, prüfen passende Paketanfragen, nehmen Angebote an oder machen Gegenangebote und transportieren das Paket während Ihrer Reise. Sie verpflichten sich:',
  'legalTerms5Bullet1': 'Einen korrekten Ausgangsort, Zielort, Reisedatum und Kapazität anzugeben und nur Pakete anzunehmen, die Sie legal und sicher transportieren können.',
  'legalTerms5Bullet2': 'Die geltenden Reisenden-Plattformgebühren (3 \$ für Dokument und Objekt) aus Ihrem Wallet (oder per Karte, falls erforderlich) zu zahlen, wenn der Absender Jetzt zahlen abschließt.',
  'legalTerms5Bullet3': 'Treffpunkte zu bestätigen oder vorzuschlagen, NFC-Kontrollpunkt 1 mit dem Absender abzuschließen, das Paket während des Transports sicher zu halten und NFC-Kontrollpunkt 2 (Reisender ↔ Empfänger) am Zielort abzuschließen.',
  'legalTerms5Bullet4': 'Ein Paket nicht zu öffnen, zu benutzen, auszutauschen oder zurückzulassen und die Lieferung nicht außerhalb von WWNGO an Dritte zu vergeben.',
  'legalTerms5Bullet5': 'Den Sendungsstatus in gutem Glauben zu aktualisieren (zum Beispiel bei Beginn des Transports) und im Chat zeitnah zu antworten.',
  'legalTerms5Bullet6': 'Die Erklärungen von Fluggesellschaft, Grenze und Zoll einzuhalten. Sie sind verantwortlich für das, was Sie physisch bei sich tragen.',
  'legalTerms6Heading': '6. Pflichten des Empfängers',
  'legalTerms6Body': 'Wenn Sie als Empfänger handeln, sind Sie in einer Lieferung benannt, nehmen die eingehende Anfrage an und nehmen das Paket am Zielort entgegen. Sie verpflichten sich:',
  'legalTerms6Bullet1': 'Die Paketdetails vor der Annahme zu prüfen. Die Annahme stellt lediglich eine Zustimmung dar — eine Empfänger-Plattformgebühr (2 \$ für Dokument und Objekt) wird bei Jetzt zahlen des Absenders erhoben, sofern der Absender sie nicht übernimmt.',
  'legalTerms6Bullet2': 'Beim Zieltreffpunkt verfügbar zu sein, das Paket zu prüfen und NFC-Kontrollpunkt 2 (Reisender ↔ Empfänger) abzuschließen, um die Lieferung zu bestätigen.',
  'legalTerms6Bullet3': 'Umgehend einen Streitfall in der App zu eröffnen, wenn das Paket fehlt, beschädigt ist oder nicht der Beschreibung entspricht, anstatt die NFC-Bestätigung abzuschließen, wenn Sie die Waren nicht annehmen.',
  'legalTerms6Bullet4': 'Kontaktdaten korrekt zu halten, damit sich Absender und Reisender abstimmen können.',
  'legalTerms7Heading': '7. Matching, Gebote und Buchung',
  'legalTerms7Body': 'Absender können Reisende entdecken und Anfragen senden. Reisende können passende Anfragen erhalten, annehmen, ablehnen oder ein Gegenangebot senden. Eine Buchung entsteht erst, wenn der Absender einen Preis akzeptiert, die erforderliche KYC- und Verifizierung abgeschlossen ist, die Treuhand erfolgreich finanziert wurde und die Plattformgebühren wie angezeigt erhoben werden. Die Auswahl eines Reisenden sperrt die Buchung. Wenn ein Zahlungsfenster oder ein Annahme-Timer abläuft, kann die Buchung automatisch storniert werden, und der Treuhand-Grundbetrag wird gemäß Abschnitt 12 erstattet.',
  'legalTerms8Heading': '8. Treffpunkte und Chat',
  'legalTerms8Body': 'Die Parteien koordinieren mit den In-App-Standortwerkzeugen ein öffentliches, geeignetes Treffen. Ein Treffen ist bestätigt, wenn die erforderlichen Parteien es in der App akzeptieren. Der Chat zwischen Absender–Reisendem, Absender–Empfänger und Reisendem–Empfänger wird je nach Lieferstatus freigeschaltet. Teilen Sie keine Zahlungsdetails außerhalb der Plattform und verlagern Sie das Geschäft nicht aus WWNGO heraus. Zahlungen außerhalb der Plattform machen den Treuhandschutz ungültig.',
  'legalTerms9Heading': '9. NFC-Kontrollpunkte und Lieferbestätigung',
  'legalTerms9Bullet1': 'NFC-Kontrollpunkt 1 (Absender ↔ Reisender) bestätigt, dass der Absender das Paket an den Reisenden übergeben hat.',
  'legalTerms9Bullet2': 'NFC-Kontrollpunkt 2 (Reisender ↔ Empfänger) bestätigt, dass der Empfänger das Paket erhalten hat. Beide Parteien müssen ihr Tippen abschließen. Ein erfolgreicher Kontrollpunkt 2 markiert die Sendung als Zugestellt und gibt die Treuhand an den Reisenden frei (sofern nicht durch einen Streitfall eingefroren).',
  'legalTerms9Bullet3': 'NFC ist ein Bestätigungswerkzeug, keine Garantie für den Zustand des Pakets. Fotos, Chat, Tracking und Streitfallunterlagen können weiterhin in einer Prüfung verwendet werden.',
  'legalTerms9Bullet4': 'Der Missbrauch von NFC (Bestätigung ohne echte Übergabe, Erzwingen eines Tippens oder Manipulation von Geräten) ist ein Grund für Sperrung und Einfrieren der Treuhand.',
  'legalTerms10Heading': '10. Verbotene Gegenstände und Null-Toleranz-Verhalten',
  'legalTerms10Body': 'Sie dürfen Folgendes nicht versenden, transportieren oder anfordern: illegale Drogen, Waffen, Sprengstoffe, Gefahrstoffe, gestohlene Waren, gefälschte Artikel, Bargeld oder Inhaberpapiere über das nach örtlichem Recht Zulässige hinaus, lebende Tiere, menschliche Überreste oder jeden Gegenstand, der vom Beförderer, der Fluggesellschaft oder dem Zielland verboten ist. Betrug, gefälschte Identität, gefälschte Fotos, Belästigung, Manipulation von Bewertungen und Versuche, die Treuhand zu umgehen, sind untersagt. WWNGO kann Konten sperren, die Treuhand einfrieren und illegale Aktivitäten den Behörden melden.',
  'legalTerms11Heading': '11. Zahlungen, Wallets und Treuhand',
  'legalTerms11Bullet1': 'Sie haben eine einzige WWNGO-Wallet, die für Ihre Aktivitäten als Absender, Reisender und Empfänger gemeinsam genutzt wird. Laden Sie mit Stripe auf und heben Sie über Stripe Connect ab, sobald ein Auszahlungskonto verknüpft und bereit ist. Der Transaktionsverlauf zeigt, zu welcher Rolle jeder Eintrag gehört.',
  'legalTerms11Bullet2': 'Wenn ein Absender einen Reisenden akzeptiert, wird die vereinbarte Auszahlung vom verfügbaren Guthaben des Absenders in die Treuhand verschoben (eine Kartenzahlung kann einen Fehlbetrag ausgleichen). Die Treuhand kann von keiner Partei abgehoben werden, bis eine Freigabe, Erstattung oder Streitfallentscheidung vorliegt.',
  'legalTerms11Bullet3': 'Plattformgebühren (Absender, Reisender und/oder Empfänger, einschließlich der optionalen Möglichkeit, dass der Absender die Gebühr des Empfängers übernimmt) werden vor Ihrer Bestätigung offengelegt und wie angezeigt erhoben.',
  'legalTerms11Bullet4': 'Die Treuhand wird nach NFC-Kontrollpunkt 2 / Zugestellt an den Reisenden freigegeben, sofern sie nicht eingefroren ist. WWNGO ist keine Bank; Wallet-Guthaben sind Plattformaufzeichnungen, die zur Abwicklung von Marktplatztransaktionen verwendet werden.',
  'legalTerms12Heading': '12. Stornierungen und Erstattungen',
  'legalTerms12Body': 'Gebuchte Lieferungen können storniert werden, bevor die Reise unterwegs ist oder zugestellt wurde, vorbehaltlich der In-App-Regeln. Der Treuhand-Grundbetrag wird dem Absender erstattet. Plattformgebühren werden den zahlenden Parteien erstattet, wenn die Stornierung mehr als 24 Stunden vor der Reise erfolgt; innerhalb von 24 Stunden sind Plattformgebühren im Allgemeinen nicht erstattungsfähig. Veröffentlichte Lieferungen, die noch nicht gebucht sind, können gemäß den Veröffentlichungsregeln der App storniert werden. Eine automatische Stornierung (zum Beispiel unbezahlte Empfänger-Fenster oder abgelaufene Annahme-Timer) erstattet den Treuhand-Grundbetrag wie im Produkt angegeben. Aufladungen und abgeschlossene Auszahlungen werden nicht zurückgebucht, außer wenn dies gesetzlich vorgeschrieben ist oder als Ergebnis einer förmlichen Streitfallentscheidung.',
  'legalTerms13Heading': '13. Tracking, Fotos und Bewertungen',
  'legalTerms13Body': 'Statusaktualisierungen, Paketfotos sowie GPS- oder Treffpunktdaten, die Sie bereitstellen, werden zur Abwicklung der Lieferung verwendet. Nach der Lieferung können die Parteien Bewertungen abgeben. Bewertungen müssen ehrlich sein und sich auf die Transaktion beziehen. WWNGO kann missbräuchliche oder gefälschte Bewertungen ausblenden oder entfernen.',
  'legalTerms14Heading': '14. Streitfälle',
  'legalTerms14Body': 'Wenn etwas schiefgeht (Schaden, Nichtzustellung, falscher Artikel, NFC-Streitfall), reichen Sie einen Streitfall in der App ein. Das Einreichen eines Streitfalls friert die Treuhand ein, während WWNGO Lieferaufzeichnungen, Fotos, Chat, NFC-Kontrollpunkte und Identitätsdaten prüft. Schließen Sie NFC-Kontrollpunkt 2 nicht ab, wenn Sie den Empfang anfechten möchten. Die Entscheidung von WWNGO über die Treuhand (Freigabe, Erstattung oder Aufteilung) ist zwischen den Parteien auf der Plattform endgültig, ohne etwaige Rechte einzuschränken, die Sie gegenüber einem anderen Nutzer vor einem zuständigen Gericht haben könnten. Rückbuchungen oder Ansprüche außerhalb der Plattform können weiterhin zu Kontomaßnahmen führen.',
  'legalTerms15Heading': '15. Haftungsbeschränkung',
  'legalTerms15Body': 'Im gesetzlich maximal zulässigen Umfang haftet WWNGO nicht für Verlust, Verzögerung, Schäden, Beschlagnahmung oder Zollprobleme, die durch Nutzer, Beförderer oder Regierungen verursacht werden; für Handlungen von Absendern, Reisenden oder Empfängern; oder für indirekte, beiläufige oder Folgeschäden. Unsere Gesamthaftung Ihnen gegenüber für einen Anspruch im Zusammenhang mit der Plattform ist auf den höheren der folgenden Beträge begrenzt: (a) die Plattformgebühren, die Sie WWNGO für die strittige Lieferung in den 12 Monaten vor dem Anspruch gezahlt haben, oder (b) 50 USD. Nichts in diesen Bedingungen schließt eine Haftung aus, die gesetzlich nicht ausgeschlossen werden kann (einschließlich bei Betrug oder durch Fahrlässigkeit verursachtem Tod/Personenschaden, sofern ein solcher Ausschluss verboten ist).',
  'legalTerms16Heading': '16. Änderungen, Sperrung und Kontakt',
  'legalTerms16Body': 'Wir können diese Bedingungen aktualisieren. Die fortgesetzte Nutzung nach einem In-App-Hinweis stellt die Annahme der überarbeiteten Bedingungen dar. Wir können Konten sperren oder kündigen, die gegen diese Bedingungen verstoßen. Fragen: support@wwngo.com. Diese Bedingungen stellen die vollständige Vereinbarung für Ihre Nutzung der Plattform dar und unterliegen den am Sitz von WWNGO geltenden Gesetzen, unbeschadet zwingender Verbraucherschutzbestimmungen in Ihrem Wohnsitzland.',
  'legalPrivacy1Heading': '1. Einleitung',
  'legalPrivacy1Body': 'Diese Datenschutzerklärung erläutert, wie WWNGO personenbezogene Daten erhebt, verwendet, weitergibt und schützt, wenn Sie unseren Peer-to-Peer-Paketmarktplatz als Absender, Reisender und/oder Empfänger nutzen. Sie gilt für die Erstregistrierung und jede spätere Nutzung desselben Kontos. Durch das Erstellen eines Kontos erkennen Sie diese Richtlinie an. Für Fragen wenden Sie sich an privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. Daten, die wir erheben',
  'legalPrivacy2Bullet1': 'Kontodaten: vollständiger Name, E-Mail, Telefon (mit Land/Vorwahl), Passwort (gehasht gespeichert), Land, ausgewählte Rolle und von Ihnen hinzugefügte Profildetails.',
  'legalPrivacy2Bullet2': 'Verifizierungsdaten: OTP-Status von E-Mail und Telefon; von Sumsub verarbeitete KYC-Informationen (Identitätsdokument, Selfie, Liveness und Verifizierungsergebnis). WWNGO speichert den Verifizierungsstatus und Referenzen, nicht Ihre Rohbilder des Ausweises, außer wenn der Prozess unseres KYC-Partners dies erfordert.',
  'legalPrivacy2Bullet3': 'Lieferdaten: Routen, Termine, Paketkategorie/-größe/-gewicht/-beschreibung, Fotos, Kontaktdaten des Empfängers, Treffpunktadressen, Gebote und Gegenangebote, Sendungsstatus, NFC-Kontrollpunktaufzeichnungen, Stornierungs- und Streitfallaufzeichnungen.',
  'legalPrivacy2Bullet4': 'Kommunikation: In-App-Chatnachrichten, Anhänge und Support-E-Mails.',
  'legalPrivacy2Bullet5': 'Zahlungen: einheitliches Wallet-Guthaben und Kontobuch (verfügbar und Treuhand), Transaktionsbeschreibungen mit Aktivitätsrollen-Tags, Stripe-Zahlungs- und Connect-Kennungen. Kartennummern werden von Stripe verarbeitet und nicht auf WWNGO-Servern gespeichert.',
  'legalPrivacy2Bullet6': 'Gerät und Nutzung: App-Version, Gerätetyp, IP-Adresse, Absturzprotokolle und Push-Benachrichtigungstoken (FCM) zur Zustellung von Benachrichtigungen.',
  'legalPrivacy3Heading': '3. Wie wir Ihre Daten verwenden',
  'legalPrivacy3Bullet1': 'Ihr Konto erstellen und sichern und Ihnen den Wechsel zwischen Absender, Reisendem und Empfänger ermöglichen.',
  'legalPrivacy3Bullet2': 'Pakete mit Reisen abgleichen, Angebote anzeigen und Gebote, Timer und Buchungssperren durchführen.',
  'legalPrivacy3Bullet3': 'Plattformgebühren erheben, Absender-Gelder treuhänderisch verwalten, Auszahlungen an Reisende nach NFC-Kontrollpunkt 2 freigeben und Erstattungen bei Stornierung oder Streitfall bearbeiten.',
  'legalPrivacy3Bullet4': 'Treffpunkt-Koordination, Chat, Tracking, NFC-Bestätigung, Bewertungen und Benachrichtigungen ermöglichen.',
  'legalPrivacy3Bullet5': 'Betrug verhindern, diese Bedingungen durchsetzen, Streitfälle prüfen und rechtliche Verpflichtungen erfüllen.',
  'legalPrivacy3Bullet6': 'Zuverlässigkeit und Kundensupport verbessern. Wir verkaufen Ihre personenbezogenen Daten nicht.',
  'legalPrivacy4Heading': '4. Rollenspezifische Weitergabe bei einer Lieferung',
  'legalPrivacy4Body': 'Zum Abschluss einer Buchung werden begrenzte Profil- und Lieferinformationen nur den anderen Parteien dieser Sendung angezeigt — zum Beispiel Namen, Bewertungen, Route, Paketübersicht, Treffpunktstatus und Chat. Ein Reisender erhält nicht Ihre vollständigen Zahlungskartendaten. Ein Empfänger sieht, was er benötigt, um das Paket anzunehmen und abzuholen. Nach Lieferung oder Stornierung folgt der Zugriff den Produktregeln (Verlauf, Bewertungen, Streitfallakten).',
  'legalPrivacy5Heading': '5. Auftragsverarbeiter und Dritte',
  'legalPrivacy5Bullet1': 'Sumsub — Identitätsverifizierung (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — Wallet-Aufladung, Zahlungsabsichten und Connect-Auszahlungen.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — Push-Benachrichtigungen.',
  'legalPrivacy5Bullet4': 'E-Mail-/SMS-Anbieter — Einmalcodes und Transaktions-E-Mails.',
  'legalPrivacy5Bullet5': 'Hosting- und Datenbankanbieter, die Daten gemäß unseren Anweisungen verarbeiten.',
  'legalPrivacy5Bullet6': 'Behörden, wenn gesetzlich vorgeschrieben oder um Nutzer vor schwerem Schaden zu schützen.',
  'legalPrivacy6Heading': '6. Aufbewahrung, Sicherheit und internationale Übermittlung',
  'legalPrivacy6Body': 'Wir bewahren Konto-, Kontobuch-, Liefer-, NFC- und Streitfallaufzeichnungen so lange auf, wie Sie ein Konto haben, und danach für einen angemessenen Zeitraum, um Auszahlungen abzuschließen, Rückbuchungen zu bearbeiten und buchhalterische und rechtliche Pflichten zu erfüllen. Wir verwenden Verschlüsselung bei der Übertragung, Zugriffskontrollen und eine einheitliche Wallet-Buchhaltung. Daten können in anderen Ländern als Ihrem verarbeitet werden; wir verwenden angemessene Schutzmaßnahmen mit Auftragsverarbeitern. Keine Übertragungsmethode ist zu 100 % sicher.',
  'legalPrivacy7Heading': '7. Ihre Rechte',
  'legalPrivacy7Body': 'Vorbehaltlich geltenden Rechts können Sie Zugang, Berichtigung, Löschung, Einschränkung oder Export Ihrer personenbezogenen Daten verlangen und bestimmten Verarbeitungen widersprechen. Sie können Ihre Einwilligung widerrufen, wenn die Verarbeitung auf einer Einwilligung beruht (dies berührt nicht die Rechtmäßigkeit vorheriger Verarbeitung). Einige Aufzeichnungen (Treuhand, KYC-Status, abgeschlossene Kontobücher) können aufbewahrt werden, wenn wir sie behalten müssen. Kontakt: privacy@wwngo.com. Sie können auch eine Beschwerde bei Ihrer örtlichen Datenschutzbehörde einreichen.',
  'legalPrivacy8Heading': '8. Kinder, Änderungen und Kontakt',
  'legalPrivacy8Body': 'WWNGO richtet sich nicht an Kinder unter 18 Jahren. Wir erheben deren Daten nicht wissentlich. Wir können diese Richtlinie aktualisieren und werden das neue Datum in der App veröffentlichen. Wesentliche Änderungen können in der App oder per E-Mail mitgeteilt werden. Kontakt: privacy@wwngo.com (Datenschutz) oder support@wwngo.com (allgemein).',
  'legalCookie1Heading': 'Was sind Cookies?',
  'legalCookie1Body': 'Cookies sind kleine Textdateien, die auf Ihrem Gerät gespeichert werden. Sie helfen, Präferenzen zu speichern und zu verstehen, wie Sie unsere Website nutzen.',
  'legalCookie2Heading': 'Cookies, die wir verwenden',
  'legalCookie2Bullet1': 'Essenziell — erforderlich für Sicherheit und Sitzungen',
  'legalCookie2Bullet2': 'Analyse — helfen uns, die Leistung zu verbessern (freiwillig)',
  'legalCookie2Bullet3': 'Präferenzen — speichern Ihre Einstellungen (freiwillig)',
  'legalCookie3Heading': 'Verwalten von Cookies',
  'legalCookie3Body': 'Sie können Cookies in Ihren Browsereinstellungen steuern. Das Deaktivieren essenzieller Cookies kann die Funktionalität der Website beeinträchtigen.',
