  'startNfcWithTraveler': 'NFC mit Reisendem starten',
  'nfcMeetTravelerHint': 'Triff den Reisenden und tippt die Telefone an (oder nutze Tippen simulieren), um den Empfang zu bestätigen. Beide müssen den NFC-Kontrollpunkt Reisender & Empfänger abschließen.',
  'acceptUnlockTracking': 'Nimm die Paketanfrage an, um Tracking, NFC und Chat freizuschalten.',
