  'legalTermsTitle': 'الشروط والأحكام',
  'legalPrivacyTitle': 'سياسة الخصوصية',
  'legalLastUpdatedDate': '4 سبتمبر 2026',
  'legalTerms1Heading': '1. الموافقة على هذه الشروط',
  'legalTerms1Body': 'تحكم هذه الشروط والأحكام ("الشروط") استخدامك لتطبيق WWNGO للهاتف المحمول والخدمات المرتبطة به ("المنصة"). WWNGO هو سوق مباشر بين الأفراد يربط بين المرسلين الذين يحتاجون إلى نقل طرد، والمسافرين المتوجهين أصلاً إلى تلك الوجهة، والمستلمين الذين يستقبلون الطرد في الوجهة النهائية. بإنشائك حسابًا وتحديدك خيار "أوافق على الشروط وسياسة الخصوصية"، فإنك تدخل في اتفاق ملزم مع WWNGO. إذا لم توافق، فلا تسجّل ولا تستخدم المنصة.',
  'legalTerms2Heading': '2. ما هو WWNGO — وما لا يكون',
  'legalTerms2Body': 'يسهّل WWNGO المطابقة، والمحادثة داخل التطبيق، وتنسيق الاجتماعات، وفحوصات الهوية، والدفع عبر المحفظة، وحجز الضمان، وتأكيد التسليم عبر NFC، والتتبع، والتقييمات، ومراجعة النزاعات. WWNGO ليس شركة شحن أو مشغل بريد أو وكيل شحن أو سمسار جمارك أو شركة تأمين أو صاحب عمل للمسافرين. يتم التسليم من قبل مستخدمين مستقلين. لا يستحوذ WWNGO على الطرود إلا بالقدر اللازم لتشغيل المنصة (مثل تخزين الصور التي تقوم بتحميلها).',
  'legalTerms3Heading': '3. الأهلية والحسابات',
  'legalTerms3Bullet1': 'يجب أن يكون عمرك 18 عامًا على الأقل وأن تكون قادرًا على إبرام عقد ملزم.',
  'legalTerms3Bullet2': 'يجب عليك تقديم اسم وبريد إلكتروني وهاتف وبلد وكلمة مرور دقيقة، وإبقائها محدثة.',
  'legalTerms3Bullet3': 'يجوز لشخص واحد استخدام حساب WWNGO واحد كمرسل و/أو مسافر و/أو مستلم. تنطبق هذه الشروط على كل دور تستخدمه.',
  'legalTerms3Bullet4': 'يُطلب التحقق من البريد الإلكتروني والهاتف، والتحقق من الهوية (KYC) عبر شريكنا Sumsub، قبل نشر التوصيلات أو إدراج الرحلات أو تقديم العروض أو قبول الطرود أو تحويل الأموال.',
  'legalTerms3Bullet5': 'أنت مسؤول عن النشاط في حسابك. لا تشارك بيانات تسجيل الدخول. أبلغ support@wwngo.com إذا اشتبهت بوصول غير مصرح به.',
  'legalTerms4Heading': '4. مسؤوليات المرسل',
  'legalTerms4Body': 'عندما تتصرف كمرسل، فإنك تنشر طلب توصيل (من مدينة إلى مدينة أو من دولة إلى دولة)، وتصف الطرد، وتحدد ميزانية، وتضيف صورًا، وتحدد مستلمًا. أنت توافق على:',
  'legalTerms4Bullet1': 'تقديم فئة الطرد وحجمه ووزنه ووصف محتواه ومساره وتاريخ السفر وتفضيلات الاجتماع بشكل صادق.',
  'legalTerms4Bullet2': 'إرسال العناصر المسموح قانونًا بحملها ونقلها على المسار المختار فقط، بما يشمل قواعد الجمارك وشركات الطيران للرحلات الدولية.',
  'legalTerms4Bullet3': 'عدم إدراج أي سلع محظورة أو خطيرة أو غير قانونية أبدًا (انظر البند 10).',
  'legalTerms4Bullet4': 'تمويل حجز الضمان للمبلغ المتفق عليه لدفعه للمسافر عند قبول عرض أو عرض مقابل، ودفع رسوم منصة المرسل عند الدفع الآن (2 دولار للوثائق والأشياء، أو 3 دولارات إذا غطيت رسوم المستلم). تُجمع أيضًا رسوم منصة المسافر والمستلم عند الدفع الآن (من المحفظة أولًا، ثم من البطاقة).',
  'legalTerms4Bullet5': 'مقابلة المسافر في مكان الاجتماع المتفق عليه في نقطة الانطلاق وإتمام نقطة تفتيش NFC 1 (المرسل ↔ المسافر) لتأكيد التسليم.',
  'legalTerms4Bullet6': 'التواصل فقط عبر محادثة WWNGO بشأن هذا التوصيل، والالتزام بعمليات الإلغاء والمؤقتات الموضحة في التطبيق.',
  'legalTerms5Heading': '5. مسؤوليات المسافر',
  'legalTerms5Body': 'عندما تتصرف كمسافر، فإنك تنشر رحلة، وتراجع طلبات الطرود المطابقة، وتقبل العروض أو تقدم عروضًا مقابلة، وتحمل الطرد خلال رحلتك. أنت توافق على:',
  'legalTerms5Bullet1': 'نشر نقطة الانطلاق والوجهة وتاريخ السفر والسعة بشكل دقيق، وقبول الطرود التي يمكنك حملها بشكل قانوني وآمن فقط.',
  'legalTerms5Bullet2': 'دفع رسوم منصة المسافر المطبقة (3 دولارات للوثائق والأشياء) من محفظتك (أو بطاقتك إذا لزم الأمر) عندما يكمل المرسل الدفع الآن.',
  'legalTerms5Bullet3': 'تأكيد أو اقتراح أماكن الاجتماع، وإتمام نقطة تفتيش NFC 1 مع المرسل، والحفاظ على أمان الطرد أثناء النقل، وإتمام نقطة تفتيش NFC 2 (المسافر ↔ المستلم) في الوجهة.',
  'legalTerms5Bullet4': 'عدم فتح الطرد أو استخدامه أو استبداله أو التخلي عنه، وعدم التعاقد من الباطن للتوصيل خارج WWNGO.',
  'legalTerms5Bullet5': 'تحديث حالة الشحنة بحسن نية (مثل بدء النقل) والرد بسرعة في المحادثة.',
  'legalTerms5Bullet6': 'الالتزام بتصريحات شركات الطيران والحدود والجمارك. أنت مسؤول عما تحمله فعليًا.',
  'legalTerms6Heading': '6. مسؤوليات المستلم',
  'legalTerms6Body': 'عندما تتصرف كمستلم، يتم تسميتك في عملية توصيل، وتقبل الطلب الوارد، وتستلم الطرد في الوجهة. أنت توافق على:',
  'legalTerms6Bullet1': 'مراجعة تفاصيل الطرد قبل القبول. القبول هو موافقة فقط — يتم تحصيل رسوم منصة المستلم (2 دولار للوثائق والأشياء) عند الدفع الآن للمرسل، إلا إذا غطاها المرسل.',
  'legalTerms6Bullet2': 'التوفر في اجتماع الوجهة، والتحقق من الطرد، وإتمام نقطة تفتيش NFC 2 (المسافر ↔ المستلم) لتأكيد التسليم.',
  'legalTerms6Bullet3': 'رفع نزاع في التطبيق فورًا إذا كان الطرد مفقودًا أو تالفًا أو غير مطابق للوصف، بدلاً من إتمام تأكيد NFC إذا لم تقبل البضائع.',
  'legalTerms6Bullet4': 'الحفاظ على بيانات الاتصال دقيقة حتى يتمكن المرسل والمسافر من التنسيق.',
  'legalTerms7Heading': '7. المطابقة والعروض والحجز',
  'legalTerms7Body': 'يمكن للمرسلين اكتشاف المسافرين وإرسال الطلبات. يمكن للمسافرين استلام طلبات مطابقة وقبولها أو رفضها أو إرسال عرض مقابل. لا يُنشأ الحجز إلا عند قبول المرسل للسعر، واكتمال التحقق من الهوية (KYC) المطلوب، وتمويل حجز الضمان بنجاح، وتحصيل رسوم المنصة كما هو معروض. يؤدي اختيار مسافر إلى قفل الحجز. إذا انتهت نافذة الدفع أو مؤقت القبول، يجوز إلغاء الحجز تلقائيًا ويُعاد رأس مال حجز الضمان وفقًا للبند 12.',
  'legalTerms8Heading': '8. أماكن الاجتماع والمحادثة',
  'legalTerms8Body': 'تنسّق الأطراف اجتماعًا عامًا ومناسبًا باستخدام أدوات الموقع داخل التطبيق. يتم تأكيد الاجتماع عندما تقبله الأطراف المطلوبة في التطبيق. يتم فتح المحادثة بين المرسل والمسافر، والمرسل والمستلم، والمسافر والمستلم وفقًا لحالة التوصيل. لا تشارك تفاصيل الدفع خارج المنصة ولا تنقل الصفقة خارج WWNGO. تُلغي المدفوعات خارج المنصة حماية حجز الضمان.',
  'legalTerms9Heading': '9. نقاط تفتيش NFC وتأكيد التسليم',
  'legalTerms9Bullet1': 'تؤكد نقطة تفتيش NFC 1 (المرسل ↔ المسافر) أن المرسل قد سلّم الطرد للمسافر.',
  'legalTerms9Bullet2': 'تؤكد نقطة تفتيش NFC 2 (المسافر ↔ المستلم) أن المستلم قد استلم الطرد. يجب على الطرفين إتمام لمستهما. يُميّز اكتمال نقطة التفتيش 2 بنجاح الشحنة بأنها تم تسليمها ويُطلق حجز الضمان للمسافر (ما لم يكن مجمّدًا بسبب نزاع).',
  'legalTerms9Bullet3': 'تقنية NFC هي أداة تأكيد، لا ضمانة لحالة الطرد. لا تزال الصور والمحادثة والتتبع وسجلات النزاعات قابلة للاستخدام في المراجعة.',
  'legalTerms9Bullet4': 'يعد سوء استخدام NFC (التأكيد دون تسليم فعلي، أو إجبار شخص على اللمس، أو تزييف الأجهزة) سببًا للتعليق وتجميد حجز الضمان.',
  'legalTerms10Heading': '10. العناصر المحظورة والسلوك بدون تسامح',
  'legalTerms10Body': 'يجب عليك عدم إرسال أو حمل أو طلب: المخدرات غير القانونية، والأسلحة، والمتفجرات، والمواد الخطرة، والبضائع المسروقة، والسلع المقلدة، والنقد أو الأدوات لحاملها بما يتجاوز ما يسمح به القانون المحلي، والحيوانات الحية، والرفات البشرية، أو أي عنصر تحظره شركة الشحن أو الطيران أو دولة الوجهة. يُمنع الاحتيال، والهوية المزيفة، والصور المزيفة، والمضايقة، والتلاعب بالتقييمات، ومحاولات تجاوز حجز الضمان. يجوز لـ WWNGO تعليق الحسابات، وتجميد حجز الضمان، وإبلاغ السلطات عن الأنشطة غير القانونية.',
  'legalTerms11Heading': '11. المدفوعات والمحافظ وحجز الضمان',
  'legalTerms11Bullet1': 'لديك محفظة WWNGO واحدة مشتركة بين أنشطتك كمرسل ومسافر ومستلم. اشحن عبر Stripe واسحب عبر Stripe Connect بعد ربط حساب استلام الدفعات وجهوزيته. يسجّل سجل المعاملات الدور الذي يتعلق به كل قيد.',
  'legalTerms11Bullet2': 'عندما يقبل المرسل مسافرًا، يُنقل المبلغ المتفق عليه من الرصيد المتاح للمرسل إلى حجز الضمان (قد يغطي الدفع بالبطاقة أي عجز). لا يمكن لأي طرف سحب حجز الضمان حتى يتم الإطلاق أو الاسترداد أو صدور قرار بشأن نزاع.',
  'legalTerms11Bullet3': 'يتم الكشف عن رسوم المنصة (المرسل و/أو المسافر و/أو المستلم، بما في ذلك خيار تغطية المرسل لرسوم المستلم) قبل تأكيدك، وتُحصَّل كما هو معروض.',
  'legalTerms11Bullet4': 'يُطلق حجز الضمان للمسافر بعد نقطة تفتيش NFC 2 / التسليم، ما لم يكن مجمّدًا. WWNGO ليس بنكًا؛ أرصدة المحفظة هي سجلات للمنصة تُستخدم لتسوية معاملات السوق.',
  'legalTerms12Heading': '12. الإلغاءات والمبالغ المستردة',
  'legalTerms12Body': 'يمكن إلغاء التوصيلات المحجوزة قبل أن تكون الرحلة قيد النقل أو تم تسليمها، وفقًا لقواعد التطبيق. يُعاد رأس مال حجز الضمان إلى المرسل. تُرد رسوم المنصة للأطراف الدافعة إذا كان الإلغاء قبل أكثر من 24 ساعة من السفر؛ وخلال 24 ساعة، تكون رسوم المنصة عادةً غير قابلة للاسترداد. يمكن إلغاء التوصيلات المنشورة غير المحجوزة بعد وفق قواعد النشر في التطبيق. يُعيد الإلغاء التلقائي (مثل نوافذ المستلم غير المدفوعة أو انتهاء مؤقتات القبول) رأس مال حجز الضمان كما هو محدد في المنتج. لا تُعكس عمليات الشحن المكتملة والدفعات المكتملة إلا إذا اقتضى القانون ذلك أو نتيجة قرار نزاع رسمي.',
  'legalTerms13Heading': '13. التتبع والصور والتقييمات',
  'legalTerms13Body': 'تُستخدم تحديثات الحالة وصور الطرد وبيانات GPS أو الاجتماع التي تقدمها لتشغيل عملية التوصيل. بعد التسليم، يمكن للأطراف ترك تقييمات. يجب أن تكون التقييمات صادقة ومتعلقة بالمعاملة. يجوز لـ WWNGO إخفاء أو إزالة التقييمات المسيئة أو المزيفة.',
  'legalTerms14Heading': '14. النزاعات',
  'legalTerms14Body': 'إذا حدث خطأ ما (تلف، عدم تسليم، عنصر خاطئ، نزاع NFC)، فقدّم نزاعًا في التطبيق. يؤدي تقديم النزاع إلى تجميد حجز الضمان بينما يراجع WWNGO سجلات التوصيل والصور والمحادثة ونقاط تفتيش NFC وبيانات الهوية. لا تُكمل نقطة تفتيش NFC 2 إذا كنت تنوي الطعن في الاستلام. يكون قرار WWNGO بشأن حجز الضمان (إطلاق أو استرداد أو تقسيم) نهائيًا بين الأطراف على المنصة، دون أن يحد ذلك من أي حقوق قد تكون لك ضد مستخدم آخر أمام محكمة ذات صلاحية قضائية. قد تؤدي عمليات استرداد المبالغ من البنك أو المطالبات خارج المنصة إلى إجراء بشأن الحساب.',
  'legalTerms15Heading': '15. تحديد المسؤولية',
  'legalTerms15Body': 'إلى أقصى حد يسمح به القانون، لا يكون WWNGO مسؤولاً عن الخسارة أو التأخير أو التلف أو المصادرة أو مشاكل الجمارك الناجمة عن المستخدمين أو شركات الشحن أو الحكومات؛ أو عن تصرفات المرسلين أو المسافرين أو المستلمين؛ أو عن الأضرار غير المباشرة أو العرضية أو التبعية. تقتصر مسؤوليتنا الإجمالية تجاهك عن أي مطالبة متعلقة بالمنصة على الأكبر من: (أ) رسوم المنصة التي دفعتها لـ WWNGO عن التوصيل المتنازع عليه خلال الأشهر الاثني عشر السابقة للمطالبة، أو (ب) 50 دولارًا أمريكيًا. لا يستبعد أي شيء في هذه الشروط المسؤولية التي لا يمكن استبعادها قانونًا (بما في ذلك الاحتيال أو الوفاة/الإصابة الشخصية الناتجة عن الإهمال حيث يكون هذا الاستبعاد محظورًا).',
  'legalTerms16Heading': '16. التغييرات والتعليق والتواصل',
  'legalTerms16Body': 'يجوز لنا تحديث هذه الشروط. يُعد الاستمرار في الاستخدام بعد إشعار داخل التطبيق قبولًا للشروط المعدّلة. يجوز لنا تعليق أو إنهاء الحسابات التي تخالف هذه الشروط. للاستفسارات: support@wwngo.com. تمثل هذه الشروط الاتفاق الكامل بشأن استخدامك للمنصة وتخضع للقوانين المعمول بها في مكان تأسيس WWNGO، دون المساس بحماية المستهلك الإلزامية في بلد إقامتك.',
  'legalPrivacy1Heading': '1. مقدمة',
  'legalPrivacy1Body': 'تشرح سياسة الخصوصية هذه كيف يجمع WWNGO البيانات الشخصية ويستخدمها ويشاركها ويحميها عندما تستخدم سوقنا المباشر للطرود بين الأفراد كمرسل و/أو مسافر و/أو مستلم. وتنطبق على التسجيل لأول مرة وكل استخدام لاحق لنفس الحساب. بإنشائك حسابًا، فإنك تقر بهذه السياسة. للاستفسارات، تواصل مع privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. البيانات التي نجمعها',
  'legalPrivacy2Bullet1': 'بيانات الحساب: الاسم الكامل، والبريد الإلكتروني، والهاتف (مع رمز البلد)، وكلمة المرور (مخزنة بشكل مُجزّأ)، والبلد، والدور المحدد، وتفاصيل الملف الشخصي التي تضيفها.',
  'legalPrivacy2Bullet2': 'بيانات التحقق: حالة رمز التحقق (OTP) للبريد الإلكتروني والهاتف؛ معلومات التحقق من الهوية (KYC) التي تعالجها Sumsub (وثيقة الهوية، والصورة الشخصية، وفحص الحيوية، ونتيجة التحقق). يحتفظ WWNGO بحالة التحقق والمراجع، لا بصور هويتك الخام، إلا إذا تطلب ذلك تدفق عمل شريكنا في التحقق من الهوية.',
  'legalPrivacy2Bullet3': 'بيانات التوصيل: المسارات، والتواريخ، وفئة/حجم/وزن/وصف الطرد، والصور، وبيانات الاتصال بالمستلم، وعناوين الاجتماع، والعروض والعروض المقابلة، وحالة الشحنة، وسجلات نقاط تفتيش NFC، وسجلات الإلغاء والنزاعات.',
  'legalPrivacy2Bullet4': 'الاتصالات: رسائل المحادثة داخل التطبيق، والمرفقات، ورسائل البريد الإلكتروني الخاصة بالدعم.',
  'legalPrivacy2Bullet5': 'المدفوعات: رصيد المحفظة الموحد والسجل (المتاح وحجز الضمان)، وأوصاف المعاملات مع علامات دور النشاط، ومعرّفات الدفع من Stripe و Connect. تُعالج أرقام البطاقات من قبل Stripe ولا تُخزَّن على خوادم WWNGO.',
  'legalPrivacy2Bullet6': 'الجهاز والاستخدام: إصدار التطبيق، ونوع الجهاز، وعنوان IP، وسجلات الأعطال، ورموز إشعارات الدفع (FCM) لتسليم التنبيهات.',
  'legalPrivacy3Heading': '3. كيف نستخدم بياناتك',
  'legalPrivacy3Bullet1': 'إنشاء حسابك وتأمينه، وتمكينك من التبديل بين المرسل والمسافر والمستلم.',
  'legalPrivacy3Bullet2': 'مطابقة الطرود بالرحلات، وعرض القوائم، وتشغيل العروض والمؤقتات وأقفال الحجز.',
  'legalPrivacy3Bullet3': 'تحصيل رسوم المنصة، والاحتفاظ بأموال المرسل في حجز الضمان، وإطلاق الدفعات للمسافرين بعد نقطة تفتيش NFC 2، ومعالجة المبالغ المستردة عند الإلغاء أو النزاع.',
  'legalPrivacy3Bullet4': 'تمكين تنسيق الاجتماعات والمحادثة والتتبع وتأكيد NFC والتقييمات والإشعارات.',
  'legalPrivacy3Bullet5': 'منع الاحتيال، وتطبيق هذه الشروط، ومراجعة النزاعات، والوفاء بالالتزامات القانونية.',
  'legalPrivacy3Bullet6': 'تحسين الموثوقية ودعم العملاء. لا نبيع بياناتك الشخصية.',
  'legalPrivacy4Heading': '4. المشاركة الخاصة بالدور في عملية توصيل',
  'legalPrivacy4Body': 'لإتمام الحجز، تُعرض معلومات محدودة عن الملف الشخصي والتوصيل فقط على الأطراف الأخرى في تلك الشحنة — مثل الأسماء والتقييمات والمسار وملخص الطرد وحالة الاجتماع والمحادثة. لا يستلم المسافر تفاصيل بطاقة الدفع الكاملة الخاصة بك. يرى المستلم ما يحتاجه لقبول الطرد واستلامه. بعد التسليم أو الإلغاء، يتبع الوصول قواعد المنتج (السجل، والتقييمات، وملفات النزاعات).',
  'legalPrivacy5Heading': '5. المعالجون والأطراف الثالثة',
  'legalPrivacy5Bullet1': 'Sumsub — التحقق من الهوية (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — شحن المحفظة، ونيات الدفع، ودفعات Connect.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — إشعارات الدفع.',
  'legalPrivacy5Bullet4': 'مزودو البريد الإلكتروني/الرسائل النصية — الرموز أحادية الاستخدام والرسائل التعاملية.',
  'legalPrivacy5Bullet5': 'مزودو الاستضافة وقواعد البيانات الذين يعالجون البيانات بناءً على تعليماتنا.',
  'legalPrivacy5Bullet6': 'السلطات عند الحاجة القانونية أو لحماية المستخدمين من ضرر جسيم.',
  'legalPrivacy6Heading': '6. الاحتفاظ بالبيانات والأمان والنقل الدولي',
  'legalPrivacy6Body': 'نحتفظ بسجلات الحساب والسجل والتوصيل و NFC والنزاعات طالما لديك حساب، وطالما لفترة معقولة بعد ذلك لإتمام الدفعات ومعالجة عمليات استرداد المبالغ من البنك والوفاء بالالتزامات المحاسبية والقانونية. نستخدم التشفير أثناء النقل، وضوابط الوصول، ومحاسبة محفظة موحدة. قد تُعالج البيانات في بلدان غير بلدك؛ ونستخدم ضمانات مناسبة مع المعالجين. لا توجد طريقة نقل آمنة بنسبة 100%.',
  'legalPrivacy7Heading': '7. حقوقك',
  'legalPrivacy7Body': 'وفقًا للقانون المعمول به، يجوز لك طلب الوصول إلى بياناتك الشخصية أو تصحيحها أو حذفها أو تقييدها أو تصديرها، والاعتراض على بعض المعالجات. يمكنك سحب موافقتك عندما تكون المعالجة قائمة على الموافقة (لا يؤثر ذلك على شرعية المعالجة السابقة). قد يتم الاحتفاظ ببعض السجلات (حجز الضمان، وحالة التحقق من الهوية، والسجلات المكتملة) عندما يتوجب علينا الاحتفاظ بها. تواصل مع privacy@wwngo.com. يمكنك أيضًا تقديم شكوى إلى سلطة حماية البيانات المحلية الخاصة بك.',
  'legalPrivacy8Heading': '8. الأطفال والتغييرات والتواصل',
  'legalPrivacy8Body': 'لا يستهدف WWNGO الأطفال دون 18 عامًا. لا نجمع بياناتهم عن علم. يجوز لنا تحديث هذه السياسة وسننشر التاريخ الجديد في التطبيق. قد يتم الإبلاغ عن التغييرات الجوهرية داخل التطبيق أو عبر البريد الإلكتروني. التواصل: privacy@wwngo.com (الخصوصية) أو support@wwngo.com (عام).',
  'legalCookie1Heading': 'ما هي ملفات تعريف الارتباط (الكوكيز)؟',
  'legalCookie1Body': 'ملفات تعريف الارتباط هي ملفات نصية صغيرة تُخزَّن على جهازك. تساعد على تذكر التفضيلات وفهم كيفية استخدامك لموقعنا.',
  'legalCookie2Heading': 'ملفات تعريف الارتباط التي نستخدمها',
  'legalCookie2Bullet1': 'أساسية — مطلوبة للأمان والجلسات',
  'legalCookie2Bullet2': 'تحليلية — تساعدنا على تحسين الأداء (اختيارية)',
  'legalCookie2Bullet3': 'تفضيلات — تتذكر إعداداتك (اختيارية)',
  'legalCookie3Heading': 'إدارة ملفات تعريف الارتباط',
  'legalCookie3Body': 'يمكنك التحكم في ملفات تعريف الارتباط من إعدادات متصفحك. قد يؤثر تعطيل ملفات تعريف الارتباط الأساسية على وظائف الموقع.',
