  'legalTermsTitle': 'नियम और शर्तें',
  'legalPrivacyTitle': 'प्राइवेसी पॉलिसी',
  'legalLastUpdatedDate': '4 सितंबर, 2026',
  'legalTerms1Heading': '1. इन शर्तों की स्वीकृति',
  'legalTerms1Body': 'यह नियम और शर्तें ("शर्तें") WWNGO मोबाइल ऐप और संबंधित सेवाओं ("प्लेटफ़ॉर्म") के आपके उपयोग को नियंत्रित करती हैं। WWNGO एक पीयर-टू-पीयर मार्केटप्लेस है जो उन प्रेषकों को जोड़ता है जिन्हें पार्सल भिजवाना है, उन यात्रियों को जो वैसे भी उस दिशा में जा रहे हैं, और उन प्राप्तकर्ताओं को जो गंतव्य पर पार्सल स्वीकार करते हैं। खाता बनाकर और "मैं शर्तों और प्राइवेसी पॉलिसी से सहमत हूं" चुनकर, आप WWNGO के साथ एक बाध्यकारी समझौता करते हैं। यदि आप सहमत नहीं हैं, तो पंजीकरण न करें और प्लेटफ़ॉर्म का उपयोग न करें।',
  'legalTerms2Heading': '2. WWNGO क्या है — और क्या नहीं है',
  'legalTerms2Body': 'WWNGO मैचिंग, इन-ऐप चैट, मीटअप समन्वय, पहचान जांच, वॉलेट पेमेंट, एस्क्रो, NFC हैंडऑफ पुष्टि, ट्रैकिंग, रेटिंग और विवाद समीक्षा को सुविधाजनक बनाता है। WWNGO कोई कोरियर, डाक ऑपरेटर, फ्रेट फॉरवर्डर, कस्टम्स ब्रोकर, इंश्योरर या यात्रियों का नियोक्ता नहीं है। डिलीवरी स्वतंत्र उपयोगकर्ताओं द्वारा की जाती है। WWNGO पार्सल पर कब्ज़ा नहीं करता, सिवाय इसके कि प्लेटफ़ॉर्म चलाने के लिए आवश्यक हो (उदाहरण के लिए आपके द्वारा अपलोड की गई फ़ोटो संग्रहीत करना)।',
  'legalTerms3Heading': '3. पात्रता और खाते',
  'legalTerms3Bullet1': 'आपकी आयु कम से कम 18 वर्ष होनी चाहिए और आप बाध्यकारी अनुबंध करने में सक्षम होने चाहिए।',
  'legalTerms3Bullet2': 'आपको सटीक नाम, ईमेल, फ़ोन, देश और पासवर्ड देना होगा, और उन्हें अद्यतन रखना होगा।',
  'legalTerms3Bullet3': 'एक व्यक्ति एक ही WWNGO खाते का उपयोग प्रेषक, यात्री, और/या प्राप्तकर्ता के रूप में कर सकता है। ये शर्तें आपके द्वारा उपयोग की जाने वाली हर भूमिका पर लागू होती हैं।',
  'legalTerms3Bullet4': 'डिलीवरी पोस्ट करने, ट्रिप लिस्ट करने, बिड लगाने, पार्सल स्वीकार करने या पैसा भेजने से पहले ईमेल और फ़ोन सत्यापन, तथा हमारे पार्टनर Sumsub के माध्यम से पहचान सत्यापन (KYC), आवश्यक हैं।',
  'legalTerms3Bullet5': 'आप अपने खाते पर होने वाली गतिविधि के लिए ज़िम्मेदार हैं। लॉगिन क्रेडेंशियल साझा न करें। यदि आपको अनधिकृत एक्सेस का संदेह हो तो support@wwngo.com को सूचित करें।',
  'legalTerms4Heading': '4. प्रेषक की ज़िम्मेदारियां',
  'legalTerms4Body': 'जब आप प्रेषक के रूप में कार्य करते हैं, तो आप एक डिलीवरी रिक्वेस्ट (शहर-से-शहर या देश-से-देश) पोस्ट करते हैं, पार्सल का विवरण देते हैं, बजट तय करते हैं, फ़ोटो जोड़ते हैं, और एक प्राप्तकर्ता का नाम बताते हैं। आप इस बात के लिए सहमत हैं कि:',
  'legalTerms4Bullet1': 'पार्सल की सही श्रेणी, आकार, वज़न, सामग्री का विवरण, मार्ग, यात्रा तिथि और मीटअप वरीयताएं दें।',
  'legalTerms4Bullet2': 'केवल वे वस्तुएं भेजें जिन्हें चुने गए मार्ग पर रखना और ले जाना कानूनी हो, जिसमें अंतरराष्ट्रीय यात्राओं के लिए कस्टम्स और एयरलाइन नियम शामिल हैं।',
  'legalTerms4Bullet3': 'कभी भी प्रतिबंधित, खतरनाक या अवैध सामान सूचीबद्ध न करें (धारा 10 देखें)।',
  'legalTerms4Bullet4': 'जब आप कोई बिड या काउंटर-ऑफ़र स्वीकार करते हैं तो सहमत यात्री पेआउट के लिए एस्क्रो फंड करें, और Pay Now पर अपनी प्रेषक प्लेटफ़ॉर्म फ़ीस चुकाएं (\$2 दस्तावेज़ और ऑब्जेक्ट के लिए, या \$3 जब आप प्राप्तकर्ता की फ़ीस कवर करते हैं)। यात्री और प्राप्तकर्ता की प्लेटफ़ॉर्म फ़ीस भी Pay Now पर एकत्र की जाती है (पहले वॉलेट से, फिर कार्ड से)।',
  'legalTerms4Bullet5': 'सहमत मूल मीटअप स्थान पर यात्री से मिलें और हैंडऑफ की पुष्टि के लिए NFC चेकपॉइंट 1 (प्रेषक ↔ यात्री) पूरा करें।',
  'legalTerms4Bullet6': 'इस डिलीवरी के लिए केवल WWNGO चैट के माध्यम से संवाद करें, और ऐप में बताए गए रद्दीकरण और टाइमर का सम्मान करें।',
  'legalTerms5Heading': '5. यात्री की ज़िम्मेदारियां',
  'legalTerms5Body': 'जब आप यात्री के रूप में कार्य करते हैं, तो आप एक ट्रिप पोस्ट करते हैं, मिलती-जुलती पार्सल रिक्वेस्ट की समीक्षा करते हैं, ऑफ़र स्वीकार करते हैं या काउंटर-ऑफ़र देते हैं, और अपनी यात्रा के दौरान पार्सल ले जाते हैं। आप इस बात के लिए सहमत हैं कि:',
  'legalTerms5Bullet1': 'सही मूल स्थान, गंतव्य, यात्रा तिथि और क्षमता पोस्ट करें, और केवल वे पार्सल स्वीकार करें जिन्हें आप कानूनी और सुरक्षित रूप से ले जा सकते हैं।',
  'legalTerms5Bullet2': 'जब प्रेषक Pay Now पूरा करता है तो अपने वॉलेट से (या ज़रूरत होने पर कार्ड से) लागू यात्री प्लेटफ़ॉर्म फ़ीस (\$3 दस्तावेज़ और ऑब्जेक्ट के लिए) चुकाएं।',
  'legalTerms5Bullet3': 'मीटअप स्थानों की पुष्टि करें या प्रस्तावित करें, प्रेषक के साथ NFC चेकपॉइंट 1 पूरा करें, ट्रांज़िट के दौरान पार्सल को सुरक्षित रखें, और गंतव्य पर NFC चेकपॉइंट 2 (यात्री ↔ प्राप्तकर्ता) पूरा करें।',
  'legalTerms5Bullet4': 'पार्सल को न खोलें, उपयोग न करें, बदलें नहीं, या छोड़ें नहीं, और WWNGO के बाहर डिलीवरी को उप-अनुबंधित न करें।',
  'legalTerms5Bullet5': 'सद्भावना से शिपमेंट की स्थिति अपडेट करें (उदाहरण के लिए ट्रांज़िट शुरू करना) और चैट में तुरंत जवाब दें।',
  'legalTerms5Bullet6': 'एयरलाइन, सीमा और कस्टम्स घोषणाओं का पालन करें। आप जो भौतिक रूप से ले जाते हैं उसके लिए आप ज़िम्मेदार हैं।',
  'legalTerms6Heading': '6. प्राप्तकर्ता की ज़िम्मेदारियां',
  'legalTerms6Body': 'जब आप प्राप्तकर्ता के रूप में कार्य करते हैं, तो आपका नाम किसी डिलीवरी पर दिया जाता है, आप आने वाली रिक्वेस्ट स्वीकार करते हैं, और गंतव्य पर पार्सल लेते हैं। आप इस बात के लिए सहमत हैं कि:',
  'legalTerms6Bullet1': 'स्वीकार करने से पहले पार्सल विवरण की समीक्षा करें। स्वीकार करना केवल सहमति है — प्राप्तकर्ता प्लेटफ़ॉर्म फ़ीस (\$2 दस्तावेज़ और ऑब्जेक्ट के लिए) प्रेषक के Pay Now पर तब तक ली जाती है जब तक प्रेषक इसे कवर न करे।',
  'legalTerms6Bullet2': 'गंतव्य मीटअप पर उपलब्ध रहें, पार्सल सत्यापित करें, और डिलीवरी की पुष्टि के लिए NFC चेकपॉइंट 2 (यात्री ↔ प्राप्तकर्ता) पूरा करें।',
  'legalTerms6Bullet3': 'यदि पार्सल गुम, क्षतिग्रस्त या वर्णन से अलग हो, तो NFC पुष्टि पूरी करने के बजाय, तुरंत ऐप में विवाद उठाएं यदि आप सामान स्वीकार नहीं करते।',
  'legalTerms6Bullet4': 'संपर्क विवरण सटीक रखें ताकि प्रेषक और यात्री समन्वय कर सकें।',
  'legalTerms7Heading': '7. मैचिंग, बिड और बुकिंग',
  'legalTerms7Body': 'प्रेषक यात्रियों को खोज सकते हैं और रिक्वेस्ट भेज सकते हैं। यात्री मिलती-जुलती रिक्वेस्ट प्राप्त कर सकते हैं, स्वीकार कर सकते हैं, अस्वीकार कर सकते हैं, या काउंटर-ऑफ़र भेज सकते हैं। बुकिंग तभी बनती है जब प्रेषक किसी कीमत को स्वीकार करता है, आवश्यक KYC और सत्यापन पूरा हो जाता है, एस्क्रो सफलतापूर्वक फंड हो जाता है, और प्लेटफ़ॉर्म फ़ीस प्रदर्शित रूप में एकत्र की जाती है। किसी यात्री का चयन बुकिंग को लॉक कर देता है। यदि पेमेंट विंडो या एक्सेप्ट टाइमर समाप्त हो जाता है, तो बुकिंग स्वतः रद्द हो सकती है और एस्क्रो की मूल राशि धारा 12 के अनुसार वापस कर दी जाती है।',
  'legalTerms8Heading': '8. मीटअप स्थान और चैट',
  'legalTerms8Body': 'पार्टियां इन-ऐप लोकेशन टूल का उपयोग करके एक सार्वजनिक, उपयुक्त मीटअप का समन्वय करती हैं। मीटअप की पुष्टि तब होती है जब आवश्यक पार्टियां ऐप में इसे स्वीकार करती हैं। प्रेषक–यात्री, प्रेषक–प्राप्तकर्ता, और यात्री–प्राप्तकर्ता के बीच चैट डिलीवरी स्टेटस के अनुसार अनलॉक होती है। पेमेंट विवरण प्लेटफ़ॉर्म से बाहर साझा न करें या डील को WWNGO से बाहर न ले जाएं। ऑफ-प्लेटफ़ॉर्म पेमेंट एस्क्रो सुरक्षा को अमान्य कर देते हैं।',
  'legalTerms9Heading': '9. NFC चेकपॉइंट और डिलीवरी पुष्टि',
  'legalTerms9Bullet1': 'NFC चेकपॉइंट 1 (प्रेषक ↔ यात्री) पुष्टि करता है कि प्रेषक ने पार्सल यात्री को सौंप दिया है।',
  'legalTerms9Bullet2': 'NFC चेकपॉइंट 2 (यात्री ↔ प्राप्तकर्ता) पुष्टि करता है कि प्राप्तकर्ता को पार्सल मिल गया है। दोनों पार्टियों को अपना टैप पूरा करना होगा। सफल चेकपॉइंट 2 शिपमेंट को डिलीवर्ड के रूप में चिह्नित करता है और यात्री को एस्क्रो जारी करता है (जब तक कि किसी विवाद से फ्रीज़ न हो)।',
  'legalTerms9Bullet3': 'NFC एक पुष्टिकरण उपकरण है, पार्सल की स्थिति की गारंटी नहीं। फ़ोटो, चैट, ट्रैकिंग और विवाद रिकॉर्ड को अभी भी समीक्षा में उपयोग किया जा सकता है।',
  'legalTerms9Bullet4': 'NFC का दुरुपयोग (वास्तविक हैंडऑफ के बिना पुष्टि करना, टैप के लिए मजबूर करना, या डिवाइस स्पूफिंग) सस्पेंशन और एस्क्रो फ्रीज़ का आधार है।',
  'legalTerms10Heading': '10. प्रतिबंधित वस्तुएं और शून्य-सहनशीलता व्यवहार',
  'legalTerms10Body': 'आपको नहीं भेजना, ले जाना या मांगना चाहिए: अवैध ड्रग्स, हथियार, विस्फोटक, खतरनाक सामग्री, चोरी का सामान, नकली वस्तुएं, स्थानीय कानून द्वारा अनुमत सीमा से अधिक नकद या वाहक साधन, जीवित पशु, मानव अवशेष, या कोई भी वस्तु जो कैरियर, एयरलाइन, या गंतव्य देश द्वारा प्रतिबंधित हो। धोखाधड़ी, नकली पहचान, नकली फ़ोटो, उत्पीड़न, रेटिंग में हेरफेर, और एस्क्रो को बायपास करने के प्रयास प्रतिबंधित हैं। WWNGO खातों को सस्पेंड कर सकता है, एस्क्रो फ्रीज़ कर सकता है, और अधिकारियों को अवैध गतिविधि की सूचना दे सकता है।',
  'legalTerms11Heading': '11. पेमेंट, वॉलेट और एस्क्रो',
  'legalTerms11Bullet1': 'आपके पास एक ही WWNGO वॉलेट है जो प्रेषक, यात्री और प्राप्तकर्ता की गतिविधि में साझा होता है। Stripe से टॉप अप करें और एक बार पेआउट खाता लिंक और तैयार होने पर Stripe Connect के माध्यम से निकालें। ट्रांज़ैक्शन हिस्ट्री यह रिकॉर्ड करती है कि प्रत्येक एंट्री किस भूमिका से संबंधित है।',
  'legalTerms11Bullet2': 'जब कोई प्रेषक किसी यात्री को स्वीकार करता है, तो सहमत पेआउट प्रेषक की उपलब्ध राशि से एस्क्रो में स्थानांतरित हो जाता है (कार्ड पेमेंट किसी कमी को कवर कर सकता है)। एस्क्रो तब तक किसी भी पार्टी द्वारा निकाला नहीं जा सकता जब तक कि रिलीज़, रिफंड, या विवाद निर्णय न हो।',
  'legalTerms11Bullet3': 'प्लेटफ़ॉर्म फ़ीस (प्रेषक, यात्री, और/या प्राप्तकर्ता, जिसमें वैकल्पिक प्रेषक-प्राप्तकर्ता-फ़ीस-कवर शामिल है) आपकी पुष्टि से पहले प्रकट की जाती है और दिखाए अनुसार ली जाती है।',
  'legalTerms11Bullet4': 'NFC चेकपॉइंट 2 / डिलीवर्ड के बाद एस्क्रो यात्री को जारी किया जाता है, जब तक कि फ्रीज़ न हो। WWNGO कोई बैंक नहीं है; वॉलेट बैलेंस प्लेटफ़ॉर्म के रिकॉर्ड हैं जो मार्केटप्लेस ट्रांज़ैक्शन को सेटल करने के लिए उपयोग किए जाते हैं।',
  'legalTerms12Heading': '12. रद्दीकरण और रिफंड',
  'legalTerms12Body': 'बुक की गई डिलीवरी को ट्रिप ट्रांज़िट में जाने या डिलीवर होने से पहले रद्द किया जा सकता है, ऐप के नियमों के अधीन। एस्क्रो की मूल राशि प्रेषक को वापस कर दी जाती है। यदि रद्दीकरण यात्रा से 24 घंटे से अधिक पहले होता है, तो प्लेटफ़ॉर्म फ़ीस भुगतान करने वाली पार्टियों को वापस कर दी जाती है; 24 घंटे के भीतर, प्लेटफ़ॉर्म फ़ीस आम तौर पर वापस नहीं की जाती। पोस्ट की गई लेकिन अभी बुक न हुई डिलीवरी को ऐप के पोस्टिंग नियमों के तहत रद्द किया जा सकता है। ऑटो-रद्दीकरण (उदाहरण के लिए अवैतनिक प्राप्तकर्ता विंडो या समाप्त एक्सेप्ट टाइमर) उत्पाद में बताए अनुसार एस्क्रो की मूल राशि वापस करता है। टॉप-अप और पूर्ण पेआउट को उलटा नहीं किया जाता सिवाय इसके कि कानून द्वारा आवश्यक हो या किसी औपचारिक विवाद परिणाम के तहत।',
  'legalTerms13Heading': '13. ट्रैकिंग, फ़ोटो और रिव्यू',
  'legalTerms13Body': 'आपके द्वारा दी गई स्टेटस अपडेट, पार्सल फ़ोटो, और GPS या मीटअप डेटा का उपयोग डिलीवरी संचालित करने के लिए किया जाता है। डिलीवरी के बाद, पार्टियां रिव्यू छोड़ सकती हैं। रिव्यू ईमानदार होने चाहिए और ट्रांज़ैक्शन से संबंधित होने चाहिए। WWNGO अपमानजनक या नकली रिव्यू को छिपा सकता है या हटा सकता है।',
  'legalTerms14Heading': '14. विवाद',
  'legalTerms14Body': 'यदि कुछ गलत हो जाता है (क्षति, गैर-डिलीवरी, गलत आइटम, NFC विवाद), तो ऐप में विवाद दर्ज करें। विवाद दर्ज करने से एस्क्रो फ्रीज़ हो जाता है जबकि WWNGO डिलीवरी रिकॉर्ड, फ़ोटो, चैट, NFC चेकपॉइंट, और पहचान डेटा की समीक्षा करता है। यदि आप रसीद पर विवाद करने का इरादा रखते हैं तो NFC चेकपॉइंट 2 पूरा न करें। एस्क्रो पर WWNGO का निर्णय (रिलीज़, रिफंड, या विभाजन) प्लेटफ़ॉर्म पर पार्टियों के बीच अंतिम है, बिना किसी सक्षम न्यायक्षेत्र की अदालत में किसी अन्य उपयोगकर्ता के विरुद्ध आपके किसी अधिकार को सीमित किए। चार्जबैक या ऑफ-प्लेटफ़ॉर्म दावों से अभी भी खाते पर कार्रवाई हो सकती है।',
  'legalTerms15Heading': '15. दायित्व की सीमा',
  'legalTerms15Body': 'कानून द्वारा अनुमत अधिकतम सीमा तक, WWNGO उपयोगकर्ताओं, कैरियर, या सरकारों के कारण होने वाली हानि, देरी, क्षति, ज़ब्ती, या कस्टम्स समस्याओं के लिए; प्रेषकों, यात्रियों, या प्राप्तकर्ताओं के कार्यों के लिए; या अप्रत्यक्ष, प्रासंगिक, या परिणामी नुकसान के लिए उत्तरदायी नहीं है। प्लेटफ़ॉर्म से संबंधित किसी दावे के लिए आपके प्रति हमारी कुल जिम्मेदारी (a) दावे से पहले के 12 महीनों में विवादित डिलीवरी के लिए आपने WWNGO को जो प्लेटफ़ॉर्म फ़ीस चुकाई, या (b) 50 USD, में से जो भी अधिक हो, तक सीमित है। इन शर्तों में कुछ भी उस दायित्व को बाहर नहीं करता जिसे कानूनी रूप से बाहर नहीं किया जा सकता (जिसमें धोखाधड़ी या लापरवाही के कारण होने वाली मृत्यु/शारीरिक चोट शामिल है, जहां ऐसा बहिष्करण प्रतिबंधित हो)।',
  'legalTerms16Heading': '16. परिवर्तन, सस्पेंशन और संपर्क',
  'legalTerms16Body': 'हम इन शर्तों को अपडेट कर सकते हैं। इन-ऐप सूचना के बाद निरंतर उपयोग संशोधित शर्तों की स्वीकृति माना जाएगा। हम उन खातों को सस्पेंड या समाप्त कर सकते हैं जो इन शर्तों का उल्लंघन करते हैं। प्रश्न: support@wwngo.com। ये शर्तें प्लेटफ़ॉर्म के आपके उपयोग के लिए संपूर्ण समझौता हैं और WWNGO की स्थापना के स्थान पर लागू कानूनों द्वारा शासित होती हैं, बिना आपके निवास देश में अनिवार्य उपभोक्ता संरक्षण को प्रभावित किए।',
  'legalPrivacy1Heading': '1. परिचय',
  'legalPrivacy1Body': 'यह प्राइवेसी पॉलिसी बताती है कि जब आप प्रेषक, यात्री, और/या प्राप्तकर्ता के रूप में हमारे पीयर-टू-पीयर पार्सल मार्केटप्लेस का उपयोग करते हैं तो WWNGO व्यक्तिगत डेटा को कैसे एकत्र, उपयोग, साझा और सुरक्षित करता है। यह पहली बार के पंजीकरण और उसी खाते के सभी बाद के उपयोग पर लागू होती है। खाता बनाकर आप इस पॉलिसी को स्वीकार करते हैं। प्रश्नों के लिए, privacy@wwngo.com पर संपर्क करें।',
  'legalPrivacy2Heading': '2. हम जो डेटा एकत्र करते हैं',
  'legalPrivacy2Bullet1': 'खाता डेटा: पूरा नाम, ईमेल, फ़ोन (देश/डायल कोड के साथ), पासवर्ड (हैश करके संग्रहीत), देश, चयनित भूमिका, और आपके द्वारा जोड़े गए प्रोफ़ाइल विवरण।',
  'legalPrivacy2Bullet2': 'सत्यापन डेटा: ईमेल और फ़ोन OTP स्थिति; Sumsub द्वारा प्रोसेस की गई KYC जानकारी (पहचान दस्तावेज़, सेल्फ़ी, लाइवनेस, और सत्यापन परिणाम)। WWNGO सत्यापन स्थिति और संदर्भ संग्रहीत करता है, आपकी कच्ची ID इमेज नहीं, सिवाय इसके कि हमारे KYC पार्टनर की प्रक्रिया के लिए यह आवश्यक हो।',
  'legalPrivacy2Bullet3': 'डिलीवरी डेटा: मार्ग, तिथियां, पार्सल श्रेणी/आकार/वज़न/विवरण, फ़ोटो, प्राप्तकर्ता संपर्क, मीटअप पते, बिड और काउंटर-ऑफ़र, शिपमेंट स्थिति, NFC चेकपॉइंट रिकॉर्ड, रद्दीकरण और विवाद रिकॉर्ड।',
  'legalPrivacy2Bullet4': 'संचार: इन-ऐप चैट मैसेज, अटैचमेंट, और सपोर्ट ईमेल।',
  'legalPrivacy2Bullet5': 'पेमेंट: एकीकृत वॉलेट बैलेंस और लेजर (उपलब्ध और एस्क्रो), एक्टिविटी रोल टैग वाले ट्रांज़ैक्शन विवरण, Stripe पेमेंट और Connect पहचानकर्ता। कार्ड नंबर Stripe द्वारा संभाले जाते हैं, WWNGO सर्वर पर संग्रहीत नहीं।',
  'legalPrivacy2Bullet6': 'डिवाइस और उपयोग: ऐप वर्शन, डिवाइस टाइप, IP एड्रेस, क्रैश लॉग, और अलर्ट पहुंचाने के लिए पुश-नोटिफ़िकेशन टोकन (FCM)।',
  'legalPrivacy3Heading': '3. हम आपके डेटा का उपयोग कैसे करते हैं',
  'legalPrivacy3Bullet1': 'आपका खाता बनाना और सुरक्षित करना, और आपको प्रेषक, यात्री, और प्राप्तकर्ता के बीच स्विच करने देना।',
  'legalPrivacy3Bullet2': 'पार्सल को ट्रिप से मैच करना, लिस्टिंग दिखाना, और बिड, टाइमर, और बुकिंग लॉक चलाना।',
  'legalPrivacy3Bullet3': 'प्लेटफ़ॉर्म फ़ीस एकत्र करना, प्रेषक के फंड को एस्क्रो में रखना, NFC चेकपॉइंट 2 के बाद यात्रियों को पेआउट जारी करना, और रद्दीकरण या विवाद पर रिफंड प्रोसेस करना।',
  'legalPrivacy3Bullet4': 'मीटअप समन्वय, चैट, ट्रैकिंग, NFC पुष्टि, रिव्यू, और नोटिफ़िकेशन को सक्षम करना।',
  'legalPrivacy3Bullet5': 'धोखाधड़ी रोकना, इन शर्तों को लागू करना, विवादों की समीक्षा करना, और कानूनी दायित्वों को पूरा करना।',
  'legalPrivacy3Bullet6': 'विश्वसनीयता और कस्टमर सपोर्ट में सुधार करना। हम आपका व्यक्तिगत डेटा नहीं बेचते।',
  'legalPrivacy4Heading': '4. डिलीवरी पर भूमिका-विशिष्ट साझाकरण',
  'legalPrivacy4Body': 'बुकिंग पूरी करने के लिए, सीमित प्रोफ़ाइल और डिलीवरी जानकारी केवल उस शिपमेंट की अन्य पार्टियों को दिखाई जाती है — उदाहरण के लिए नाम, रेटिंग, मार्ग, पार्सल सारांश, मीटअप स्थिति, और चैट। किसी यात्री को आपके पूरे पेमेंट कार्ड विवरण प्राप्त नहीं होते। एक प्राप्तकर्ता वह देखता है जिसकी उसे पार्सल स्वीकार करने और लेने के लिए आवश्यकता है। डिलीवरी या रद्दीकरण के बाद, एक्सेस प्रोडक्ट नियमों (हिस्ट्री, रिव्यू, विवाद फ़ाइलें) का पालन करता है।',
  'legalPrivacy5Heading': '5. प्रोसेसर और तीसरे पक्ष',
  'legalPrivacy5Bullet1': 'Sumsub — पहचान सत्यापन (KYC)।',
  'legalPrivacy5Bullet2': 'Stripe — वॉलेट टॉप-अप, पेमेंट इंटेंट, और Connect पेआउट।',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — पुश नोटिफ़िकेशन।',
  'legalPrivacy5Bullet4': 'ईमेल/SMS प्रोवाइडर — वन-टाइम कोड और ट्रांज़ैक्शनल मेल।',
  'legalPrivacy5Bullet5': 'होस्टिंग और डेटाबेस प्रोवाइडर जो हमारे निर्देशों पर डेटा प्रोसेस करते हैं।',
  'legalPrivacy5Bullet6': 'जब कानून द्वारा आवश्यक हो या उपयोगकर्ताओं को गंभीर नुकसान से बचाने के लिए अधिकारी।',
  'legalPrivacy6Heading': '6. डेटा संरक्षण, सुरक्षा और अंतरराष्ट्रीय स्थानांतरण',
  'legalPrivacy6Body': 'हम खाता, लेजर, डिलीवरी, NFC, और विवाद रिकॉर्ड जब तक आपका खाता है तब तक रखते हैं, और उसके बाद पेआउट पूरा करने, चार्जबैक संभालने, और बुककीपिंग व कानूनी दायित्वों को पूरा करने के लिए एक उचित अवधि तक रखते हैं। हम ट्रांज़िट में एन्क्रिप्शन, एक्सेस कंट्रोल, और एकीकृत वॉलेट अकाउंटिंग का उपयोग करते हैं। डेटा को आपके अलावा अन्य देशों में प्रोसेस किया जा सकता है; हम प्रोसेसर के साथ उचित सुरक्षा उपायों का उपयोग करते हैं। ट्रांसमिशन का कोई भी तरीका 100% सुरक्षित नहीं है।',
  'legalPrivacy7Heading': '7. आपके अधिकार',
  'legalPrivacy7Body': 'लागू कानून के अधीन, आप अपने व्यक्तिगत डेटा तक एक्सेस, सुधार, हटाना, प्रतिबंध, या एक्सपोर्ट का अनुरोध कर सकते हैं, और कुछ प्रोसेसिंग पर आपत्ति कर सकते हैं। जहां प्रोसेसिंग सहमति पर आधारित है, आप सहमति वापस ले सकते हैं (यह पूर्व वैध प्रोसेसिंग को प्रभावित नहीं करता)। कुछ रिकॉर्ड (एस्क्रो, KYC स्थिति, पूर्ण लेजर) को बरकरार रखा जा सकता है जहां हमें उन्हें रखना आवश्यक हो। privacy@wwngo.com पर संपर्क करें। आप अपने स्थानीय डेटा प्रोटेक्शन प्राधिकरण के पास शिकायत भी दर्ज कर सकते हैं।',
  'legalPrivacy8Heading': '8. बच्चे, परिवर्तन और संपर्क',
  'legalPrivacy8Body': 'WWNGO 18 वर्ष से कम उम्र के बच्चों के लिए निर्देशित नहीं है। हम जानबूझकर उनका डेटा एकत्र नहीं करते। हम इस पॉलिसी को अपडेट कर सकते हैं और ऐप में नई तिथि पोस्ट करेंगे। महत्वपूर्ण परिवर्तनों की सूचना इन-ऐप या ईमेल द्वारा दी जा सकती है। संपर्क: privacy@wwngo.com (प्राइवेसी) या support@wwngo.com (सामान्य)।',
  'legalCookie1Heading': 'कुकीज़ क्या हैं?',
  'legalCookie1Body': 'कुकीज़ आपके डिवाइस पर संग्रहीत छोटी टेक्स्ट फ़ाइलें हैं। वे प्राथमिकताओं को याद रखने और यह समझने में मदद करती हैं कि आप हमारी साइट का उपयोग कैसे करते हैं।',
  'legalCookie2Heading': 'कुकीज़ जो हम उपयोग करते हैं',
  'legalCookie2Bullet1': 'आवश्यक — सुरक्षा और सेशन के लिए ज़रूरी',
  'legalCookie2Bullet2': 'एनालिटिक्स — हमें प्रदर्शन सुधारने में मदद करते हैं (वैकल्पिक)',
  'legalCookie2Bullet3': 'प्राथमिकताएं — आपकी सेटिंग्स को याद रखते हैं (वैकल्पिक)',
  'legalCookie3Heading': 'कुकीज़ प्रबंधित करना',
  'legalCookie3Body': 'आप अपनी ब्राउज़र सेटिंग्स में कुकीज़ को नियंत्रित कर सकते हैं। आवश्यक कुकीज़ को अक्षम करने से साइट की कार्यक्षमता प्रभावित हो सकती है।',
  'newRequest': 'नया अनुरोध',
  'parcelRequest': 'पार्सल अनुरोध',
