  'feeFullyCoveredBySender': 'सेंडर ने प्लेटफ़ॉर्म शुल्क का 100% भुगतान चुना। स्वीकार करने पर कोई शुल्क नहीं।',
  'requestAcceptedBody': 'आपका पार्सल अनुरोध स्वीकार हो गया। हम एक यात्री मिलाएँगे और सेंडर भुगतान पूरा करने पर सूचित करेंगे।',
  'youAcceptedParcelRequest': 'आपने यह पार्सल अनुरोध स्वीकार किया।',
