  'whenSomeoneSendsParcel': 'जब कोई आपको पार्सल भेजेगा, वह यहाँ दिखेगा।',
  'completedDeliveriesShowHere': 'पूर्ण डिलीवरी इस टैब में दिखेंगी।',
  'shipmentDetails': 'शिपमेंट विवरण',
  'chatWithTraveler': 'यात्री से चैट करें',
  'waitingForTravelerToChat': 'चैट के लिए यात्री की प्रतीक्षा',
  'chatWithSender': 'सेंडर से चैट करें',
