  'legalTerms1Body': '本条款与条件("条款")规范您对 WWNGO 移动应用及相关服务("平台")的使用。WWNGO 是一个连接寄件人(需要运送包裹)、旅客(正好前往该方向)与收件人(在目的地接收包裹)的点对点市场。创建账户并勾选"我同意条款和隐私政策"即表示您与 WWNGO 达成具有约束力的协议。如果您不同意,请不要注册或使用本平台。',
  'legalTerms2Heading': '2. WWNGO 是什么——又不是什么',
  'legalTerms2Body': 'WWNGO 提供匹配、应用内聊天、见面协调、身份核验、钱包支付、担保金托管、NFC 交接确认、追踪、评分及争议审核等服务。WWNGO 不是快递公司、邮政运营商、货运代理、报关行、保险公司,也不是旅客的雇主。配送由独立用户完成。除运营平台所必需外(例如存储您上传的照片),WWNGO 不会占有包裹。',
  'legalTerms3Heading': '3. 资格与账户',
  'legalTerms3Bullet1': '您必须年满18周岁,并具备订立具有约束力合同的能力。',
  'legalTerms3Bullet2': '您必须提供准确的姓名、电子邮箱、电话、国家和密码,并保持信息最新。',
  'legalTerms3Bullet3': '同一人可将同一个 WWNGO 账户用作寄件人、旅客和/或收件人。本条款适用于您使用的每一种角色。',
  'legalTerms3Bullet4': '在发布配送、发布行程、出价、接受包裹或转移资金之前,须完成电子邮箱和电话验证,以及通过我们的合作伙伴 Sumsub 进行的身份验证(KYC)。',
  'legalTerms3Bullet5': '您对账户上的活动负责。请勿共享登录凭据。如怀疑存在未经授权的访问,请通知 support@wwngo.com。',
  'legalTerms4Heading': '4. 寄件人的责任',
  'legalTerms4Body': '当您作为寄件人时,您会发布配送请求(城市到城市或国家到国家),描述包裹,设定预算,添加照片,并指定收件人。您同意:',
  'legalTerms4Bullet1': '如实提供包裹类别、尺寸、重量、内容描述、路线、出行日期和见面偏好。',
  'legalTerms4Bullet2': '只寄送在所选路线上合法持有和运输的物品,包括国际行程的海关和航空公司规定。',
  'legalTerms4Bullet3': '绝不列出被禁止、危险或非法的物品(见第10条)。',
  'legalTerms4Bullet4': '当您接受出价或还价时,为约定的旅客报酬提供担保金,并在立即支付时支付寄件人平台费用(文件和物品各为2美元,若您代付收件人费用则为3美元)。旅客和收件人的平台费用也会在立即支付时收取(先从钱包扣款,再用卡支付)。',
  'legalTerms4Bullet5': '在约定的出发见面地点与旅客会面,并完成 NFC检查点1(寄件人 ↔ 旅客)以确认交接。',
  'legalTerms4Bullet6': '仅通过 WWNGO 聊天就该配送进行沟通,并遵守应用中所述的取消规则和计时器。',
  'legalTerms5Heading': '5. 旅客的责任',
  'legalTerms5Body': '当您作为旅客时,您会发布行程,查看匹配的包裹请求,接受或还价,并在旅途中携带包裹。您同意:',
  'legalTerms5Bullet1': '准确发布出发地、目的地、出行日期和容量,并只接受您能够合法且安全携带的包裹。',
  'legalTerms5Bullet2': '当寄件人完成立即支付时,从您的钱包(如需要也可用卡)支付适用的旅客平台费用(文件和物品各为3美元)。',
  'legalTerms5Bullet3': '确认或提出见面地点,与寄件人完成 NFC检查点1,在运输途中确保包裹安全,并在目的地完成 NFC检查点2(旅客 ↔ 收件人)。',
  'legalTerms5Bullet4': '不得打开、使用、更换或丢弃包裹,也不得在 WWNGO 之外将配送分包给他人。',
  'legalTerms5Bullet5': '本着诚信更新配送状态(例如开始运输),并在聊天中及时回应。',
  'legalTerms5Bullet6': '遵守航空公司、边境和海关申报要求。您对自己实际携带的物品负责。',
  'legalTerms6Heading': '6. 收件人的责任',
  'legalTerms6Body': '当您作为收件人时,您会在某次配送中被指定,接受收到的请求,并在目的地领取包裹。您同意:',
  'legalTerms6Bullet1': '在接受前查看包裹详情。接受仅表示同意——除非寄件人代付,否则收件人平台费用(文件和物品各为2美元)将在寄件人立即支付时收取。',
  'legalTerms6Bullet2': '在目的地见面时随时可到场,核实包裹,并完成 NFC检查点2(旅客 ↔ 收件人)以确认交付。',
  'legalTerms6Bullet3': '如果包裹丢失、损坏或与描述不符,应立即在应用内提出争议,而不是在不接受货物的情况下完成 NFC 确认。',
  'legalTerms6Bullet4': '保持联系方式准确,以便寄件人和旅客可以协调。',
  'legalTerms7Heading': '7. 匹配、出价与预订',
  'legalTerms7Body': '寄件人可以发现旅客并发送请求。旅客可以收到匹配的请求,并接受、拒绝或发送还价。只有当寄件人接受价格、所需的 KYC 和验证均已完成、担保金已成功注入,且平台费用已按显示收取时,预订才会创建。选择某位旅客会锁定该预订。如果支付窗口或接受计时器过期,预订可能会自动取消,担保金本金将按第12条规定退还。',
  'legalTerms8Heading': '8. 见面地点与聊天',
  'legalTerms8Body': '各方使用应用内位置工具协调一个公开且合适的见面地点。当所需各方在应用中确认后,见面即被确认。寄件人—旅客、寄件人—收件人以及旅客—收件人之间的聊天会根据配送状态解锁。请勿在平台之外分享支付详情,也不要将交易转移到 WWNGO 之外进行。平台外支付将使担保金保护失效。',
  'legalTerms9Heading': '9. NFC检查点与配送确认',
  'legalTerms9Bullet1': 'NFC检查点1(寄件人 ↔ 旅客)确认寄件人已将包裹交给旅客。',
  'legalTerms9Bullet2': 'NFC检查点2(旅客 ↔ 收件人)确认收件人已收到包裹。双方都必须完成各自的触碰。成功完成检查点2会将配送标记为"已送达",并将担保金释放给旅客(除非因争议被冻结)。',
  'legalTerms9Bullet3': 'NFC 是一种确认工具,并非包裹状况的保证。照片、聊天记录、追踪信息和争议记录仍可用于审核。',
  'legalTerms9Bullet4': '滥用 NFC(未实际交接即确认、强迫他人触碰或伪造设备)将导致账户暂停及担保金冻结。',
  'legalTerms10Heading': '10. 禁止物品与零容忍行为',
  'legalTerms10Body': '您不得寄送、携带或请求以下物品:非法毒品、武器、爆炸物、危险材料、被盗物品、假冒物品、超出当地法律允许范围的现金或不记名票据、活体动物、人体遗骸,或承运人、航空公司或目的地国家禁止的任何物品。欺诈、虚假身份、虚假照片、骚扰、操纵评分以及规避担保金的行为均被禁止。WWNGO 可暂停账户、冻结担保金,并向主管部门举报非法活动。',
  'legalTerms11Heading': '11. 支付、钱包与担保金',
  'legalTerms11Bullet1': '您拥有一个在寄件人、旅客和收件人活动之间共享的 WWNGO 钱包。可通过 Stripe 充值,并在收款账户关联并准备就绪后通过 Stripe Connect 提现。交易记录会记录每一条目所对应的角色。',
  'legalTerms11Bullet2': '当寄件人接受某位旅客时,约定的报酬将从寄件人的可用余额转入担保金(如有差额可由卡支付补足)。担保金在释放、退款或争议裁决之前,任何一方均不可提取。',
  'legalTerms11Bullet3': '平台费用(寄件人、旅客和/或收件人的费用,包括寄件人可选代付收件人费用的情况)会在您确认之前公开披露,并按显示的金额收取。',
  'legalTerms11Bullet4': '担保金在 NFC检查点2 / 已送达之后释放给旅客,除非被冻结。WWNGO 不是银行;钱包余额是用于结算市场交易的平台记录。',
  'legalTerms12Heading': '12. 取消与退款',
  'legalTerms12Body': '已预订的配送可在行程处于运输中或已送达之前取消,须遵守应用内规则。担保金本金将退还给寄件人。如果取消发生在出行前超过24小时,平台费用将退还给付款方;在24小时内,平台费用一般不予退还。尚未预订的已发布配送可依照应用的发布规则取消。自动取消(例如未付款的收件人窗口期或已过期的接受计时器)将按产品中规定退还担保金本金。已完成的充值和付款不会撤销,除非法律要求或经正式争议裁决。',
  'legalTerms13Heading': '13. 追踪、照片与评价',
  'legalTerms13Body': '您提供的状态更新、包裹照片以及 GPS 或见面数据用于办理配送。配送完成后,各方可以留下评价。评价必须真实并与交易相关。WWNGO 可能隐藏或删除滥用性或虚假评价。',
  'legalTerms14Heading': '14. 争议',
  'legalTerms14Body': '如果出现问题(损坏、未送达、物品错误、NFC 争议),请在应用内提出争议。提出争议会冻结担保金,同时 WWNGO 将审查配送记录、照片、聊天记录、NFC检查点和身份数据。如果您打算对收货提出争议,请不要完成 NFC检查点2。WWNGO 就担保金作出的决定(释放、退款或分割)在平台上各方之间为最终决定,但不限制您在有管辖权的法院对其他用户可能拥有的任何权利。银行拒付或平台外索赔仍可能导致账户处理。',
  'legalTerms15Heading': '15. 责任限制',
  'legalTerms15Body': '在法律允许的最大范围内,WWNGO 不对因用户、承运人或政府造成的损失、延误、损坏、扣押或海关问题负责;不对寄件人、旅客或收件人的行为负责;也不对间接、附带或后果性损害负责。我们对您就与平台相关的索赔所承担的全部责任,限于以下两者中较高者:(a)您在索赔前12个月内为争议配送向 WWNGO 支付的平台费用,或(b)50美元。本条款中的任何内容均不排除依法不可排除的责任(包括因欺诈或因疏忽导致死亡/人身伤害且此类排除被禁止的情形)。',
  'legalTerms16Heading': '16. 变更、暂停与联系方式',
  'legalTerms16Body': '我们可能会更新本条款。在应用内通知后继续使用即表示接受修订后的条款。我们可能暂停或终止违反本条款的账户。问题请联系:support@wwngo.com。本条款构成您使用本平台的完整协议,并受 WWNGO 注册地适用法律管辖,但不影响您居住国的强制性消费者保护规定。',
  'legalPrivacy1Heading': '1. 简介',
  'legalPrivacy1Body': '本隐私政策说明当您作为寄件人、旅客和/或收件人使用我们的点对点包裹市场时,WWNGO 如何收集、使用、共享和保护个人数据。本政策适用于首次注册以及此后对同一账户的所有使用。创建账户即表示您认可本政策。如有疑问,请联系 privacy@wwngo.com。',
  'legalPrivacy2Heading': '2. 我们收集的数据',
  'legalPrivacy2Bullet1': '账户数据:全名、电子邮箱、电话(含国家/区域代码)、密码(以哈希方式存储)、国家、所选角色以及您添加的个人资料信息。',
  'legalPrivacy2Bullet2': '验证数据:电子邮箱和电话的一次性验证码状态;由 Sumsub 处理的 KYC 信息(身份证件、自拍照、活体检测及验证结果)。除非我们的 KYC 合作伙伴的流程有要求,WWNGO 只存储验证状态和引用信息,而非您的原始证件图像。',
  'legalPrivacy2Bullet3': '配送数据:路线、日期、包裹类别/尺寸/重量/描述、照片、收件人联系方式、见面地址、出价与还价、配送状态、NFC检查点记录、取消和争议记录。',
  'legalPrivacy2Bullet4': '通信信息:应用内聊天消息、附件及客服邮件。',
  'legalPrivacy2Bullet5': '支付信息:统一的钱包余额与账本(可用余额和担保金)、带有活动角色标签的交易描述、Stripe 支付及 Connect 标识符。卡号由 Stripe 处理,不会存储在 WWNGO 服务器上。',
  'legalPrivacy2Bullet6': '设备与使用信息:应用版本、设备类型、IP 地址、崩溃日志,以及用于发送提醒的推送通知令牌(FCM)。',
  'legalPrivacy3Heading': '3. 我们如何使用您的数据',
  'legalPrivacy3Bullet1': '创建并保护您的账户,并让您可以在寄件人、旅客和收件人之间切换。',
  'legalPrivacy3Bullet2': '将包裹与行程匹配,展示信息列表,并运行出价、计时器和预订锁定机制。',
  'legalPrivacy3Bullet3': '收取平台费用,将寄件人资金保存于担保金中,在 NFC检查点2 后向旅客释放报酬,并在取消或争议时处理退款。',
  'legalPrivacy3Bullet4': '支持见面协调、聊天、追踪、NFC 确认、评价和通知功能。',
  'legalPrivacy3Bullet5': '预防欺诈,执行本条款,审查争议,并履行法律义务。',
  'legalPrivacy3Bullet6': '提升可靠性和客户支持水平。我们不会出售您的个人数据。',
  'legalPrivacy4Heading': '4. 配送中按角色进行的信息共享',
  'legalPrivacy4Body': '为完成预订,仅向该次配送的其他相关方展示有限的个人资料和配送信息——例如姓名、评分、路线、包裹摘要、见面状态和聊天记录。旅客不会收到您完整的支付卡信息。收件人只能看到接受和领取包裹所需的信息。配送完成或取消后,访问权限将遵循产品规则(历史记录、评价、争议档案)。',
  'legalPrivacy5Heading': '5. 处理方与第三方',
  'legalPrivacy5Bullet1': 'Sumsub——身份验证(KYC)。',
  'legalPrivacy5Bullet2': 'Stripe——钱包充值、支付意图及 Connect 提现。',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging——推送通知。',
  'legalPrivacy5Bullet4': '邮箱/短信服务提供商——一次性验证码及交易类邮件。',
  'legalPrivacy5Bullet5': '按照我们的指示处理数据的托管和数据库服务提供商。',
  'legalPrivacy5Bullet6': '在法律要求或为保护用户免受严重伤害时的相关主管部门。',
  'legalPrivacy6Heading': '6. 数据保留、安全与国际传输',
  'legalPrivacy6Body': '只要您拥有账户,我们就会保留账户、账本、配送、NFC 及争议记录,此后还会在合理期限内继续保留,以完成付款、处理银行拒付,并履行簿记及法律义务。我们在传输过程中使用加密、访问控制以及统一的钱包记账方式。数据可能会在您所在国家以外的国家进行处理;我们会与处理方采取适当的保障措施。没有任何一种传输方式是100%安全的。',
  'legalPrivacy7Heading': '7. 您的权利',
  'legalPrivacy7Body': '在适用法律允许的范围内,您可以要求访问、更正、删除、限制或导出您的个人数据,并对某些处理提出异议。如果处理是基于同意进行的,您可以撤回同意(这不会影响此前合法处理的效力)。某些记录(担保金、KYC 状态、已完成的账本)在我们必须保留的情况下可能会被保留。请联系 privacy@wwngo.com。您也可以向您当地的数据保护主管部门投诉。',
  'legalPrivacy8Heading': '8. 未成年人、变更与联系方式',
  'legalPrivacy8Body': 'WWNGO 并非针对18岁以下的未成年人。我们不会在知情的情况下收集他们的数据。我们可能会更新本政策,并会在应用中公布新的日期。重大变更可能会通过应用内通知或电子邮件告知。联系方式:privacy@wwngo.com(隐私相关)或 support@wwngo.com(一般事务)。',
  'legalCookie1Heading': '什么是Cookie?',
  'legalCookie1Body': 'Cookie是存储在您设备上的小型文本文件。它们有助于记住您的偏好设置,并帮助我们了解您如何使用本网站。',
  'legalCookie2Heading': '我们使用的Cookie',
  'legalCookie2Bullet1': '必要性Cookie——安全和会话所需',
  'legalCookie2Bullet2': '分析性Cookie——帮助我们提升性能(可选)',
  'legalCookie2Bullet3': '偏好性Cookie——记住您的设置(可选)',
  'legalCookie3Heading': '管理Cookie',
  'legalCookie3Body': '您可以在浏览器设置中管理Cookie。禁用必要性Cookie可能会影响网站功能。',
  'newRequest': '新请求',
  'parcelRequest': '包裹请求',
  'requestAcceptedExclaim': '请求已接受！',
  'wantsToSendYouAParcel': '{name} 想给您寄送包裹。',
  'paymentDetails': '付款详情',
  'walletBalance': '钱包余额',
  'pickupLocation': '取件地点',
  'receiverLocation': '收件地点',
  'travelerToBeMatched': '旅客（待匹配）',
  'willBeAssigned': '待分配',
  'feeCoveredBySenderParen': '{amount}（由寄件人承担）',
  'chargedFromWalletOnPayNow': '寄件人点击立即支付（{amount}）时从您的钱包（或必要时从银行卡）扣款。点击接受时不会扣款。',
  'feeFullyCoveredBySender': '寄件人选择支付 100% 的平台费用。接受时不收费。',
  'requestAcceptedBody': '您的包裹请求已接受。我们将匹配旅客，并在寄件人完成付款后通知您。',
  'youAcceptedParcelRequest': '您已接受此包裹请求。',
  'youDeclinedParcelRequest': '您已拒绝此包裹请求。',
  'parcelsAddressedToYou': '寄给您的包裹',
  'incomingTab': '进行中',
  'pastTab': '历史',
  'reviewAndAcceptRequest': '查看并接受或拒绝此请求',
  'noIncomingParcels': '暂无进行中的包裹',
  'noPastDeliveries': '暂无历史配送',
  'whenSomeoneSendsParcel': '有人给您寄包裹时，将显示在此处。',
  'completedDeliveriesShowHere': '已完成的配送将显示在此标签页。',
  'shipmentDetails': '货运详情',
  'chatWithTraveler': '与旅客聊天',
  'waitingForTravelerToChat': '等待旅客聊天',
