  'legalTermsTitle': 'Şartlar ve Koşullar',
  'legalPrivacyTitle': 'Gizlilik Politikası',
  'legalLastUpdatedDate': '4 Eylül 2026',
  'legalTerms1Heading': '1. Bu Şartların Kabulü',
  'legalTerms1Body': 'Bu Şartlar ve Koşullar ("Şartlar"), WWNGO mobil uygulamasını ve ilgili hizmetleri ("Platform") kullanımınızı düzenler. WWNGO, bir paketin taşınmasını isteyen Göndericileri, zaten o yöne gitmekte olan Yolcuları ve varış noktasında paketi kabul eden Alıcıları birbirine bağlayan bir eşler arası pazar yeridir. Bir hesap oluşturup "Şartlar ve Gizlilik Politikasını kabul ediyorum" seçeneğini işaretleyerek WWNGO ile bağlayıcı bir sözleşmeye girersiniz. Kabul etmiyorsanız kaydolmayın ve Platformu kullanmayın.',
  'legalTerms2Heading': '2. WWNGO nedir — ve ne değildir',
  'legalTerms2Body': 'WWNGO; eşleştirme, uygulama içi sohbet, buluşma koordinasyonu, kimlik kontrolleri, cüzdan ödemeleri, emanet, NFC teslim onayı, takip, değerlendirmeler ve anlaşmazlık incelemesini kolaylaştırır. WWNGO bir kurye, posta operatörü, nakliye acentesi, gümrük komisyoncusu, sigortacı veya Yolcuların işvereni değildir. Teslimat bağımsız kullanıcılar tarafından gerçekleştirilir. WWNGO, Platformun işletilmesi için gerekli olmadıkça (örneğin yüklediğiniz fotoğrafları saklamak gibi) paketlere sahip olmaz.',
  'legalTerms3Heading': '3. Uygunluk ve hesaplar',
  'legalTerms3Bullet1': 'En az 18 yaşında olmalı ve bağlayıcı bir sözleşme yapabilecek durumda olmalısınız.',
  'legalTerms3Bullet2': 'Doğru ad, e-posta, telefon, ülke ve şifre sağlamalı ve bunları güncel tutmalısınız.',
  'legalTerms3Bullet3': 'Bir kişi, tek bir WWNGO hesabını Gönderici, Yolcu ve/veya Alıcı olarak kullanabilir. Bu Şartlar kullandığınız her rol için geçerlidir.',
  'legalTerms3Bullet4': 'Teslimat yayınlamadan, seyahat listelemeden, teklif vermeden, paket kabul etmeden veya para hareketi yapmadan önce e-posta ve telefon doğrulaması ile ortağımız Sumsub aracılığıyla kimlik doğrulaması (KYC) gereklidir.',
  'legalTerms3Bullet5': 'Hesabınızdaki etkinlikten siz sorumlusunuz. Giriş bilgilerinizi paylaşmayın. Yetkisiz erişimden şüphelenirseniz support@wwngo.com adresine bildirin.',
  'legalTerms4Heading': '4. Gönderici sorumlulukları',
  'legalTerms4Body': 'Gönderici olarak hareket ettiğinizde bir teslimat isteği yayınlarsınız (şehirden şehre veya ülkeden ülkeye), paketi tanımlarsınız, bir bütçe belirlersiniz, fotoğraf eklersiniz ve bir Alıcı belirlersiniz. Şunları kabul edersiniz:',
  'legalTerms4Bullet1': 'Doğru paket kategorisi, boyutu, ağırlığı, içerik açıklaması, güzergâh, seyahat tarihi ve buluşma tercihlerini sağlamak.',
  'legalTerms4Bullet2': 'Yalnızca seçilen güzergâhta bulundurulması ve taşınması yasal olan öğeleri göndermek, uluslararası seyahatler için gümrük ve havayolu kurallarını dahil etmek.',
  'legalTerms4Bullet3': 'Yasak, tehlikeli veya yasa dışı malları asla listelemek (Bölüm 10\'a bakın).',
  'legalTerms4Bullet4': 'Bir teklifi veya karşı teklifi kabul ettiğinizde anlaşılan yolcu ödemesi için emanete fon sağlamak ve Şimdi öde sırasında Gönderici platform ücretinizi ödemek (Belge ve Nesne için 2 \$, alıcının ücretini üstlenirseniz 3 \$). Yolcu ve Alıcı platform ücretleri de Şimdi öde sırasında tahsil edilir (önce cüzdandan, ardından kart).',
  'legalTerms4Bullet5': 'Kararlaştırılan çıkış buluşma noktasında Yolcuyla buluşmak ve teslimi onaylamak için NFC Kontrol Noktası 1\'i (Gönderici ↔ Yolcu) tamamlamak.',
  'legalTerms4Bullet6': 'Bu teslimat için yalnızca WWNGO sohbeti üzerinden iletişim kurmak ve uygulamada açıklanan iptal ve süre sınırlarına uymak.',
  'legalTerms5Heading': '5. Yolcu sorumlulukları',
  'legalTerms5Body': 'Yolcu olarak hareket ettiğinizde bir seyahat yayınlarsınız, eşleşen paket taleplerini incelersiniz, teklifleri kabul eder veya karşı teklif verirsiniz, ve seyahatiniz sırasında paketi taşırsınız. Şunları kabul edersiniz:',
  'legalTerms5Bullet1': 'Doğru çıkış noktası, varış noktası, seyahat tarihi ve kapasite yayınlamak, ve yalnızca yasal ve güvenli şekilde taşıyabileceğiniz paketleri kabul etmek.',
  'legalTerms5Bullet2': 'Gönderici Şimdi öde işlemini tamamladığında geçerli Yolcu platform ücretlerini (Belge ve Nesne için 3 \$) cüzdanınızdan (gerekirse kartla) ödemek.',
  'legalTerms5Bullet3': 'Buluşma noktalarını onaylamak veya önermek, Gönderici ile NFC Kontrol Noktası 1\'i tamamlamak, taşıma sırasında paketi güvende tutmak, ve varış noktasında NFC Kontrol Noktası 2\'yi (Yolcu ↔ Alıcı) tamamlamak.',
  'legalTerms5Bullet4': 'Bir paketi açmamak, kullanmamak, değiştirmemek veya bırakmamak, ve teslimatı WWNGO dışında bir alt yükleniciye vermemek.',
  'legalTerms5Bullet5': 'Sevkiyat durumunu iyi niyetle güncellemek (örneğin taşımaya başlarken) ve sohbette hızlıca yanıt vermek.',
  'legalTerms5Bullet6': 'Havayolu, sınır ve gümrük beyanlarına uymak. Fiziksel olarak taşıdığınız şeylerden siz sorumlusunuz.',
  'legalTerms6Heading': '6. Alıcı sorumlulukları',
  'legalTerms6Body': 'Alıcı olarak hareket ettiğinizde bir teslimatta adınız belirtilir, gelen isteği kabul edersiniz ve varış noktasında paketi alırsınız. Şunları kabul edersiniz:',
  'legalTerms6Bullet1': 'Kabul etmeden önce paket detaylarını incelemek. Kabul etmek yalnızca bir onay anlamına gelir — gönderici bunu üstlenmediği sürece, gönderici Şimdi öde işleminde bir Alıcı platform ücreti (Belge ve Nesne için 2 \$) tahsil edilir.',
  'legalTerms6Bullet2': 'Varış buluşmasında hazır olmak, paketi doğrulamak ve teslimi onaylamak için NFC Kontrol Noktası 2\'yi (Yolcu ↔ Alıcı) tamamlamak.',
  'legalTerms6Bullet3': 'Paket eksik, zarar görmüş veya açıklamaya uymuyorsa, malları kabul etmiyorsanız NFC onayını tamamlamak yerine uygulamada hızlıca bir anlaşmazlık açmak.',
  'legalTerms6Bullet4': 'Gönderici ve Yolcunun koordinasyon sağlayabilmesi için iletişim bilgilerini doğru tutmak.',
  'legalTerms7Heading': '7. Eşleştirme, teklifler ve rezervasyon',
  'legalTerms7Body': 'Göndericiler yolcuları keşfedebilir ve istek gönderebilir. Yolcular eşleşen istekler alabilir, kabul edebilir, reddedebilir veya karşı teklif gönderebilir. Bir rezervasyon, yalnızca Gönderici bir fiyatı kabul ettiğinde, gerekli KYC ve doğrulama tamamlandığında, emanet başarıyla fonlandığında ve platform ücretleri gösterildiği şekilde tahsil edildiğinde oluşturulur. Bir Yolcunun seçilmesi rezervasyonu kilitler. Bir ödeme penceresi veya kabul süresi dolarsa, rezervasyon otomatik olarak iptal edilebilir ve emanet anaparası Bölüm 12\'ye göre geri ödenir.',
  'legalTerms8Heading': '8. Buluşma noktaları ve sohbet',
  'legalTerms8Body': 'Taraflar, uygulama içi konum araçlarını kullanarak halka açık, uygun bir buluşma koordine eder. Gerekli taraflar bunu uygulamada kabul ettiğinde bir buluşma onaylanır. Gönderici–Yolcu, Gönderici–Alıcı ve Yolcu–Alıcı arasındaki sohbet, teslimat durumuna göre açılır. Ödeme detaylarını platform dışında paylaşmayın veya anlaşmayı WWNGO dışına taşımayın. Platform dışı ödemeler emanet korumasını geçersiz kılar.',
  'legalTerms9Heading': '9. NFC kontrol noktaları ve teslimat onayı',
  'legalTerms9Bullet1': 'NFC Kontrol Noktası 1 (Gönderici ↔ Yolcu), Göndericinin paketi Yolcuya teslim ettiğini doğrular.',
  'legalTerms9Bullet2': 'NFC Kontrol Noktası 2 (Yolcu ↔ Alıcı), Alıcının paketi aldığını doğrular. Her iki taraf da dokunuşunu tamamlamalıdır. Başarılı bir Kontrol Noktası 2, sevkiyatı Teslim Edildi olarak işaretler ve emaneti Yolcuya serbest bırakır (bir anlaşmazlık nedeniyle dondurulmadığı sürece).',
  'legalTerms9Bullet3': 'NFC bir onay aracıdır, paketin durumunun garantisi değildir. Fotoğraflar, sohbet, takip ve anlaşmazlık kayıtları bir incelemede hâlâ kullanılabilir.',
  'legalTerms9Bullet4': 'NFC\'nin kötüye kullanılması (gerçek bir teslim olmadan onaylamak, dokunuşa zorlamak veya cihazları sahtelemek) askıya alma ve emanetin dondurulması için gerekçe oluşturur.',
  'legalTerms10Heading': '10. Yasak öğeler ve sıfır tolerans davranışı',
  'legalTerms10Body': 'Şunları göndermemeli, taşımamalı veya talep etmemelisiniz: yasa dışı uyuşturucular, silahlar, patlayıcılar, tehlikeli maddeler, çalıntı mallar, sahte ürünler, yerel yasaların izin verdiğinin ötesinde nakit veya hamiline yazılı belgeler, canlı hayvanlar, insan kalıntıları veya taşıyıcı, havayolu ya da varış ülkesi tarafından yasaklanan herhangi bir öğe. Dolandırıcılık, sahte kimlik, sahte fotoğraflar, taciz, değerlendirme manipülasyonu ve emaneti atlatma girişimleri yasaktır. WWNGO hesapları askıya alabilir, emaneti dondurabilir ve yasa dışı faaliyetleri yetkililere bildirebilir.',
  'legalTerms11Heading': '11. Ödemeler, cüzdanlar ve emanet',
  'legalTerms11Bullet1': 'Gönderici, Yolcu ve Alıcı etkinlikleriniz arasında paylaşılan tek bir WWNGO cüzdanınız vardır. Stripe ile bakiye yükleyin ve bir ödeme hesabı bağlanıp hazır olduğunda Stripe Connect üzerinden para çekin. İşlem geçmişi her girişin hangi role ait olduğunu kaydeder.',
  'legalTerms11Bullet2': 'Bir Gönderici bir Yolcuyu kabul ettiğinde, anlaşılan ödeme Göndericinin kullanılabilir bakiyesinden emanete taşınır (kart ödemesi bir açığı kapatabilir). Emanet, serbest bırakma, geri ödeme veya bir anlaşmazlık kararı verilene kadar hiçbir taraf tarafından çekilemez.',
  'legalTerms11Bullet3': 'Platform ücretleri (Gönderici, Yolcu ve/veya Alıcı için, isteğe bağlı olarak Göndericinin Alıcı ücretini üstlenmesi dahil) onayınızdan önce açıklanır ve gösterildiği şekilde tahsil edilir.',
  'legalTerms11Bullet4': 'Emanet, dondurulmadığı sürece NFC Kontrol Noktası 2 / Teslim Edildi sonrasında Yolcuya serbest bırakılır. WWNGO bir banka değildir; cüzdan bakiyeleri, pazar yeri işlemlerini sonuçlandırmak için kullanılan Platform kayıtlarıdır.',
  'legalTerms12Heading': '12. İptaller ve geri ödemeler',
  'legalTerms12Body': 'Rezerve edilmiş teslimatlar, uygulama içi kurallara bağlı olarak seyahat taşıma sürecinde veya teslim edilmeden önce iptal edilebilir. Emanet anaparası Göndericiye geri ödenir. İptal, seyahatten 24 saatten fazla önce gerçekleşirse platform ücretleri ödeyen taraflara geri ödenir; 24 saat içinde platform ücretleri genellikle geri ödenmez. Henüz rezerve edilmemiş yayınlanmış teslimatlar, uygulamadaki yayınlama kurallarına göre iptal edilebilir. Otomatik iptal (örneğin ödenmemiş Alıcı pencereleri veya süresi dolmuş kabul süreleri), üründe belirtildiği şekilde emanet anaparasını geri öder. Bakiye yüklemeleri ve tamamlanmış ödemeler, yasanın gerektirdiği veya resmi bir anlaşmazlık sonucu durumları dışında geri alınmaz.',
  'legalTerms13Heading': '13. Takip, fotoğraflar ve değerlendirmeler',
  'legalTerms13Body': 'Sağladığınız durum güncellemeleri, paket fotoğrafları ve GPS veya buluşma verileri, teslimatı yürütmek için kullanılır. Teslimattan sonra taraflar değerlendirme bırakabilir. Değerlendirmeler dürüst olmalı ve işlemle ilgili olmalıdır. WWNGO, kötüye kullanılan veya sahte değerlendirmeleri gizleyebilir veya kaldırabilir.',
  'legalTerms14Heading': '14. Anlaşmazlıklar',
  'legalTerms14Body': 'Bir şey yanlış giderse (hasar, teslim edilmeme, yanlış öğe, NFC anlaşmazlığı), uygulamada bir anlaşmazlık açın. Bir anlaşmazlık açmak, WWNGO teslimat kayıtlarını, fotoğrafları, sohbeti, NFC kontrol noktalarını ve kimlik verilerini incelerken emaneti dondurur. Teslimatı itiraz etmeyi düşünüyorsanız NFC Kontrol Noktası 2\'yi tamamlamayın. WWNGO\'nun emanet (serbest bırakma, geri ödeme veya bölme) konusundaki kararı, yetkili bir mahkemede başka bir kullanıcıya karşı sahip olabileceğiniz hakları sınırlamadan, Platform üzerindeki taraflar arasında nihaidir. Ters ibrazlar veya platform dışı talepler yine de hesap işlemine yol açabilir.',
  'legalTerms15Heading': '15. Sorumluluğun sınırlandırılması',
  'legalTerms15Body': 'Yasaların izin verdiği azami ölçüde, WWNGO; kullanıcılar, taşıyıcılar veya hükümetler tarafından yol açılan kayıp, gecikme, hasar, alıkoyma veya gümrük sorunlarından; Göndericilerin, Yolcuların veya Alıcıların eylemlerinden; ya da dolaylı, arızi veya sonuçsal zararlardan sorumlu değildir. Platformla ilgili bir talep için size karşı toplam sorumluluğumuz, (a) talepten önceki 12 ay içinde anlaşmazlık konusu teslimat için WWNGO\'ya ödediğiniz platform ücretleri ya da (b) 50 USD tutarlarından hangisi daha yüksekse onunla sınırlıdır. Bu Şartlardaki hiçbir şey, yasal olarak hariç tutulamayan sorumluluğu (bu tür bir hariç tutmanın yasak olduğu durumlarda ihmal nedeniyle dolandırıcılık veya ölüm/kişisel yaralanma dahil) hariç tutmaz.',
  'legalTerms16Heading': '16. Değişiklikler, askıya alma ve iletişim',
  'legalTerms16Body': 'Bu Şartları güncelleyebiliriz. Uygulama içi bir bildirimden sonra kullanıma devam edilmesi, revize edilmiş Şartların kabulü anlamına gelir. Bu Şartları ihlal eden hesapları askıya alabilir veya sonlandırabiliriz. Sorular: support@wwngo.com. Bu Şartlar, Platformu kullanımınızla ilgili tam anlaşmayı oluşturur ve WWNGO\'nun kuruluş yerine uygulanan yasalara tabidir; bu, ikamet ettiğiniz ülkedeki zorunlu tüketici korumalarını etkilemez.',
  'legalPrivacy1Heading': '1. Giriş',
  'legalPrivacy1Body': 'Bu Gizlilik Politikası, Gönderici, Yolcu ve/veya Alıcı olarak eşler arası paket pazar yerimizi kullandığınızda WWNGO\'nun kişisel verileri nasıl topladığını, kullandığını, paylaştığını ve koruduğunu açıklar. İlk kayıt ve aynı hesabın sonraki tüm kullanımları için geçerlidir. Bir hesap oluşturarak bu Politikayı kabul edersiniz. Sorularınız için privacy@wwngo.com ile iletişime geçin.',
  'legalPrivacy2Heading': '2. Topladığımız veriler',
  'legalPrivacy2Bullet1': 'Hesap verileri: tam ad, e-posta, telefon (ülke/çevir kodu ile), şifre (hash olarak saklanır), ülke, seçilen rol ve eklediğiniz profil bilgileri.',
  'legalPrivacy2Bullet2': 'Doğrulama verileri: e-posta ve telefon OTP durumu; Sumsub tarafından işlenen KYC bilgileri (kimlik belgesi, selfie, canlılık kontrolü ve doğrulama sonucu). WWNGO, KYC ortağımızın süreci gerektirmediği sürece ham kimlik görüntülerinizi değil, doğrulama durumunu ve referansları saklar.',
  'legalPrivacy2Bullet3': 'Teslimat verileri: güzergâhlar, tarihler, paket kategorisi/boyutu/ağırlığı/açıklaması, fotoğraflar, Alıcı iletişim bilgileri, buluşma adresleri, teklifler ve karşı teklifler, sevkiyat durumu, NFC kontrol noktası kayıtları, iptal ve anlaşmazlık kayıtları.',
  'legalPrivacy2Bullet4': 'İletişimler: uygulama içi sohbet mesajları, ekler ve destek e-postaları.',
  'legalPrivacy2Bullet5': 'Ödemeler: birleşik cüzdan bakiyesi ve muhasebe defteri (kullanılabilir bakiye ve emanet), etkinlik rolü etiketleri içeren işlem açıklamaları, Stripe ödeme ve Connect tanımlayıcıları. Kart numaraları Stripe tarafından işlenir ve WWNGO sunucularında saklanmaz.',
  'legalPrivacy2Bullet6': 'Cihaz ve kullanım: uygulama sürümü, cihaz türü, IP adresi, çökme günlükleri ve uyarı iletmek için push bildirim tokenları (FCM).',
  'legalPrivacy3Heading': '3. Verilerinizi nasıl kullanıyoruz',
  'legalPrivacy3Bullet1': 'Hesabınızı oluşturmak ve güvence altına almak, ve Gönderici, Yolcu ve Alıcı arasında geçiş yapmanızı sağlamak.',
  'legalPrivacy3Bullet2': 'Paketleri seyahatlerle eşleştirmek, ilanları göstermek ve teklifleri, süreleri ve rezervasyon kilitlerini yürütmek.',
  'legalPrivacy3Bullet3': 'Platform ücretlerini tahsil etmek, Gönderici fonlarını emanette tutmak, NFC Kontrol Noktası 2 sonrasında Yolculara ödeme yapmak ve iptal veya anlaşmazlık durumunda geri ödemeleri işlemek.',
  'legalPrivacy3Bullet4': 'Buluşma koordinasyonunu, sohbeti, takibi, NFC onayını, değerlendirmeleri ve bildirimleri etkinleştirmek.',
  'legalPrivacy3Bullet5': 'Dolandırıcılığı önlemek, bu Şartları uygulamak, anlaşmazlıkları incelemek ve yasal yükümlülükleri karşılamak.',
  'legalPrivacy3Bullet6': 'Güvenilirliği ve müşteri desteğini iyileştirmek. Kişisel verilerinizi satmıyoruz.',
  'legalPrivacy4Heading': '4. Bir teslimatta role özgü paylaşım',
  'legalPrivacy4Body': 'Bir rezervasyonu tamamlamak için, sınırlı profil ve teslimat bilgileri yalnızca o sevkiyattaki diğer taraflara gösterilir — örneğin adlar, değerlendirmeler, güzergâh, paket özeti, buluşma durumu ve sohbet. Bir Yolcu, ödeme kartınızın tüm bilgilerini almaz. Bir Alıcı, paketi kabul etmek ve almak için gereken bilgileri görür. Teslimat veya iptal sonrasında erişim, ürün kurallarını (geçmiş, değerlendirmeler, anlaşmazlık dosyaları) takip eder.',
  'legalPrivacy5Heading': '5. İşleyenler ve üçüncü taraflar',
  'legalPrivacy5Bullet1': 'Sumsub — kimlik doğrulama (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — cüzdan bakiye yükleme, ödeme niyetleri ve Connect ödemeleri.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — push bildirimleri.',
  'legalPrivacy5Bullet4': 'E-posta/SMS sağlayıcıları — tek kullanımlık kodlar ve işlemsel e-postalar.',
  'legalPrivacy5Bullet5': 'Talimatlarımız doğrultusunda veri işleyen barındırma ve veritabanı sağlayıcıları.',
  'legalPrivacy5Bullet6': 'Yasal olarak gerekli olduğunda veya kullanıcıları ciddi zarardan korumak için yetkililer.',
  'legalPrivacy6Heading': '6. Saklama, güvenlik ve uluslararası aktarım',
  'legalPrivacy6Body': 'Hesap, muhasebe defteri, teslimat, NFC ve anlaşmazlık kayıtlarını, hesabınız olduğu sürece ve ardından ödemeleri tamamlamak, ters ibrazları ele almak ve muhasebe ile yasal görevleri karşılamak için makul bir süre boyunca saklarız. Aktarım sırasında şifreleme, erişim kontrolleri ve birleşik cüzdan muhasebesi kullanırız. Veriler sizin ülkenizden farklı ülkelerde işlenebilir; işleyenlerle uygun güvenceler kullanırız. Hiçbir iletim yöntemi %100 güvenli değildir.',
  'legalPrivacy7Heading': '7. Haklarınız',
  'legalPrivacy7Body': 'Geçerli yasalara bağlı olarak, kişisel verilerinize erişim, düzeltme, silme, kısıtlama veya dışa aktarma talep edebilir ve belirli işlemlere itiraz edebilirsiniz. İşleme rıza temeline dayanıyorsa rızanızı geri çekebilirsiniz (bu, önceki yasal işlemenin geçerliliğini etkilemez). Bazı kayıtlar (emanet, KYC durumu, tamamlanmış muhasebe defterleri), bunları saklamamız gerektiğinde muhafaza edilebilir. privacy@wwngo.com ile iletişime geçin. Ayrıca yerel veri koruma otoritenize şikâyette bulunabilirsiniz.',
  'legalPrivacy8Heading': '8. Çocuklar, değişiklikler ve iletişim',
  'legalPrivacy8Body': 'WWNGO, 18 yaşından küçük çocuklara yönelik değildir. Bilerek onların verilerini toplamayız. Bu Politikayı güncelleyebiliriz ve yeni tarihi uygulamada yayınlarız. Önemli değişiklikler uygulama içinde veya e-posta ile bildirilebilir. İletişim: privacy@wwngo.com (gizlilik) veya support@wwngo.com (genel).',
  'legalCookie1Heading': 'Çerezler nedir?',
  'legalCookie1Body': 'Çerezler, cihazınızda saklanan küçük metin dosyalarıdır. Tercihlerinizi hatırlamaya ve sitemizi nasıl kullandığınızı anlamaya yardımcı olurlar.',
  'legalCookie2Heading': 'Kullandığımız çerezler',
  'legalCookie2Bullet1': 'Gerekli — güvenlik ve oturumlar için gereklidir',
  'legalCookie2Bullet2': 'Analitik — performansı iyileştirmemize yardımcı olur (isteğe bağlı)',
  'legalCookie2Bullet3': 'Tercihler — ayarlarınızı hatırlar (isteğe bağlı)',
  'legalCookie3Heading': 'Çerezleri yönetme',
  'legalCookie3Body': 'Çerezleri tarayıcı ayarlarınızdan kontrol edebilirsiniz. Gerekli çerezleri devre dışı bırakmak site işlevselliğini etkileyebilir.',
