  'legalTermsTitle': 'Условия использования',
  'legalPrivacyTitle': 'Политика конфиденциальности',
  'legalLastUpdatedDate': '4 сентября 2026 г.',
  'legalTerms1Heading': '1. Согласие с настоящими Условиями',
  'legalTerms1Body': 'Настоящие Условия использования («Условия») регулируют использование вами мобильного приложения WWNGO и связанных сервисов («Платформа»). WWNGO — это площадка для прямого взаимодействия между пользователями, которая связывает Отправителей, которым нужно отправить посылку, Путешественников, которые уже направляются в нужную сторону, и Получателей, которые принимают посылку в пункте назначения. Создавая учётную запись и отмечая «Я принимаю Условия и Политику конфиденциальности», вы заключаете обязательное соглашение с WWNGO. Если вы не согласны, не регистрируйтесь и не используйте Платформу.',
  'legalTerms2Heading': '2. Что представляет собой WWNGO — и чем он не является',
  'legalTerms2Body': 'WWNGO обеспечивает подбор пар, чат внутри приложения, координацию встреч, проверку личности, платежи через кошелёк, эскроу, подтверждение передачи через NFC, отслеживание, оценки и рассмотрение споров. WWNGO не является курьерской службой, почтовым оператором, транспортно-экспедиционной компанией, таможенным брокером, страховщиком или работодателем Путешественников. Доставка выполняется независимыми пользователями. WWNGO не завладевает посылками, кроме случаев, когда это необходимо для работы Платформы (например, для хранения загружаемых вами фотографий).',
  'legalTerms3Heading': '3. Право на использование и учётные записи',
  'legalTerms3Bullet1': 'Вам должно быть не менее 18 лет, и вы должны быть способны заключать обязательный договор.',
  'legalTerms3Bullet2': 'Вы обязаны предоставить точные имя, адрес электронной почты, номер телефона, страну и пароль, а также поддерживать их актуальность.',
  'legalTerms3Bullet3': 'Один человек может использовать одну учётную запись WWNGO в качестве Отправителя, Путешественника и/или Получателя. Настоящие Условия применяются к каждой роли, которую вы используете.',
  'legalTerms3Bullet4': 'Перед публикацией доставок, размещением поездок, подачей предложений, принятием посылок или переводом денежных средств требуется подтверждение адреса электронной почты и телефона, а также проверка личности (KYC) через нашего партнёра Sumsub.',
  'legalTerms3Bullet5': 'Вы несёте ответственность за действия в вашей учётной записи. Не передавайте свои учётные данные для входа третьим лицам. Сообщите на support@wwngo.com, если подозреваете несанкционированный доступ.',
  'legalTerms4Heading': '4. Обязанности Отправителя',
  'legalTerms4Body': 'Действуя в качестве Отправителя, вы размещаете запрос на доставку (из города в город или из страны в страну), описываете посылку, устанавливаете бюджет, добавляете фотографии и указываете Получателя. Вы обязуетесь:',
  'legalTerms4Bullet1': 'Указывать достоверную категорию посылки, размер, вес, описание содержимого, маршрут, дату поездки и предпочтения по месту встречи.',
  'legalTerms4Bullet2': 'Отправлять только те предметы, владение и перевозка которых законны на выбранном маршруте, включая таможенные и авиационные правила для международных поездок.',
  'legalTerms4Bullet3': 'Никогда не указывать запрещённые, опасные или незаконные товары (см. Раздел 10).',
  'legalTerms4Bullet4': 'Финансировать эскроу для согласованной выплаты путешественнику при принятии предложения или встречного предложения, а также оплачивать комиссию платформы Отправителя при нажатии «Оплатить сейчас» (2 \$ за Документ и Предмет, либо 3 \$, если вы оплачиваете комиссию получателя). Комиссии платформы Путешественника и Получателя также взимаются при «Оплатить сейчас» (сначала с кошелька, затем с карты).',
  'legalTerms4Bullet5': 'Встретиться с Путешественником в согласованном месте встречи в пункте отправления и завершить контрольную точку NFC 1 (Отправитель ↔ Путешественник) для подтверждения передачи.',
  'legalTerms4Bullet6': 'Общаться по данной доставке только через чат WWNGO и соблюдать правила отмены и таймеры, описанные в приложении.',
  'legalTerms5Heading': '5. Обязанности Путешественника',
  'legalTerms5Body': 'Действуя в качестве Путешественника, вы размещаете поездку, просматриваете подходящие запросы на посылки, принимаете предложения или делаете встречные предложения, и перевозите посылку во время своей поездки. Вы обязуетесь:',
  'legalTerms5Bullet1': 'Указывать точные пункт отправления, пункт назначения, дату поездки и вместимость, и принимать только те посылки, которые можете перевозить законно и безопасно.',
  'legalTerms5Bullet2': 'Оплачивать применимые комиссии платформы Путешественника (3 \$ за Документ и Предмет) со своего кошелька (или картой при необходимости), когда Отправитель завершает «Оплатить сейчас».',
  'legalTerms5Bullet3': 'Подтверждать или предлагать места встречи, завершать контрольную точку NFC 1 с Отправителем, обеспечивать сохранность посылки во время перевозки, и завершать контрольную точку NFC 2 (Путешественник ↔ Получатель) в пункте назначения.',
  'legalTerms5Bullet4': 'Не открывать, не использовать, не обменивать и не оставлять посылку без внимания, а также не передавать доставку сторонним исполнителям за пределами WWNGO.',
  'legalTerms5Bullet5': 'Добросовестно обновлять статус отправления (например, при начале перевозки) и оперативно отвечать в чате.',
  'legalTerms5Bullet6': 'Соблюдать декларации авиакомпании, пограничные и таможенные требования. Вы несёте ответственность за то, что физически перевозите.',
  'legalTerms6Heading': '6. Обязанности Получателя',
  'legalTerms6Body': 'Действуя в качестве Получателя, вы указаны в доставке, принимаете входящий запрос и забираете посылку в пункте назначения. Вы обязуетесь:',
  'legalTerms6Bullet1': 'Проверять детали посылки перед принятием. Принятие означает только согласие — комиссия платформы Получателя (2 \$ за Документ и Предмет) взимается при «Оплатить сейчас» отправителя, если отправитель не покрывает её.',
  'legalTerms6Bullet2': 'Быть доступным на встрече в пункте назначения, проверить посылку и завершить контрольную точку NFC 2 (Путешественник ↔ Получатель) для подтверждения доставки.',
  'legalTerms6Bullet3': 'Незамедлительно открывать спор в приложении, если посылка отсутствует, повреждена или не соответствует описанию, вместо завершения подтверждения NFC, если вы не принимаете товар.',
  'legalTerms6Bullet4': 'Поддерживать точность контактных данных, чтобы Отправитель и Путешественник могли координироваться.',
  'legalTerms7Heading': '7. Подбор, предложения и бронирование',
  'legalTerms7Body': 'Отправители могут находить путешественников и отправлять запросы. Путешественники могут получать подходящие запросы, принимать их, отклонять или отправлять встречное предложение. Бронирование создаётся только тогда, когда Отправитель принимает цену, завершены необходимые KYC и проверка, эскроу успешно профинансировано, и комиссии платформы взимаются в указанном размере. Выбор Путешественника блокирует бронирование. Если истекает окно оплаты или таймер принятия, бронирование может быть автоматически отменено, а основная сумма эскроу возвращается в соответствии с Разделом 12.',
  'legalTerms8Heading': '8. Места встречи и чат',
  'legalTerms8Body': 'Стороны координируют публичную, подходящую встречу с помощью инструментов геолокации в приложении. Встреча считается подтверждённой, когда необходимые стороны принимают её в приложении. Чат между Отправителем и Путешественником, Отправителем и Получателем, а также Путешественником и Получателем открывается в зависимости от статуса доставки. Не сообщайте платёжные данные за пределами платформы и не переносите сделку за пределы WWNGO. Платежи вне платформы аннулируют защиту эскроу.',
  'legalTerms9Heading': '9. Контрольные точки NFC и подтверждение доставки',
  'legalTerms9Bullet1': 'Контрольная точка NFC 1 (Отправитель ↔ Путешественник) подтверждает, что Отправитель передал посылку Путешественнику.',
  'legalTerms9Bullet2': 'Контрольная точка NFC 2 (Путешественник ↔ Получатель) подтверждает, что Получатель получил посылку. Обе стороны должны выполнить своё касание. Успешное прохождение Контрольной точки 2 отмечает отправление как Доставлено и высвобождает эскроу в пользу Путешественника (если оно не заморожено из-за спора).',
  'legalTerms9Bullet3': 'NFC — это инструмент подтверждения, а не гарантия состояния посылки. Фотографии, чат, отслеживание и записи о спорах могут всё равно использоваться при рассмотрении.',
  'legalTerms9Bullet4': 'Неправомерное использование NFC (подтверждение без реальной передачи, принуждение к касанию или подмена устройств) является основанием для блокировки и заморозки эскроу.',
  'legalTerms10Heading': '10. Запрещённые предметы и нулевая терпимость',
  'legalTerms10Body': 'Вам запрещено отправлять, перевозить или запрашивать: незаконные наркотики, оружие, взрывчатые вещества, опасные материалы, украденные товары, контрафактные изделия, наличные средства или ценные бумаги на предъявителя сверх разрешённого местным законодательством, живых животных, человеческие останки, а также любые предметы, запрещённые перевозчиком, авиакомпанией или страной назначения. Запрещены мошенничество, поддельная личность, поддельные фотографии, преследование, манипулирование оценками и попытки обойти эскроу. WWNGO может блокировать учётные записи, замораживать эскроу и сообщать о незаконной деятельности властям.',
  'legalTerms11Heading': '11. Платежи, кошельки и эскроу',
  'legalTerms11Bullet1': 'У вас есть один кошелёк WWNGO, общий для действий в роли Отправителя, Путешественника и Получателя. Пополняйте баланс через Stripe и выводите средства через Stripe Connect после привязки и готовности счёта для выплат. История транзакций фиксирует, к какой роли относится каждая запись.',
  'legalTerms11Bullet2': 'Когда Отправитель принимает Путешественника, согласованная выплата переводится из доступного баланса Отправителя в эскроу (платёж картой может покрыть недостающую сумму). Ни одна из сторон не может вывести средства из эскроу до их высвобождения, возврата или решения по спору.',
  'legalTerms11Bullet3': 'Комиссии платформы (Отправителя, Путешественника и/или Получателя, включая опцию, при которой Отправитель покрывает комиссию Получателя) раскрываются до вашего подтверждения и взимаются в указанном размере.',
  'legalTerms11Bullet4': 'Эскроу высвобождается в пользу Путешественника после контрольной точки NFC 2 / статуса «Доставлено», если оно не заморожено. WWNGO не является банком; остатки кошелька — это записи Платформы, используемые для расчётов по операциям на площадке.',
  'legalTerms12Heading': '12. Отмены и возвраты средств',
  'legalTerms12Body': 'Забронированные доставки можно отменить до того, как поездка окажется в пути или будет доставлена, с учётом правил приложения. Основная сумма эскроу возвращается Отправителю. Комиссии платформы возвращаются оплатившим их сторонам, если отмена происходит более чем за 24 часа до поездки; в течение 24 часов комиссии платформы, как правило, не подлежат возврату. Опубликованные, но ещё не забронированные доставки можно отменить в соответствии с правилами публикации в приложении. Автоматическая отмена (например, неоплаченные окна Получателя или истёкшие таймеры принятия) возвращает основную сумму эскроу, как указано в продукте. Пополнения и завершённые выплаты не отменяются, за исключением случаев, предусмотренных законом, или по итогам официального решения по спору.',
  'legalTerms13Heading': '13. Отслеживание, фотографии и отзывы',
  'legalTerms13Body': 'Обновления статуса, фотографии посылки, а также данные GPS или о встрече, предоставленные вами, используются для организации доставки. После доставки стороны могут оставлять отзывы. Отзывы должны быть честными и относиться к сделке. WWNGO может скрывать или удалять оскорбительные или поддельные отзывы.',
  'legalTerms14Heading': '14. Споры',
  'legalTerms14Body': 'Если что-то пошло не так (повреждение, недоставка, неверный товар, спор по NFC), откройте спор в приложении. Открытие спора замораживает эскроу, пока WWNGO рассматривает записи о доставке, фотографии, чат, контрольные точки NFC и данные идентификации. Не завершайте контрольную точку NFC 2, если вы намерены оспорить получение. Решение WWNGO по эскроу (высвобождение, возврат или разделение) является окончательным между сторонами на Платформе, не ограничивая при этом никаких прав, которые вы можете иметь в отношении другого пользователя в компетентном суде. Возврат платежей через банк или претензии за пределами платформы всё равно могут повлечь действия в отношении учётной записи.',
  'legalTerms15Heading': '15. Ограничение ответственности',
  'legalTerms15Body': 'В максимальной степени, разрешённой законом, WWNGO не несёт ответственности за утрату, задержку, повреждение, изъятие или таможенные проблемы, вызванные пользователями, перевозчиками или государственными органами; за действия Отправителей, Путешественников или Получателей; а также за косвенные, случайные или вытекающие убытки. Наша общая ответственность перед вами по претензии, связанной с Платформой, ограничена наибольшей из следующих сумм: (a) комиссии платформы, уплаченные вами WWNGO за спорную доставку в течение 12 месяцев до предъявления претензии, или (b) 50 долларов США. Ничто в настоящих Условиях не исключает ответственность, которая не может быть законно исключена (включая случаи мошенничества или смерти/телесных повреждений, вызванных небрежностью, если такое исключение запрещено).',
  'legalTerms16Heading': '16. Изменения, блокировка и контакты',
  'legalTerms16Body': 'Мы можем обновлять настоящие Условия. Продолжение использования после уведомления в приложении означает принятие пересмотренных Условий. Мы можем блокировать или прекращать действие учётных записей, нарушающих настоящие Условия. Вопросы: support@wwngo.com. Настоящие Условия представляют собой полное соглашение относительно использования вами Платформы и регулируются законодательством, применимым по месту регистрации WWNGO, без ущерба для обязательных мер защиты потребителей в стране вашего проживания.',
  'legalPrivacy1Heading': '1. Введение',
  'legalPrivacy1Body': 'Настоящая Политика конфиденциальности объясняет, как WWNGO собирает, использует, передаёт и защищает персональные данные, когда вы используете нашу площадку для прямой доставки посылок в качестве Отправителя, Путешественника и/или Получателя. Она применяется к первой регистрации и всем последующим использованиям той же учётной записи. Создавая учётную запись, вы подтверждаете согласие с настоящей Политикой. По вопросам обращайтесь на privacy@wwngo.com.',
  'legalPrivacy2Heading': '2. Данные, которые мы собираем',
  'legalPrivacy2Bullet1': 'Данные учётной записи: полное имя, адрес электронной почты, телефон (с кодом страны), пароль (хранится в виде хеша), страна, выбранная роль и добавляемые вами данные профиля.',
  'legalPrivacy2Bullet2': 'Данные проверки: статус одноразовых кодов для электронной почты и телефона; информация KYC, обрабатываемая Sumsub (документ, удостоверяющий личность, селфи, проверка живости и результат верификации). WWNGO хранит статус проверки и ссылки на неё, а не исходные изображения документов, за исключением случаев, когда это требуется процессом нашего партнёра по KYC.',
  'legalPrivacy2Bullet3': 'Данные о доставке: маршруты, даты, категория/размер/вес/описание посылки, фотографии, контактные данные Получателя, адреса встреч, предложения и встречные предложения, статус отправления, записи контрольных точек NFC, записи об отменах и спорах.',
  'legalPrivacy2Bullet4': 'Коммуникации: сообщения чата внутри приложения, вложения и письма службы поддержки.',
  'legalPrivacy2Bullet5': 'Платежи: единый баланс и реестр кошелька (доступные средства и эскроу), описания транзакций с метками ролей активности, идентификаторы платежей Stripe и Connect. Номера карт обрабатываются Stripe и не хранятся на серверах WWNGO.',
  'legalPrivacy2Bullet6': 'Устройство и использование: версия приложения, тип устройства, IP-адрес, журналы сбоев и токены push-уведомлений (FCM) для доставки оповещений.',
  'legalPrivacy3Heading': '3. Как мы используем ваши данные',
  'legalPrivacy3Bullet1': 'Создание и защита вашей учётной записи, а также предоставление возможности переключаться между ролями Отправителя, Путешественника и Получателя.',
  'legalPrivacy3Bullet2': 'Сопоставление посылок с поездками, отображение объявлений и обработка предложений, таймеров и блокировок бронирования.',
  'legalPrivacy3Bullet3': 'Взимание комиссий платформы, удержание средств Отправителя в эскроу, выплата средств Путешественникам после контрольной точки NFC 2, и обработка возвратов при отмене или споре.',
  'legalPrivacy3Bullet4': 'Обеспечение координации встреч, чата, отслеживания, подтверждения NFC, отзывов и уведомлений.',
  'legalPrivacy3Bullet5': 'Предотвращение мошенничества, обеспечение соблюдения настоящих Условий, рассмотрение споров и выполнение юридических обязательств.',
  'legalPrivacy3Bullet6': 'Повышение надёжности и качества поддержки клиентов. Мы не продаём ваши персональные данные.',
  'legalPrivacy4Heading': '4. Обмен данными по ролям в рамках доставки',
  'legalPrivacy4Body': 'Для завершения бронирования ограниченная информация о профиле и доставке отображается только другим сторонам данного отправления — например, имена, оценки, маршрут, сводка по посылке, статус встречи и чат. Путешественник не получает полные данные вашей платёжной карты. Получатель видит только то, что необходимо для принятия и получения посылки. После доставки или отмены доступ регулируется правилами продукта (история, отзывы, материалы по спорам).',
  'legalPrivacy5Heading': '5. Обработчики данных и третьи лица',
  'legalPrivacy5Bullet1': 'Sumsub — проверка личности (KYC).',
  'legalPrivacy5Bullet2': 'Stripe — пополнение кошелька, платёжные намерения и выплаты через Connect.',
  'legalPrivacy5Bullet3': 'Firebase Cloud Messaging — push-уведомления.',
  'legalPrivacy5Bullet4': 'Поставщики услуг электронной почты/SMS — одноразовые коды и транзакционные письма.',
  'legalPrivacy5Bullet5': 'Поставщики хостинга и баз данных, обрабатывающие данные по нашим инструкциям.',
  'legalPrivacy5Bullet6': 'Государственные органы — при наличии законных требований или для защиты пользователей от серьёзного вреда.',
  'legalPrivacy6Heading': '6. Хранение, безопасность и международная передача',
  'legalPrivacy6Body': 'Мы храним записи об учётной записи, реестре, доставке, NFC и спорах в течение всего времени существования вашей учётной записи и в течение разумного периода после этого — для завершения выплат, обработки возвратов платежей через банк и выполнения бухгалтерских и юридических обязанностей. Мы используем шифрование при передаче данных, контроль доступа и единую систему учёта кошелька. Данные могут обрабатываться в странах, отличных от вашей; мы применяем соответствующие меры защиты в отношении обработчиков данных. Ни один метод передачи данных не является безопасным на 100%.',
  'legalPrivacy7Heading': '7. Ваши права',
  'legalPrivacy7Body': 'В соответствии с применимым законодательством вы можете запросить доступ, исправление, удаление, ограничение обработки или экспорт своих персональных данных, а также возразить против определённых видов обработки. Вы можете отозвать согласие в случаях, когда обработка основана на согласии (это не влияет на законность предыдущей обработки). Некоторые записи (эскроу, статус KYC, завершённые реестры) могут храниться, если мы обязаны их сохранять. Обращайтесь на privacy@wwngo.com. Вы также можете подать жалобу в местный орган по защите данных.',
  'legalPrivacy8Heading': '8. Дети, изменения и контакты',
  'legalPrivacy8Body': 'WWNGO не предназначен для детей младше 18 лет. Мы сознательно не собираем их данные. Мы можем обновлять настоящую Политику и будем публиковать новую дату в приложении. О существенных изменениях может быть сообщено в приложении или по электронной почте. Контакты: privacy@wwngo.com (по вопросам конфиденциальности) или support@wwngo.com (по общим вопросам).',
  'legalCookie1Heading': 'Что такое файлы cookie?',
  'legalCookie1Body': 'Файлы cookie — это небольшие текстовые файлы, хранящиеся на вашем устройстве. Они помогают запоминать предпочтения и понимать, как вы используете наш сайт.',
